const REPDB=[{"id":"ab-wheel-rollout","n":"Roulette abdominale","en":"Ab Wheel Rollout","c":"strength","eq":"ab_wheel","pm":["rectus_abdominis","transverse_abdominis"],"sm":["anterior_deltoid","latissimus_dorsi","obliques","serratus_anterior"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — roulette abdo. Travaille surtout : Grand droit (abdominaux), Transverse. En soutien : Deltoïde antérieur, Grand dorsal, Obliques, Dentelé antérieur.","ins":["Kneel on the floor and grip the ab wheel handles shoulder-width.","Brace the core hard so the lower back stays neutral.","Roll the wheel slowly forward, extending the body as far as you can control.","Stop before the hips sag or the back arches.","Pull the wheel back to the knees by contracting the abs."],"met":6.0},{"id":"air-bike","n":"Vélo à air (air bike)","en":"Air Bike","c":"cardio","eq":"air_bike","pm":["hamstrings","quadriceps"],"sm":["gluteus_maximus","latissimus_dorsi","pectoralis_major","rectus_abdominis"],"d":"intermediate","bw":false,"uni":false,"img":["main"],"desc":"Exercice cardio — vélo à air. Travaille surtout : Ischio-jambiers, Quadriceps. En soutien : Grand fessier, Grand dorsal, Pectoraux, Grand droit (abdominaux).","ins":["Sit on the air bike and grip the moving handles.","Place your feet on the pedals and brace your core.","Push and pull the handles while pedaling at a steady pace.","Drive with both arms and legs to maintain power output.","Continue for the desired duration or distance."],"met":8.0},{"id":"archer-pull-ups","n":"Tractions archer","en":"Archer Pull Ups","c":"strength","eq":"pull_up_bar","pm":["latissimus_dorsi"],"sm":["biceps_brachii","forearm_flexors","posterior_deltoid","rhomboids"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre de traction. Travaille surtout : Grand dorsal. En soutien : Biceps, Fléchisseurs de l'avant-bras, Deltoïde postérieur, Rhomboïdes.","ins":["Grip the bar wider than shoulder width with palms facing away.","Pull yourself up while shifting your body toward one hand.","Keep the opposite arm straight as a support.","Lower yourself under control back to the hang.","Alternate sides each rep or complete reps on one side first."],"met":6.0},{"id":"archer-push-ups","n":"Pompes archer","en":"Archer Push Ups","c":"strength","eq":"","pm":["pectoralis_major"],"sm":["anterior_deltoid","rectus_abdominis","serratus_anterior","triceps_brachii"],"d":"advanced","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Grand droit (abdominaux), Dentelé antérieur, Triceps.","ins":["Set up in a wide push-up position with arms straight.","Lower yourself toward one hand while keeping the other arm straight.","Keep your core tight and body in a straight line.","Press back up to the start position.","Alternate sides each rep for the desired number of reps."],"met":5.0},{"id":"arnold-press","n":"Développé Arnold","en":"Arnold Press","c":"strength","eq":"dumbbell","pm":["anterior_deltoid","lateral_deltoid"],"sm":["serratus_anterior","trapezius","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Dentelé antérieur, Trapèzes, Triceps.","ins":["Hold a pair of dumbbells at shoulder height with palms facing you.","Press the dumbbells overhead while rotating your palms to face forward.","Fully extend your arms at the top without locking the elbows.","Reverse the motion and rotate back to the start.","Repeat for the desired number of reps."],"met":6.0},{"id":"assisted-dips","n":"Dips assistés à la machine","en":"Machine Assisted Dips","c":"strength","eq":"dip_machine","pm":["pectoralis_major","triceps_brachii"],"sm":["anterior_deltoid","rhomboids"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — machine à dips. Travaille surtout : Pectoraux, Triceps. En soutien : Deltoïde antérieur, Rhomboïdes.","ins":["Step onto the assisted dip machine with knees on the pad.","Grip the parallel bars and support your weight with straight arms.","Lower your body by bending your elbows until shoulders are below elbows.","Press back up to the start position.","Repeat for the desired number of reps."],"met":6.0},{"id":"assisted-pull-ups","n":"Tractions assistées","en":"Assisted Pull Ups","c":"strength","eq":"assisted_pullup_machine","pm":["latissimus_dorsi"],"sm":["biceps_brachii","forearm_flexors","posterior_deltoid","rhomboids"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — machine de tractions assistées. Travaille surtout : Grand dorsal. En soutien : Biceps, Fléchisseurs de l'avant-bras, Deltoïde postérieur, Rhomboïdes.","ins":["Place your knees on the assisted pull-up machine pad.","Grip the bar with palms facing away, slightly wider than shoulders.","Pull your chest toward the bar by driving your elbows down.","Lower yourself under control to a full hang.","Repeat for the desired number of reps."],"met":6.0},{"id":"back-extension","n":"Extension lombaire","en":"Back Extension","c":"strength","eq":"","pm":["erector_spinae"],"sm":["gluteus_maximus","hamstrings"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis). En soutien : Grand fessier, Ischio-jambiers.","ins":["Lie face down on a hyperextension bench with hips at the pad edge.","Lower your upper body toward the floor.","Raise your torso back up until your body is straight.","Repeat."],"met":3.5},{"id":"back-lever","n":"Back lever","en":"Back Lever","c":"strength","eq":"pull_up_bar","pm":["erector_spinae","latissimus_dorsi"],"sm":["anterior_deltoid","gluteus_maximus","rectus_abdominis"],"d":"advanced","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — barre de traction. Travaille surtout : Lombaires (érecteurs du rachis), Grand dorsal. En soutien : Deltoïde antérieur, Grand fessier, Grand droit (abdominaux).","ins":["Hang from a bar with an overhand grip and rotate backward through the arms until inverted.","Lower the body forward and down until it is horizontal, facing the floor.","Keep the arms straight and the whole body in one rigid line from head to heels.","Brace the core and squeeze the glutes so the hips and shoulders do not sag.","Hold for time, then rotate back up under control."],"met":6.0},{"id":"ball-leg-curl","n":"Leg curl sur ballon","en":"Stability Ball Leg Curl","c":"strength","eq":"stability_ball","pm":["hamstrings"],"sm":["gastrocnemius","gluteus_maximus"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — ballon de gym. Travaille surtout : Ischio-jambiers. En soutien : Mollets (gastrocnémiens), Grand fessier.","ins":["Lie face-up on the floor with your heels and lower calves on top of a stability ball, arms out for balance.","Press through the heels to raise your hips into a straight line from shoulders to ankles.","Keeping the hips up, bend the knees to roll the ball toward your glutes.","Extend the legs back out under control without dropping the hips.","Complete all reps, then lower the hips and step off the ball."],"met":5.0},{"id":"ball-pike","n":"Pike sur ballon","en":"Ball Pike","c":"strength","eq":"stability_ball","pm":["obliques","rectus_abdominis"],"sm":["anterior_deltoid","hip_flexors","serratus_anterior"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — ballon de gym. Travaille surtout : Obliques, Grand droit (abdominaux). En soutien : Deltoïde antérieur, Fléchisseurs de hanche, Dentelé antérieur.","ins":["Place the shins on a stability ball and hands on the floor in a high plank.","Brace the core and keep the legs straight.","Pike the hips up, rolling the ball toward the chest as the body forms an inverted V.","Pause briefly at the top.","Roll the ball back out to the starting plank."],"met":6.0},{"id":"band-assisted-pull-ups","n":"Tractions assistées à l'élastique","en":"Band Assisted Pull Ups","c":"strength","eq":"resistance_band","pm":["latissimus_dorsi"],"sm":["biceps_brachii","forearm_flexors","posterior_deltoid","rhomboids"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — élastique. Travaille surtout : Grand dorsal. En soutien : Biceps, Fléchisseurs de l'avant-bras, Deltoïde postérieur, Rhomboïdes.","ins":["Loop a resistance band over the pull-up bar and step one foot into it.","Grip the bar with palms facing away, shoulder-width apart.","Pull your chest toward the bar by driving your elbows down.","Lower yourself under control to a full hang.","Repeat for the desired number of reps."],"met":6.0},{"id":"band-pull-apart","n":"Écartés d'élastique (band pull apart)","en":"Band Pull Apart","c":"strength","eq":"resistance_band","pm":["posterior_deltoid"],"sm":["rhomboids","trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — élastique. Travaille surtout : Deltoïde postérieur. En soutien : Rhomboïdes, Trapèzes.","ins":["Stand holding a light resistance band with both hands, arms extended straight in front at shoulder height.","Hands start shoulder-width apart, palms facing down.","Keeping arms straight, pull the band apart by driving the hands out to the sides.","Finish with the band touching your chest and the shoulder blades squeezed together.","Return slowly to the starting position and repeat."],"met":5.0},{"id":"banded-adductor-stretch","n":"Étirement des adducteurs à l'élastique","en":"Banded Adductor Stretch","c":"stretching","eq":"resistance_band","pm":["adductors"],"sm":["hamstrings"],"d":"beginner","bw":false,"uni":true,"img":["main"],"desc":"Étirement — élastique. Travaille surtout : Adducteurs. En soutien : Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Lie on your back with a band looped around one foot.","Raise that leg and let it open out to the side.","Hold the band to control how far the leg lowers.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"banded-ankle-stretch","n":"Étirement de la cheville à l'élastique","en":"Banded Ankle Stretch","c":"stretching","eq":"resistance_band","pm":["gastrocnemius"],"sm":["soleus"],"d":"beginner","bw":false,"uni":true,"img":["main"],"desc":"Étirement — élastique. Travaille surtout : Mollets (gastrocnémiens). En soutien : Soléaire. Se fait d'un côté puis de l'autre.","ins":["Sit with one leg extended and a band around the forefoot.","Hold the band in both hands.","Pull so the toes draw back toward your shin.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"banded-calf-stretch","n":"Étirement des mollets à l'élastique","en":"Banded Calf Stretch","c":"stretching","eq":"resistance_band","pm":["gastrocnemius"],"sm":["soleus"],"d":"beginner","bw":false,"uni":true,"img":["main"],"desc":"Étirement — élastique. Travaille surtout : Mollets (gastrocnémiens). En soutien : Soléaire. Se fait d'un côté puis de l'autre.","ins":["Lie on your back and loop a band around the ball of one foot.","Raise the leg and keep it fairly straight.","Pull the band so your toes draw back toward your shin.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"banded-chest-stretch","n":"Étirement des pectoraux à l'élastique","en":"Banded Chest Stretch","c":"stretching","eq":"resistance_band","pm":["pectoralis_major"],"sm":["anterior_deltoid"],"d":"beginner","bw":false,"uni":false,"img":["main"],"desc":"Étirement — élastique. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur.","ins":["Hold a band behind your back with both hands.","Straighten your arms and draw them apart.","Lift your chest and squeeze your shoulder blades.","Hold for 20 to 30 seconds, breathing steadily."],"met":5.0},{"id":"banded-clamshell","n":"Clamshell avec élastique","en":"Banded Clamshell","c":"strength","eq":"loop_band","pm":["gluteus_medius"],"sm":["gluteus_maximus"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — mini-bande élastique. Travaille surtout : Moyen fessier. En soutien : Grand fessier.","ins":["Lie on your side with hips and knees bent to roughly 45 degrees, feet stacked.","Place a loop band around both legs above the knees.","Keep the feet pressed together and the pelvis stable — do not roll back as you move.","Open the top knee upward against the band, like a clamshell opening, until you feel the glute fire.","Pause briefly at the top, then lower under control to the start.","Complete all reps on one side, then switch."],"met":5.0},{"id":"banded-figure-4-stretch","n":"Étirement en 4 à l'élastique","en":"Banded Figure-4 Stretch","c":"stretching","eq":"resistance_band","pm":["gluteus_maximus"],"sm":["gluteus_medius"],"d":"beginner","bw":false,"uni":true,"img":["main"],"desc":"Étirement — élastique. Travaille surtout : Grand fessier. En soutien : Moyen fessier. Se fait d'un côté puis de l'autre.","ins":["Lie on your back and cross one ankle over the opposite thigh.","Loop a band around the supporting thigh.","Pull both legs toward your chest with the band.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"banded-fire-hydrant","n":"Fire hydrant avec élastique","en":"Banded Fire Hydrant","c":"strength","eq":"loop_band","pm":["gluteus_medius"],"sm":["gluteus_maximus"],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — mini-bande élastique. Travaille surtout : Moyen fessier. En soutien : Grand fessier. Se fait d'un côté puis de l'autre.","ins":["Place a loop band just above your knees and assume a quadruped position with hands under shoulders and knees under hips.","Keep your core engaged and back flat, maintaining a neutral spine throughout the movement.","Slowly lift one knee out to the side, keeping the knee bent at 90 degrees, until your thigh is parallel to the floor.","Hold briefly at the top, squeezing your glute, then slowly lower your leg back to the starting position with control.","Complete all repetitions on one side before switching to the other side."],"met":5.0},{"id":"banded-glute-bridge","n":"Pont fessier avec élastique","en":"Banded Glute Bridge","c":"strength","eq":"loop_band","pm":["gluteus_maximus"],"sm":["gluteus_medius","hamstrings"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — mini-bande élastique. Travaille surtout : Grand fessier. En soutien : Moyen fessier, Ischio-jambiers.","ins":["Lie on your back with the knees bent and feet flat on the floor, shoulder-width apart.","Place a loop band around both legs just above the knees.","Press the lower back into the floor and brace the core.","Drive through the heels and squeeze the glutes to lift the hips into a bridge — keep the band tension by pushing the knees outward.","At the top, the body forms a straight line from shoulders to knees. Pause briefly.","Lower under control to the start and repeat for the recommended number of repetitions."],"met":6.0},{"id":"banded-good-morning","n":"Good morning à l'élastique","en":"Banded Good Morning","c":"strength","eq":"loop_band","pm":["gluteus_maximus","hamstrings"],"sm":["erector_spinae"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — mini-bande élastique. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis).","ins":["Stand on a loop band with both feet and pass it over the back of your neck.","Set feet hip-width with a soft bend in the knees.","Hinge at the hips, pushing them back with a flat back.","Lower until you feel a stretch in the hamstrings.","Drive the hips forward to return to standing."],"met":6.0},{"id":"banded-hamstring-stretch","n":"Étirement des ischios à l'élastique","en":"Banded Hamstring Stretch","c":"stretching","eq":"resistance_band","pm":["hamstrings"],"sm":["gastrocnemius"],"d":"beginner","bw":false,"uni":true,"img":["main"],"desc":"Étirement — élastique. Travaille surtout : Ischio-jambiers. En soutien : Mollets (gastrocnémiens). Se fait d'un côté puis de l'autre.","ins":["Lie on your back and loop a band around one foot.","Raise that leg straight up, holding the band in both hands.","Gently pull the band to draw the leg toward you.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"banded-hip-thrust","n":"Hip thrust avec élastique","en":"Banded Hip Thrust","c":"strength","eq":"loop_band","pm":["gluteus_maximus"],"sm":["gluteus_medius","hamstrings"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — mini-bande élastique. Travaille surtout : Grand fessier. En soutien : Moyen fessier, Ischio-jambiers.","ins":["Place a loop band just above your knees and sit on the floor with your upper back against a bench.","Bend your knees, plant your feet hip-width apart, and position the band to create tension.","Drive through your heels, extend your hips, and lift your glutes off the floor until your body forms a straight line from shoulders to knees.","Squeeze your glutes forcefully at the top, ensuring your knees are pushed out against the band.","Slowly lower your hips back to the starting position with control."],"met":6.0},{"id":"banded-it-band-stretch","n":"Étirement de la bandelette ilio-tibiale à l'élastique","en":"Banded IT-Band Stretch","c":"stretching","eq":"resistance_band","pm":["abductors"],"sm":["gluteus_maximus","gluteus_medius"],"d":"beginner","bw":false,"uni":true,"img":["main"],"desc":"Étirement — élastique. Travaille surtout : Abducteurs. En soutien : Grand fessier, Moyen fessier. Se fait d'un côté puis de l'autre.","ins":["Lie on your back with a band around one raised foot.","Hold the band with the opposite hand.","Draw the straight leg across your body toward the floor.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"banded-kneeling-hip-thrust","n":"Hip thrust à genoux avec élastique","en":"Banded Kneeling Hip Thrust","c":"strength","eq":"loop_band","pm":["gluteus_maximus"],"sm":["hamstrings"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — mini-bande élastique. Travaille surtout : Grand fessier. En soutien : Ischio-jambiers.","ins":["Place a loop band just above your knees. Kneel on the floor with your torso upright and knees hip-width apart.","Lean slightly forward from your hips, keeping your back straight and core braced.","Initiate the movement by squeezing your glutes, driving your hips forward until your torso is upright.","Squeeze your glutes hard at the top, maintaining tension on the band.","Slowly reverse the movement, controlling the band's resistance as you return to the starting position."],"met":6.0},{"id":"banded-lat-stretch","n":"Étirement du grand dorsal à l'élastique","en":"Banded Lat Stretch","c":"stretching","eq":"resistance_band","pm":["latissimus_dorsi"],"sm":["posterior_deltoid"],"d":"beginner","bw":false,"uni":false,"img":["main"],"desc":"Étirement — élastique. Travaille surtout : Grand dorsal. En soutien : Deltoïde postérieur.","ins":["Hold a band overhead with both hands under light tension.","Hinge forward at the hips with your arms reaching ahead.","Let your chest sink to lengthen the sides of your back.","Hold for 20 to 30 seconds, breathing steadily."],"met":5.0},{"id":"banded-lateral-walk","n":"Marche latérale avec élastique","en":"Banded Lateral Walk","c":"strength","eq":"loop_band","pm":["gluteus_medius"],"sm":["gluteus_maximus","quadriceps"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique — mini-bande élastique. Travaille surtout : Moyen fessier. En soutien : Grand fessier, Quadriceps.","ins":["Place a loop band around the legs above the knees (or around the ankles for a harder version).","Stand in a quarter-squat: feet shoulder-width, hips back, chest up, knees tracking over the toes.","Step one foot directly out to the side against the band tension.","Bring the trailing foot in toward the lead — keep tension on the band the entire time, do not let the feet snap together.","Continue side-stepping in one direction for the prescribed reps or distance, then reverse.","Stay low throughout; do not pop up between steps."],"met":6.0},{"id":"banded-rear-delt-stretch","n":"Étirement de l'arrière d'épaule à l'élastique","en":"Banded Rear Delt Stretch","c":"stretching","eq":"resistance_band","pm":["posterior_deltoid"],"sm":["rhomboids","trapezius"],"d":"beginner","bw":false,"uni":true,"img":["main"],"desc":"Étirement — élastique. Travaille surtout : Deltoïde postérieur. En soutien : Rhomboïdes, Trapèzes. Se fait d'un côté puis de l'autre.","ins":["Loop a band around one arm and hold the other end.","Draw that arm horizontally across your chest.","Use the band to deepen the pull gently.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"banded-romanian-deadlift","n":"Soulevé de terre roumain à l'élastique","en":"Banded Romanian Deadlift","c":"strength","eq":"loop_band","pm":["gluteus_maximus","hamstrings"],"sm":["erector_spinae"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — mini-bande élastique. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis).","ins":["Stand on a loop band with both feet and grip the top of the band.","Set feet hip-width with a soft bend in the knees.","Hinge at the hips, sliding the hands down the legs.","Lower until you feel a stretch in the hamstrings.","Drive the hips forward to return to standing."],"met":6.0},{"id":"banded-seated-hip-abduction","n":"Abduction de hanche assise avec élastique","en":"Banded Seated Hip Abduction","c":"strength","eq":"loop_band","pm":["gluteus_medius"],"sm":["gluteus_maximus"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — mini-bande élastique. Travaille surtout : Moyen fessier. En soutien : Grand fessier.","ins":["Sit on a bench or chair with a loop band around your knees.","Keep your feet flat on the floor, hip-width apart, and maintain an upright posture.","Push your knees outwards against the band, engaging your glutes.","Hold the peak contraction briefly, then slowly return your knees to the starting position.","Control the movement throughout the entire range of motion."],"met":5.0},{"id":"banded-shoulder-stretch","n":"Étirement d'épaule à l'élastique","en":"Banded Shoulder Stretch","c":"stretching","eq":"resistance_band","pm":["anterior_deltoid"],"sm":["pectoralis_major"],"d":"beginner","bw":false,"uni":false,"img":["main"],"desc":"Étirement — élastique. Travaille surtout : Deltoïde antérieur. En soutien : Pectoraux.","ins":["Hold a band behind your back, one hand high and one low.","Keep light tension in the band.","Open your chest and draw your shoulders gently back.","Hold for 20 to 30 seconds, breathing steadily."],"met":5.0},{"id":"banded-squat","n":"Squat avec élastique","en":"Banded Squat","c":"strength","eq":"loop_band","pm":["gluteus_maximus","quadriceps"],"sm":["gluteus_medius","hamstrings"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — mini-bande élastique. Travaille surtout : Grand fessier, Quadriceps. En soutien : Moyen fessier, Ischio-jambiers.","ins":["Place a loop band just above the knees.","Stand with feet shoulder-width apart, toes slightly out.","Push the knees out against the band as you squat down.","Descend until thighs are parallel or below.","Drive through the heels to stand back up."],"met":6.0},{"id":"banded-standing-curl","n":"Leg curl debout à l'élastique","en":"Banded Standing Leg Curl","c":"strength","eq":"loop_band","pm":["hamstrings"],"sm":["gastrocnemius"],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — mini-bande élastique. Travaille surtout : Ischio-jambiers. En soutien : Mollets (gastrocnémiens). Se fait d'un côté puis de l'autre.","ins":["Loop a resistance band around one ankle and anchor the other end under your standing foot or a fixed point in front of you.","Stand tall, holding onto something for balance if needed, with a slight bend in the standing knee.","Curl the banded heel up and back toward your glute, keeping the thigh still.","Squeeze the hamstring at the top, then lower under control to a full stretch.","Complete all reps on one side, then switch legs."],"met":5.0},{"id":"banded-standing-hip-abduction","n":"Abduction de hanche debout avec élastique","en":"Banded Standing Hip Abduction","c":"strength","eq":"loop_band","pm":["gluteus_medius"],"sm":["gluteus_maximus"],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — mini-bande élastique. Travaille surtout : Moyen fessier. En soutien : Grand fessier. Se fait d'un côté puis de l'autre.","ins":["Place a loop band around your ankles or just above your knees.","Stand tall with a slight bend in your knees and brace your core.","Shift your weight onto one leg, maintaining a stable torso.","Slowly abduct the free leg out to the side, feeling the glute contract.","Control the movement as you return the leg to the starting position.","Complete all reps per side before switching."],"met":5.0},{"id":"banded-standing-hip-adduction","n":"Adduction de hanche debout avec élastique","en":"Banded Standing Hip Adduction","c":"strength","eq":"loop_band","pm":["adductors"],"sm":[],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — mini-bande élastique. Travaille surtout : Adducteurs. Se fait d'un côté puis de l'autre.","ins":["Anchor a loop band to a sturdy upright at ankle height.","Step into the loop with the working leg facing the anchor side.","Stand a few feet away so the band has tension.","Sweep the working leg across the body toward the standing leg.","Return slowly to the start. Complete reps per side, then switch."],"met":5.0},{"id":"banded-sumo-walk","n":"Marche sumo avec élastique","en":"Banded Sumo Walk","c":"strength","eq":"loop_band","pm":["gluteus_maximus","gluteus_medius"],"sm":["quadriceps"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — mini-bande élastique. Travaille surtout : Grand fessier, Moyen fessier. En soutien : Quadriceps.","ins":["Place a loop band just above the knees.","Drop into a quarter squat with feet wider than shoulder-width.","Step forward in a wide stance, keeping tension on the band.","Continue stepping forward, alternating feet, for the prescribed distance.","Stay low throughout — do not stand up between steps."],"met":6.0},{"id":"banded-terminal-knee-extension","n":"Extension terminale du genou à l'élastique","en":"Banded Terminal Knee Extension","c":"strength","eq":"loop_band","pm":["quadriceps"],"sm":[],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — mini-bande élastique. Travaille surtout : Quadriceps. Se fait d'un côté puis de l'autre.","ins":["Anchor a loop band to a sturdy upright at knee height.","Step into the loop so the band sits behind one knee.","Step back so the band pulls the knee into a slight bend.","Extend the knee fully against the band, contracting the quad.","Return slowly. Complete reps per side, then switch."],"met":5.0},{"id":"banded-triceps-stretch","n":"Étirement des triceps à l'élastique","en":"Banded Triceps Stretch","c":"stretching","eq":"resistance_band","pm":["triceps_brachii"],"sm":["latissimus_dorsi"],"d":"beginner","bw":false,"uni":true,"img":["main"],"desc":"Étirement — élastique. Travaille surtout : Triceps. En soutien : Grand dorsal. Se fait d'un côté puis de l'autre.","ins":["Hold a band that runs down your back, top hand behind your head.","Anchor the lower hand at your lower back.","Reach the top hand down to feel the triceps lengthen.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"barbell-ab-rollout","n":"Roulette abdominale à la barre","en":"Barbell Ab Rollout","c":"strength","eq":"barbell","pm":["rectus_abdominis"],"sm":["latissimus_dorsi","obliques","transverse_abdominis"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique — barre. Travaille surtout : Grand droit (abdominaux). En soutien : Grand dorsal, Obliques, Transverse.","ins":["Load plates of equal size on both ends of a barbell and place it on the floor.","Kneel behind the bar and grip it shoulder-width, arms extended.","Brace the core hard, then roll the bar forward away from your body.","Go as far as you can keep a neutral spine — stop before the hips sag.","Pull the bar back to the starting position by contracting the abs and lats.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"barbell-bulgarian-split-squat","n":"Squat bulgare à la barre","en":"Barbell Bulgarian Split Squat","c":"strength","eq":"barbell","pm":["gluteus_maximus","quadriceps"],"sm":["adductors","erector_spinae","gluteus_medius","hamstrings"],"d":"advanced","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Grand fessier, Quadriceps. En soutien : Adducteurs, Lombaires (érecteurs du rachis), Moyen fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Set a barbell across the upper back and stand about two feet in front of a flat bench, facing away from it.","Place the top of one foot on the bench behind you, with the front foot far enough forward to keep the shin close to vertical when you lower.","Brace the trunk and lower the back knee toward the floor by bending the front hip and knee.","Descend until the front thigh is about parallel to the floor, keeping the chest up.","Drive through the middle of the front foot to return to the start.","Complete the repetitions on one leg, then switch."],"met":6.0},{"id":"barbell-calf-raise","n":"Mollets debout à la barre","en":"Barbell Calf Raise","c":"strength","eq":"barbell","pm":["gastrocnemius"],"sm":["soleus"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — barre. Travaille surtout : Mollets (gastrocnémiens). En soutien : Soléaire.","ins":["Place a barbell across your upper back as in a squat.","Stand with the balls of your feet on a raised platform.","Push up onto your toes as high as possible.","Pause and squeeze your calves at the top.","Lower your heels below the platform and repeat."],"met":5.0},{"id":"barbell-curl","n":"Curl à la barre","en":"Barbell Curl","c":"strength","eq":"barbell","pm":["biceps_brachii"],"sm":["brachialis","forearm_flexors"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre. Travaille surtout : Biceps. En soutien : Brachial, Fléchisseurs de l'avant-bras.","ins":["Stand holding a barbell with a shoulder-width underhand grip.","Curl the bar up toward your shoulders.","Squeeze at the top, then lower under control.","Repeat."],"met":5.0},{"id":"barbell-front-raise","n":"Élévation frontale à la barre","en":"Barbell Front Raise","c":"strength","eq":"barbell","pm":["anterior_deltoid"],"sm":["lateral_deltoid","pectoralis_major","serratus_anterior"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — barre. Travaille surtout : Deltoïde antérieur. En soutien : Deltoïde latéral, Pectoraux, Dentelé antérieur.","ins":["Stand holding a barbell with an overhand grip at thigh level.","Keep your arms straight and core braced.","Raise the barbell in front of you to shoulder height.","Pause briefly at the top.","Lower under control and repeat."],"met":5.0},{"id":"barbell-glute-bridge","n":"Pont fessier à la barre","en":"Barbell Glute Bridge","c":"strength","eq":"barbell","pm":["gluteus_maximus"],"sm":["hamstrings"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Grand fessier. En soutien : Ischio-jambiers.","ins":["Lie on the floor with a barbell across your hips and knees bent.","Drive your hips up by squeezing your glutes.","Hold at the top with hips fully extended.","Lower with control.","Repeat."],"met":6.0},{"id":"barbell-lunge","n":"Fente à la barre","en":"Barbell Lunge","c":"strength","eq":"barbell","pm":["gluteus_maximus","quadriceps"],"sm":["erector_spinae","gluteus_medius","hamstrings"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Moyen fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Place a barbell across your upper back and stand tall.","Step forward with one leg into a long stride.","Lower your back knee toward the ground until your front thigh is parallel.","Drive through your front heel to return to standing.","Complete reps on one side, then switch."],"met":6.0},{"id":"barbell-overhead-extension","n":"Extension triceps au-dessus de la tête à la barre","en":"Barbell Overhead Extension","c":"strength","eq":"barbell","pm":["triceps_brachii"],"sm":[],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — barre. Travaille surtout : Triceps.","ins":["Load a barbell with an appropriate weight and stand or sit with a neutral spine.","Grip the barbell with an overhand, shoulder-width grip, and press it overhead.","Slowly lower the barbell behind your head by flexing your elbows, keeping your upper arms stable.","Extend your elbows to press the barbell back to the starting overhead position, squeezing your triceps.","Maintain control throughout the movement, avoiding momentum."],"met":5.0},{"id":"barbell-preacher-curl","n":"Curl pupitre à la barre","en":"Barbell Preacher Curl","c":"strength","eq":"barbell","pm":["biceps_brachii"],"sm":["brachialis"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre. Travaille surtout : Biceps. En soutien : Brachial.","ins":["Sit on a preacher bench with your chest against the pad, gripping a barbell with an underhand, shoulder-width grip.","Position your upper arms firmly against the pad, ensuring your elbows are slightly bent at the start.","Curl the barbell upwards by contracting your biceps, keeping your upper arms stationary on the pad.","Squeeze your biceps at the top of the movement, focusing on peak contraction.","Slowly lower the barbell back to the starting position, controlling the eccentric phase.","Fully extend your arms at the bottom to achieve a complete stretch in the biceps."],"met":5.0},{"id":"barbell-pullover","n":"Pull-over à la barre","en":"Barbell Pullover","c":"strength","eq":"barbell","pm":["latissimus_dorsi","pectoralis_major"],"sm":["triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre. Travaille surtout : Grand dorsal, Pectoraux. En soutien : Triceps.","ins":["Lie across a bench with a barbell held over your chest.","Lower the bar back over your head in an arc.","Pull it back to the start over your chest.","Repeat."],"met":6.0},{"id":"barbell-rear-delt-row","n":"Rowing arrière d'épaule à la barre","en":"Barbell Rear Delt Row","c":"strength","eq":"barbell","pm":["posterior_deltoid"],"sm":["latissimus_dorsi","rhomboids","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre. Travaille surtout : Deltoïde postérieur. En soutien : Grand dorsal, Rhomboïdes, Trapèzes.","ins":["Hinge at the hips with a flat back until your torso is nearly parallel to the floor.","Hold a barbell with an overhand, wider-than-shoulder-width grip, arms hanging.","Row the bar up toward your upper chest with the elbows flaring out to the sides.","Pause and squeeze the rear delts and upper back at the top.","Lower the bar under control and repeat."],"met":6.0},{"id":"barbell-reverse-lunge","n":"Fente arrière à la barre","en":"Barbell Reverse Lunge","c":"strength","eq":"barbell","pm":["gluteus_maximus","quadriceps"],"sm":["erector_spinae","gluteus_medius","hamstrings"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Moyen fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Place a barbell across your upper back and stand tall.","Step one foot backward into a long stride.","Lower your back knee toward the ground under control.","Drive through your front heel to return to standing.","Complete reps on one side, then switch."],"met":6.0},{"id":"barbell-row","n":"Rowing buste penché à la barre","en":"Bent-Over Barbell Row","c":"strength","eq":"barbell","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","posterior_deltoid"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Deltoïde postérieur.","ins":["Hinge at the hips with a slight knee bend.","Grip the bar slightly wider than shoulder-width.","Pull the bar to your lower chest, squeezing your shoulder blades.","Lower the bar under control.","Repeat."],"met":6.0},{"id":"barbell-wrist-curl","n":"Curl poignets à la barre","en":"Barbell Wrist Curl","c":"strength","eq":"barbell","pm":["forearm_flexors"],"sm":[],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre. Travaille surtout : Fléchisseurs de l'avant-bras.","ins":["Sit on a bench with forearms resting on the thighs, palms up.","Hold a barbell with hands shoulder-width, wrists hanging off the knees.","Let the bar roll down to the fingertips at the bottom.","Curl the bar up by flexing the wrists.","Lower under control."],"met":5.0},{"id":"battle-rope-double-slam","n":"Double slam à la corde ondulatoire","en":"Battle Rope Double Slam","c":"cardio","eq":"battle_rope","pm":["anterior_deltoid","latissimus_dorsi"],"sm":["forearm_flexors","gluteus_maximus","obliques","quadriceps","rectus_abdominis","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice cardio — corde ondulatoire. Travaille surtout : Deltoïde antérieur, Grand dorsal. En soutien : Fléchisseurs de l'avant-bras, Grand fessier, Obliques, Quadriceps, Grand droit (abdominaux), Trapèzes.","ins":["Take one rope end in each hand and face the anchor, standing far enough back that the ropes have a slight slack.","Set your feet slightly wider than your hips and sit into a quarter squat with your chest up.","Swing both arms up together, letting the ropes rise in front of you as you extend through the hips.","Slam both ends down to the floor at the same time, hinging at the hips and driving through your lats.","Ride the rebound straight back into the next slam, keeping both arms moving in unison rather than alternating.","Keep slamming for the desired time or number of reps."],"met":10.3},{"id":"battle-ropes","n":"Cordes ondulatoires","en":"Battle Ropes","c":"cardio","eq":"battle_rope","pm":["anterior_deltoid","lateral_deltoid","latissimus_dorsi"],"sm":["forearm_flexors","quadriceps","rectus_abdominis","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["main"],"desc":"Exercice cardio — corde ondulatoire. Travaille surtout : Deltoïde antérieur, Deltoïde latéral, Grand dorsal. En soutien : Fléchisseurs de l'avant-bras, Quadriceps, Grand droit (abdominaux), Trapèzes.","ins":["Anchor the ropes to a fixed point and grab one end in each hand.","Step back so the ropes have moderate slack.","Drop into a quarter squat with feet shoulder-width.","Drive each arm up and down rapidly to send waves through the ropes.","Continue for the prescribed work interval."],"met":10.3},{"id":"bear-crawl","n":"Marche de l'ours","en":"Bear Crawl","c":"strength","eq":"","pm":["anterior_deltoid","rectus_abdominis"],"sm":["obliques","quadriceps","triceps_brachii"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Deltoïde antérieur, Grand droit (abdominaux). En soutien : Obliques, Quadriceps, Triceps.","ins":["Start on all fours with your hands under your shoulders and knees under your hips.","Tuck your toes and lift your knees a few centimeters off the floor.","Keeping your back flat and hips low, step your right hand and left foot forward together.","Then move your left hand and right foot, crawling forward in a controlled rhythm.","Keep your core braced and your hips from swaying side to side."],"met":5.0},{"id":"bear-plank-hold","n":"Gainage de l'ours","en":"Bear Plank Hold","c":"strength","eq":"","pm":["rectus_abdominis","transverse_abdominis"],"sm":["anterior_deltoid","obliques","quadriceps","serratus_anterior"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Grand droit (abdominaux), Transverse. En soutien : Deltoïde antérieur, Obliques, Quadriceps, Dentelé antérieur.","ins":["Start on hands and knees with the hands under the shoulders and the knees under the hips.","Tuck the toes under and brace the abdominals so the back is flat.","Press into the hands and lift the knees a couple of inches off the floor.","Hold the position with the hips level and the head in line with the spine.","Breathe steadily, then lower the knees to rest."],"met":5.0},{"id":"behind-the-back-barbell-shrug","n":"Haussements d'épaules barre dans le dos","en":"Behind the Back Barbell Shrug","c":"strength","eq":"barbell","pm":["trapezius"],"sm":["forearm_flexors","rhomboids"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre. Travaille surtout : Trapèzes. En soutien : Fléchisseurs de l'avant-bras, Rhomboïdes.","ins":["Stand holding a barbell behind your back with an overhand grip.","Keep your arms straight and chest up.","Shrug your shoulders straight up toward your ears.","Pause and squeeze at the top.","Lower under control and repeat."],"met":5.0},{"id":"behind-the-neck-lat-pulldown","n":"Tirage vertical nuque","en":"Behind-the-Neck Lat Pulldown","c":"strength","eq":"lat_pulldown_machine","pm":["latissimus_dorsi"],"sm":["posterior_deltoid","rhomboids","trapezius"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — machine tirage vertical. Travaille surtout : Grand dorsal. En soutien : Deltoïde postérieur, Rhomboïdes, Trapèzes.","ins":["Sit at a lat pulldown station with thighs secured under the pad.","Grip the bar with a wide, overhand grip — wider than shoulder-width.","Keep the torso upright and tuck the chin slightly forward.","Pull the bar down behind the head until it touches the base of the neck.","Return under control to the full overhead stretch.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"behind-the-neck-press","n":"Développé nuque","en":"Behind the Neck Press","c":"strength","eq":"barbell","pm":["anterior_deltoid","lateral_deltoid"],"sm":["trapezius","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Trapèzes, Triceps.","ins":["Sit or stand with a barbell resting on your upper traps behind your neck.","Grip the bar wider than shoulder width.","Press the bar straight up overhead until your arms are extended.","Lower the bar back to the starting position under control.","Repeat for the desired number of reps."],"met":6.0},{"id":"behind-the-neck-pull-ups","n":"Traction nuque","en":"Behind-the-Neck Pull-Up","c":"strength","eq":"pull_up_bar","pm":["latissimus_dorsi"],"sm":["biceps_brachii","posterior_deltoid","rhomboids","trapezius"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre de traction. Travaille surtout : Grand dorsal. En soutien : Biceps, Deltoïde postérieur, Rhomboïdes, Trapèzes.","ins":["Grip the pull-up bar with an overhand grip wider than shoulder-width and hang at full arm extension with your legs together.","Keep your torso vertical rather than leaning back, and pull your elbows down and out to the sides.","Continue pulling until the bar passes behind your head and the back of your neck comes level with it, without letting the bar touch your neck.","Lower yourself under control back to a full dead hang, keeping your head still rather than letting it snap forward.","Repeat for the desired number of reps."],"met":6.0},{"id":"bench-adductor-stretch","n":"Étirement des adducteurs sur banc","en":"Bench Adductor Stretch","c":"stretching","eq":"flat_bench","pm":["adductors"],"sm":["hamstrings"],"d":"beginner","bw":false,"uni":true,"img":["main"],"desc":"Étirement — banc. Travaille surtout : Adducteurs. En soutien : Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Stand side-on to a bench.","Rest one straight leg up on the bench out to the side.","Keep your torso upright and shift gently toward the bench.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"bench-ankle-stretch","n":"Étirement de la cheville sur banc","en":"Bench Ankle Stretch","c":"stretching","eq":"flat_bench","pm":["gastrocnemius"],"sm":["soleus"],"d":"beginner","bw":false,"uni":true,"img":["main"],"desc":"Étirement — banc. Travaille surtout : Mollets (gastrocnémiens). En soutien : Soléaire. Se fait d'un côté puis de l'autre.","ins":["Place one whole foot flat on top of a bench.","Keep your torso upright.","Drive that knee forward over your toes.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"bench-bulgarian-split-stretch","n":"Étirement squat bulgare sur banc","en":"Bench Bulgarian Split Stretch","c":"stretching","eq":"flat_bench","pm":["hip_flexors","quadriceps"],"sm":["gluteus_maximus"],"d":"beginner","bw":false,"uni":true,"img":["main"],"desc":"Étirement — banc. Travaille surtout : Fléchisseurs de hanche, Quadriceps. En soutien : Grand fessier. Se fait d'un côté puis de l'autre.","ins":["Rest the top of your rear foot on a bench behind you.","Set the front foot flat and bend that knee.","Sink your hips straight down.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"bench-calf-stretch","n":"Étirement des mollets sur banc","en":"Bench Calf Stretch","c":"stretching","eq":"flat_bench","pm":["gastrocnemius"],"sm":["soleus"],"d":"beginner","bw":false,"uni":true,"img":["main"],"desc":"Étirement — banc. Travaille surtout : Mollets (gastrocnémiens). En soutien : Soléaire. Se fait d'un côté puis de l'autre.","ins":["Place the ball of one foot on the edge of a bench.","Keep that knee straight.","Let your heel drop down below the toes.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"bench-chest-stretch","n":"Étirement des pectoraux sur banc","en":"Bench Chest Stretch","c":"stretching","eq":"flat_bench","pm":["pectoralis_major"],"sm":["anterior_deltoid"],"d":"beginner","bw":false,"uni":false,"img":["main"],"desc":"Étirement — banc. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur.","ins":["Kneel with your back to a bench.","Place both hands behind you on the edge of the bench.","Sink your hips down to open the chest.","Hold for 20 to 30 seconds, breathing steadily."],"met":5.0},{"id":"bench-childs-pose","n":"Posture de l'enfant sur banc","en":"Bench Child's Pose","c":"stretching","eq":"flat_bench","pm":["erector_spinae","latissimus_dorsi"],"sm":[],"d":"beginner","bw":false,"uni":false,"img":["main"],"desc":"Étirement — banc. Travaille surtout : Lombaires (érecteurs du rachis), Grand dorsal.","ins":["Kneel on the floor in front of a bench.","Extend both arms forward and rest them on the bench.","Sit your hips back toward your heels and let the chest sink.","Hold for 20 to 30 seconds, breathing steadily."],"met":5.0},{"id":"bench-couch-stretch","n":"Étirement du canapé sur banc","en":"Bench Couch Stretch","c":"stretching","eq":"flat_bench","pm":["hip_flexors","quadriceps"],"sm":[],"d":"beginner","bw":false,"uni":true,"img":["main"],"desc":"Étirement — banc. Travaille surtout : Fléchisseurs de hanche, Quadriceps. Se fait d'un côté puis de l'autre.","ins":["Kneel with your rear shin against the front of a bench.","Place the front foot flat on the floor.","Bring your torso upright until the front of the thigh stretches.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"bench-dips","n":"Dips sur banc","en":"Bench Dips","c":"strength","eq":"","pm":["triceps_brachii"],"sm":["anterior_deltoid","pectoralis_major"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Triceps. En soutien : Deltoïde antérieur, Pectoraux.","ins":["Sit on a bench and place your hands on the edge beside your hips.","Slide your hips off the bench with legs extended.","Lower your body by bending your elbows to 90 degrees.","Press through your palms to return to the start.","Repeat for the desired number of reps."],"met":5.0},{"id":"bench-figure-4-glute-stretch","n":"Étirement en 4 des fessiers sur banc","en":"Bench Figure-4 Glute Stretch","c":"stretching","eq":"flat_bench","pm":["gluteus_maximus"],"sm":["gluteus_medius"],"d":"beginner","bw":false,"uni":true,"img":["main"],"desc":"Étirement — banc. Travaille surtout : Grand fessier. En soutien : Moyen fessier. Se fait d'un côté puis de l'autre.","ins":["Sit on the end of a bench.","Cross one ankle over the opposite knee.","Keep your back flat and hinge forward over the crossed leg.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"bench-hamstring-stretch","n":"Étirement des ischios sur banc","en":"Bench Hamstring Stretch","c":"stretching","eq":"flat_bench","pm":["hamstrings"],"sm":["erector_spinae"],"d":"beginner","bw":false,"uni":true,"img":["main"],"desc":"Étirement — banc. Travaille surtout : Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis). Se fait d'un côté puis de l'autre.","ins":["Place one heel on a bench with that leg straight.","Stand tall on the supporting leg.","Hinge forward from the hips over the raised leg.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"bench-hollow-hold","n":"Hollow sur banc","en":"Bench Hollow Hold","c":"strength","eq":"flat_bench","pm":["hip_flexors","rectus_abdominis"],"sm":["obliques","quadriceps","transverse_abdominis"],"d":"intermediate","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — banc. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Obliques, Quadriceps, Transverse.","ins":["Lie on your back on a flat bench with the glutes and lower back on the pad and the legs extended.","Reach the arms overhead beside the ears.","Brace the abdominals and press the lower back into the bench.","Lift the shoulders and the straight legs a few inches to form a shallow hollow.","Hold the position while breathing steadily, then lower to rest."],"met":6.0},{"id":"bench-lat-stretch","n":"Étirement du grand dorsal sur banc","en":"Bench Lat Stretch","c":"stretching","eq":"flat_bench","pm":["latissimus_dorsi"],"sm":["posterior_deltoid"],"d":"beginner","bw":false,"uni":false,"img":["main"],"desc":"Étirement — banc. Travaille surtout : Grand dorsal. En soutien : Deltoïde postérieur.","ins":["Kneel on the floor in front of a bench.","Place both hands on top of the bench.","Sit your hips back and let your chest sink down.","Hold for 20 to 30 seconds, breathing steadily."],"met":5.0},{"id":"bench-leg-pull-in","n":"Relevés de genoux sur banc","en":"Bench Leg Pull-In","c":"strength","eq":"","pm":["rectus_abdominis"],"sm":["hip_flexors","obliques"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation dynamique, au poids du corps. Travaille surtout : Grand droit (abdominaux). En soutien : Fléchisseurs de hanche, Obliques.","ins":["Lie on your back on a flat bench and grip the sides behind your head for support.","Extend your legs straight out with heels just above the bench surface.","Pull your knees toward your chest, lifting the hips slightly off the bench.","Extend the legs back out under control without letting the heels touch the bench.","Repeat for the desired number of repetitions."],"met":3.5},{"id":"bench-press","n":"Développé couché à la barre","en":"Barbell Bench Press","c":"strength","eq":"barbell","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Lie flat on a bench with your eyes under the bar.","Grip the bar slightly wider than shoulder-width.","Unrack the bar and lower it to your mid-chest.","Press the bar back up to full arm extension.","Repeat for the desired number of reps."],"met":6.0},{"id":"bench-pull","n":"Tirage allongé sur banc","en":"Bench Pull","c":"strength","eq":"barbell","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","posterior_deltoid","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Deltoïde postérieur, Trapèzes.","ins":["Lie face down on an elevated bench with arms hanging straight down.","Grip a barbell or dumbbells below you.","Row the weight up to the underside of the bench.","Squeeze your shoulder blades at the top.","Lower under control and repeat."],"met":6.0},{"id":"bent-arm-barbell-pullover","n":"Pull-over bras fléchis à la barre","en":"Bent Arm Barbell Pullover","c":"strength","eq":"barbell","pm":["latissimus_dorsi","pectoralis_major"],"sm":["serratus_anterior","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre. Travaille surtout : Grand dorsal, Pectoraux. En soutien : Dentelé antérieur, Triceps.","ins":["Lie on a bench holding a barbell above your chest with bent elbows.","Keep your elbows bent throughout the movement.","Lower the barbell behind your head in an arc.","Pull the barbell back over your chest using your lats.","Repeat for the desired number of reps."],"met":5.0},{"id":"bent-arm-ez-bar-pullover","n":"Pull-over bras fléchis à la barre EZ","en":"Bent-Arm EZ-Bar Pullover","c":"strength","eq":"ez_bar","pm":["latissimus_dorsi","pectoralis_major"],"sm":["posterior_deltoid","serratus_anterior","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre EZ. Travaille surtout : Grand dorsal, Pectoraux. En soutien : Deltoïde postérieur, Dentelé antérieur, Triceps.","ins":["Lie on a flat bench holding an EZ-bar with a narrow overhand grip on the inner bends.","Start with the bar above your chest, elbows bent to roughly 90 degrees.","Keep the elbow angle fixed and lower the bar back in an arc overhead until a deep stretch is felt in the lats and pecs.","Pull the bar back over the chest along the same arc, without straightening the elbows.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"bent-over-db-row","n":"Rowing buste penché aux haltères","en":"Bent-Over Dumbbell Row","c":"strength","eq":"dumbbell","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","posterior_deltoid","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — haltères. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Deltoïde postérieur, Trapèzes.","ins":["Stand with feet hip-width, holding a dumbbell in each hand at the sides, palms facing in.","Hinge at the hips with a flat back until the torso is roughly 30–45 degrees from horizontal, dumbbells hanging directly below the shoulders.","Brace the core and pull both dumbbells up and slightly back, driving the elbows past the ribs.","Squeeze the upper back at the top, keeping the elbows tucked.","Lower under control to the starting position with the arms fully extended.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"bent-over-ez-bar-row","n":"Rowing buste penché à la barre EZ","en":"Bent-Over EZ-Bar Row","c":"strength","eq":"ez_bar","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","posterior_deltoid"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre EZ. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Deltoïde postérieur.","ins":["Hold an EZ-bar with an overhand grip, hinge at the hips to 45 degrees.","Pull the bar to your lower ribcage.","Lower under control.","Repeat."],"met":6.0},{"id":"bicep-curl","n":"Curl biceps aux haltères","en":"Dumbbell Bicep Curl","c":"strength","eq":"dumbbell","pm":["biceps_brachii"],"sm":["brachialis","forearm_flexors"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Biceps. En soutien : Brachial, Fléchisseurs de l'avant-bras.","ins":["Stand holding dumbbells at your sides, palms forward.","Curl the weights up toward your shoulders.","Squeeze at the top, then lower under control.","Repeat."],"met":5.0},{"id":"bicycle-crunch","n":"Crunch vélo","en":"Bicycle Crunch","c":"strength","eq":"","pm":["obliques","rectus_abdominis"],"sm":["hip_flexors"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage, au poids du corps. Travaille surtout : Obliques, Grand droit (abdominaux). En soutien : Fléchisseurs de hanche.","ins":["Lie on your back with hands behind your head and legs raised.","Bring one knee toward your chest while rotating your torso to meet it with the opposite elbow.","Extend that leg while bringing the other knee in.","Continue alternating in a pedaling motion.","Repeat."],"met":5.0},{"id":"bird-dog","n":"Bird dog","en":"Bird-Dog","c":"strength","eq":"","pm":["erector_spinae","transverse_abdominis"],"sm":["gluteus_maximus"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Transverse. En soutien : Grand fessier.","ins":["Start on all fours with a neutral spine.","Extend your right arm forward and left leg back simultaneously.","Hold for a moment, then return.","Repeat on the other side.","Alternate."],"met":5.0},{"id":"bird-dog-hold","n":"Bird dog statique","en":"Bird Dog Hold","c":"strength","eq":"","pm":["erector_spinae","rectus_abdominis"],"sm":["gluteus_maximus","obliques","posterior_deltoid"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Grand droit (abdominaux). En soutien : Grand fessier, Obliques, Deltoïde postérieur.","ins":["Start on all fours with hands under shoulders and knees under hips.","Extend one arm forward and the opposite leg back.","Keep your core tight and body level.","Hold the position without rotating your torso.","Hold for time. Complete on one side, then switch."],"met":3.5},{"id":"boat-pose","n":"Posture du bateau","en":"Boat Pose","c":"strength","eq":"","pm":["hip_flexors","rectus_abdominis"],"sm":["erector_spinae","quadriceps"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Lombaires (érecteurs du rachis), Quadriceps.","ins":["Sit on the floor with the knees bent and the feet flat, hands resting behind the thighs.","Lean back until you balance just behind the sit bones and lift the chest so the spine stays long.","Lift the shins until they are parallel to the floor, then straighten the legs as far as the back stays flat.","Reach the arms forward beside the legs and hold the position for the prescribed time.","Lower the feet under control to finish."],"met":5.0},{"id":"bodyweight-calf-raise","n":"Mollets au poids du corps","en":"Bodyweight Calf Raise","c":"strength","eq":"","pm":["gastrocnemius"],"sm":["soleus"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée, au poids du corps. Travaille surtout : Mollets (gastrocnémiens). En soutien : Soléaire.","ins":["Stand with feet hip-width apart on a flat surface.","Push up onto the balls of your feet as high as possible.","Squeeze your calves at the top.","Lower your heels back to the floor under control.","Repeat for the desired number of reps."],"met":3.5},{"id":"bodyweight-good-morning","n":"Good morning au poids du corps","en":"Bodyweight Good Morning","c":"strength","eq":"","pm":["erector_spinae","hamstrings"],"sm":["gluteus_maximus"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Ischio-jambiers. En soutien : Grand fessier.","ins":["Stand with feet hip-width apart and hands behind your head.","Keep a slight bend in your knees and brace your core.","Hinge at the hips and lower your torso toward parallel.","Drive your hips forward to return to standing.","Repeat for the desired number of reps."],"met":5.0},{"id":"bodyweight-lateral-raise","n":"Élévation latérale au poids du corps","en":"Bodyweight Lateral Raise","c":"strength","eq":"","pm":["lateral_deltoid"],"sm":["anterior_deltoid","trapezius"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée, au poids du corps. Travaille surtout : Deltoïde latéral. En soutien : Deltoïde antérieur, Trapèzes.","ins":["Stand upright with arms hanging at your sides.","Raise both arms out to the sides with a slight elbow bend until parallel with the floor.","Pause briefly at the top.","Lower slowly back to the starting position.","Repeat for the desired reps."],"met":3.5},{"id":"bodyweight-overhead-press","n":"Développé au-dessus de la tête au poids du corps","en":"Bodyweight Overhead Press","c":"strength","eq":"","pm":["anterior_deltoid","triceps_brachii"],"sm":["serratus_anterior","trapezius"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Deltoïde antérieur, Triceps. En soutien : Dentelé antérieur, Trapèzes.","ins":["Stand facing a wall in a pike position with hands on the ground.","Walk your feet closer for a more vertical body line.","Lower your head toward the floor by bending your elbows.","Press through your hands to extend your arms.","Repeat for the desired number of reps."],"met":5.0},{"id":"bodyweight-reverse-lunge","n":"Fente arrière au poids du corps","en":"Bodyweight Reverse Lunge","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["hamstrings"],"d":"beginner","bw":true,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Stand tall with your feet hip-width apart.","Step one leg back and lower your knee toward the floor.","Lower until your front thigh is parallel to the floor.","Push through your front heel to return to standing.","Repeat on both sides."],"met":5.0},{"id":"bodyweight-squat","n":"Squat au poids du corps","en":"Bodyweight Squat","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["erector_spinae","gluteus_medius","hamstrings"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Moyen fessier, Ischio-jambiers.","ins":["Stand with feet shoulder-width apart and arms extended forward.","Sit back and down by bending your hips and knees.","Lower until your thighs are parallel to the floor.","Drive through your heels to return to standing.","Repeat for the desired number of reps."],"met":6.0},{"id":"bow-pose","n":"Posture de l'arc","en":"Bow Pose","c":"strength","eq":"","pm":["erector_spinae","gluteus_maximus"],"sm":["hamstrings","pectoralis_major"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Grand fessier. En soutien : Ischio-jambiers, Pectoraux.","ins":["Lie face down with the arms beside the body and the forehead resting on the mat.","Bend the knees and take hold of the outside of both ankles.","Press the shins back into the hands so the chest and thighs lift away from the floor.","Hold the lifted position for the prescribed time, keeping the neck long and the gaze forward.","Release the ankles and lower down under control."],"met":5.0},{"id":"box-jump","n":"Saut sur box","en":"Box Jump","c":"plyometrics","eq":"plyo_box","pm":["gluteus_maximus","quadriceps"],"sm":["gastrocnemius","hamstrings","soleus"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice pliométrique — box de saut. Travaille surtout : Grand fessier, Quadriceps. En soutien : Mollets (gastrocnémiens), Ischio-jambiers, Soléaire.","ins":["Stand a foot in front of a sturdy box with feet shoulder-width.","Drop into a quarter-squat and swing the arms back.","Drive the arms up and explode off the floor onto the box.","Land softly with both feet flat and knees bent.","Step down — do not jump down — and reset."],"met":7.0},{"id":"box-squat","n":"Squat sur box","en":"Box Squat","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["erector_spinae","gluteus_medius","hamstrings"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Moyen fessier, Ischio-jambiers.","ins":["Stand in front of a box or bench, feet shoulder-width apart, with your arms extended forward for balance.","Push your hips back and bend your knees, sitting back toward the box rather than straight down.","Touch the box lightly with your glutes without collapsing onto it.","Drive through your feet to stand back up, squeezing your glutes at the top.","Repeat for the desired number of reps."],"met":6.0},{"id":"bulgarian-split-squat","n":"Squat bulgare","en":"Bulgarian Split Squat","c":"strength","eq":"dumbbell","pm":["gluteus_maximus","quadriceps"],"sm":["hamstrings"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Grand fessier, Quadriceps. En soutien : Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Stand in front of a bench, place one foot behind you on the bench.","Hold dumbbells at your sides.","Lower your body until your front thigh is parallel to the floor.","Push through your front heel to stand back up.","Repeat on both sides."],"met":6.0},{"id":"burpees","n":"Burpees","en":"Burpees","c":"cardio","eq":"","pm":["gluteus_maximus","pectoralis_major","quadriceps"],"sm":["anterior_deltoid","rectus_abdominis","triceps_brachii"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Exercice cardio, au poids du corps. Travaille surtout : Grand fessier, Pectoraux, Quadriceps. En soutien : Deltoïde antérieur, Grand droit (abdominaux), Triceps.","ins":["Stand with feet shoulder-width apart.","Squat down and place the hands on the floor in front of you.","Jump or step the feet back into a plank, then perform a push-up.","Jump or step the feet forward to the hands.","Stand up and jump explosively, reaching the arms overhead."],"met":8.0},{"id":"butterfly-stretch","n":"Étirement papillon","en":"Butterfly Stretch","c":"stretching","eq":"","pm":["adductors"],"sm":["hip_flexors"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Adducteurs. En soutien : Fléchisseurs de hanche.","ins":["Sit tall and press the soles of your feet together.","Let your knees drop out toward the floor.","Hold your feet and sit up tall.","Hold for 20 to 30 seconds, breathing steadily."],"met":5.0},{"id":"cable-bent-over-row","n":"Rowing buste penché à la poulie","en":"Cable Bent-Over Row","c":"strength","eq":"cable","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","posterior_deltoid"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — poulie. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Deltoïde postérieur.","ins":["Attach a straight or V-bar to a low cable pulley.","Hinge at the hips with knees slightly bent.","Pull the handle toward your lower chest.","Squeeze your shoulder blades at the top.","Lower with control and repeat."],"met":6.0},{"id":"cable-chest-press","n":"Développé pectoraux à la poulie","en":"Cable Chest Press","c":"strength","eq":"cable","pm":["pectoralis_major"],"sm":["anterior_deltoid","serratus_anterior","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — poulie. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Dentelé antérieur, Triceps.","ins":["Set the cables to chest height and face away from the machine.","Grip a handle in each hand and step forward into a staggered stance.","Press the handles forward until your arms are extended.","Squeeze your chest at the top.","Return under control and repeat."],"met":6.0},{"id":"cable-crunch","n":"Crunch à la poulie","en":"Cable Crunch","c":"strength","eq":"cable","pm":["rectus_abdominis"],"sm":["obliques","transverse_abdominis"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — poulie. Travaille surtout : Grand droit (abdominaux). En soutien : Obliques, Transverse.","ins":["Kneel in front of a cable machine with a rope attachment at the top.","Hold the rope near your forehead with elbows bent.","Crunch down by flexing your spine and bringing your elbows to your thighs.","Squeeze your abs hard at the bottom.","Return to the start position and repeat."],"met":5.0},{"id":"cable-curl","n":"Curl à la poulie","en":"Cable Curl","c":"strength","eq":"cable","pm":["biceps_brachii"],"sm":["brachialis"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — poulie. Travaille surtout : Biceps. En soutien : Brachial.","ins":["Stand facing a low cable pulley with a straight bar or EZ-bar attachment.","Grip the bar with an underhand grip, elbows at your sides.","Curl the bar up toward your shoulders.","Lower with control.","Repeat."],"met":5.0},{"id":"cable-external-rotation","n":"Rotation externe à la poulie","en":"Cable External Rotation","c":"strength","eq":"cable","pm":["posterior_deltoid"],"sm":["rhomboids","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — poulie. Travaille surtout : Deltoïde postérieur. En soutien : Rhomboïdes, Trapèzes.","ins":["Set a cable pulley to elbow height and grip the handle.","Stand side-on to the machine with your working elbow bent at 90 degrees.","Keep your elbow glued to your side and rotate your forearm outward.","Pause at the end of the movement.","Return under control. Complete reps on one side, then switch."],"met":6.0},{"id":"cable-fly","n":"Écartés à la poulie","en":"Cable Fly","c":"strength","eq":"cable","pm":["pectoralis_major"],"sm":["anterior_deltoid"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — poulie. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur.","ins":["Stand between two cable columns with handles attached to high pulleys.","With a slight bend in your elbows, open your arms wide.","Bring your hands together in front of your chest in a hugging motion.","Slowly return to the starting position.","Repeat."],"met":5.0},{"id":"cable-front-raise","n":"Élévation frontale à la poulie","en":"Cable Front Raise","c":"strength","eq":"cable","pm":["anterior_deltoid"],"sm":["lateral_deltoid","pectoralis_major"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — poulie. Travaille surtout : Deltoïde antérieur. En soutien : Deltoïde latéral, Pectoraux. Se fait d'un côté puis de l'autre.","ins":["Stand facing away from a low cable pulley with a handle attachment.","Hold the handle with arm extended at your thigh.","Raise your arm forward to shoulder height keeping it straight.","Pause at the top.","Lower under control and repeat."],"met":5.0},{"id":"cable-hammer-curl","n":"Curl marteau à la poulie","en":"Cable Hammer Curl","c":"strength","eq":"cable","pm":["biceps_brachii","brachialis","brachioradialis"],"sm":["forearm_flexors"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — poulie. Travaille surtout : Biceps, Brachial, Brachio-radial. En soutien : Fléchisseurs de l'avant-bras.","ins":["Attach a rope to a low cable pulley and stand facing the machine.","Grip the rope with a neutral (hammer) grip, palms facing each other.","Curl the rope upward toward your shoulders, keeping elbows pinned at your sides.","Squeeze at the top, then lower slowly to full extension.","Repeat for the desired reps."],"met":5.0},{"id":"cable-kickback","n":"Kickback fessier à la poulie","en":"Cable Glute Kickback","c":"strength","eq":"cable","pm":["gluteus_maximus"],"sm":["hamstrings"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — poulie. Travaille surtout : Grand fessier. En soutien : Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Attach an ankle cuff to a low cable pulley and fasten it around one ankle.","Stand facing the machine, holding the frame lightly for balance, and hinge slightly forward at the hips.","Kick the cuffed leg straight back, extending the hip fully while keeping the knee nearly straight.","Squeeze the glute at full hip extension, then return the foot slowly to the start.","Complete all reps on one side before switching."],"met":5.0},{"id":"cable-lateral-raise","n":"Élévation latérale à la poulie","en":"Cable Lateral Raise","c":"strength","eq":"cable","pm":["lateral_deltoid"],"sm":["anterior_deltoid","trapezius"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — poulie. Travaille surtout : Deltoïde latéral. En soutien : Deltoïde antérieur, Trapèzes. Se fait d'un côté puis de l'autre.","ins":["Stand sideways to a low pulley, grip the handle with the outside hand.","Keep a soft bend in the elbow and the cable in front of the working leg.","Raise the arm out to the side until parallel to the floor.","Lower under control. Complete reps per side, then switch.","Maintain tension — do not let the weight rest at the bottom."],"met":5.0},{"id":"cable-pallof-press","n":"Pallof press à la poulie","en":"Cable Pallof Press","c":"strength","eq":"cable","pm":["obliques","transverse_abdominis"],"sm":["anterior_deltoid","erector_spinae","gluteus_medius","rectus_abdominis"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — poulie. Travaille surtout : Obliques, Transverse. En soutien : Deltoïde antérieur, Lombaires (érecteurs du rachis), Moyen fessier, Grand droit (abdominaux).","ins":["Set a cable at chest height and take the handle in both hands, standing side-on to the machine.","Step away until there is real tension on the cable, with your feet about shoulder-width apart and knees softly bent.","Bring the handle to the centre of your chest and brace your trunk and glutes.","Press the handle straight out in front of you until your arms are extended, resisting the pull that wants to rotate you toward the machine.","Hold the extended position for a moment, then bring the handle back to your chest under control.","Complete the desired reps, then turn around and repeat facing the other way."],"met":3.5},{"id":"cable-pull-through","n":"Pull-through à la poulie","en":"Cable Pull-Through","c":"strength","eq":"cable","pm":["gluteus_maximus","hamstrings"],"sm":["erector_spinae"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — poulie. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis).","ins":["Attach a rope to the low pulley and stand facing away from the machine with the rope between the legs.","Step forward until the cable is taut, then brace the trunk and soften the knees.","Push the hips back while keeping the spine neutral and the arms long.","Drive the hips forward and squeeze the glutes to stand tall.","Reverse into the next hinge without letting the weight stack slam down."],"met":6.0},{"id":"cable-tricep-kickback","n":"Kickback triceps à la poulie","en":"Cable Tricep Kickback","c":"strength","eq":"cable","pm":["triceps_brachii"],"sm":["posterior_deltoid"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — poulie. Travaille surtout : Triceps. En soutien : Deltoïde postérieur.","ins":["Attach a handle to a low cable and hinge forward at the hips.","Tuck your upper arm against your side with elbow bent 90 degrees.","Extend your elbow to push the handle back behind you.","Squeeze your triceps at the end of the movement.","Return under control. Complete reps on one side, then switch."],"met":5.0},{"id":"cable-upright-row","n":"Rowing menton à la poulie","en":"Cable Upright Row","c":"strength","eq":"cable","pm":["lateral_deltoid","trapezius"],"sm":["anterior_deltoid","biceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — poulie. Travaille surtout : Deltoïde latéral, Trapèzes. En soutien : Deltoïde antérieur, Biceps.","ins":["Stand in front of a cable machine and grip a straight bar or rope at thigh height.","Pull the bar up toward your chin, leading with your elbows.","Lower under control.","Repeat."],"met":6.0},{"id":"cable-wrist-curl","n":"Curl poignets à la poulie","en":"Cable Wrist Curl","c":"strength","eq":"cable","pm":["forearm_flexors"],"sm":[],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — poulie. Travaille surtout : Fléchisseurs de l'avant-bras.","ins":["Attach a straight bar to a low cable pulley.","Kneel or sit with forearms on a bench, palms facing up.","Let your wrists flex off the bench edge.","Curl the bar up by flexing your wrists.","Lower under control and repeat."],"met":5.0},{"id":"camel-pose","n":"Posture du chameau","en":"Camel Pose","c":"stretching","eq":"","pm":["erector_spinae","hip_flexors"],"sm":["pectoralis_major","quadriceps"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Fléchisseurs de hanche. En soutien : Pectoraux, Quadriceps.","ins":["Kneel with the knees hip-width apart and the hips stacked over the knees.","Place the hands on the back of the pelvis with the fingers pointing down and lift the chest.","Press the hips forward and arch back, reaching for the heels if the position stays comfortable.","Hold the pose for the prescribed time, keeping the neck in line with the spine.","Bring the hands back to the pelvis and come up chest-first."],"met":5.0},{"id":"captains-chair-knee-raise","n":"Relevés de genoux à la chaise romaine","en":"Captain's Chair Knee Raise","c":"strength","eq":"","pm":["hip_flexors","rectus_abdominis"],"sm":["obliques","transverse_abdominis"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage, au poids du corps. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Obliques, Transverse.","ins":["Position yourself in the captain's chair with your back flat against the pad and forearms on the armrests.","Let your legs hang straight down.","Engage your core and raise your knees toward your chest.","Hold briefly at the top, then lower slowly to the starting position.","Repeat for the desired reps."],"met":5.0},{"id":"captains-chair-leg-raise","n":"Relevés de jambes à la chaise romaine","en":"Captain's Chair Leg Raise","c":"strength","eq":"","pm":["hip_flexors","rectus_abdominis"],"sm":["obliques","transverse_abdominis"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage, au poids du corps. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Obliques, Transverse.","ins":["Position yourself in the captain's chair with your back flat against the pad and forearms on the armrests.","Let your legs hang straight down.","Keeping your legs straight, raise them until parallel with the floor or higher.","Hold briefly at the top, then lower slowly.","Repeat for the desired reps."],"met":5.0},{"id":"cat-cow","n":"Chat-vache","en":"Cat-Cow","c":"stretching","eq":"","pm":["erector_spinae","rectus_abdominis"],"sm":["transverse_abdominis","trapezius"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Grand droit (abdominaux). En soutien : Transverse, Trapèzes.","ins":["Start on all fours with the hands under the shoulders and the knees under the hips.","Exhale and round the spine towards the ceiling, tucking the tailbone and letting the head drop.","Inhale and reverse it: let the belly sink, lift the chest and tailbone, and look slightly forward.","Move between the two shapes slowly, one breath per position.","Finish in a neutral spine and sit back onto the heels."],"met":5.0},{"id":"cat-stretch","n":"Étirement du chat","en":"Cat Stretch","c":"stretching","eq":"","pm":["erector_spinae"],"sm":["rhomboids","trapezius"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis). En soutien : Rhomboïdes, Trapèzes.","ins":["Start on all fours, hands under shoulders and knees under hips.","Round your spine up toward the ceiling.","Tuck your chin toward your chest.","Hold for 20 to 30 seconds, breathing steadily."],"met":5.0},{"id":"chair-pose","n":"Posture de la chaise","en":"Chair Pose","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["anterior_deltoid","erector_spinae"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Deltoïde antérieur, Lombaires (érecteurs du rachis).","ins":["Stand with the feet together or hip-width apart and the weight in the heels.","Bend the knees and send the hips back as if sitting down onto a chair.","Raise the arms overhead beside the ears, keeping the ribs from flaring.","Hold the position for the prescribed time with the chest lifted and the knees tracking over the toes.","Press through the heels to stand back up."],"met":5.0},{"id":"cheat-curl","n":"Curl avec élan (cheat curl)","en":"Cheat Curl","c":"strength","eq":"barbell","pm":["biceps_brachii"],"sm":["brachialis","brachioradialis","erector_spinae"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre. Travaille surtout : Biceps. En soutien : Brachial, Brachio-radial, Lombaires (érecteurs du rachis).","ins":["Stand holding weight at thigh level with an underhand grip.","Use a slight hip drive to start the curl.","Curl the weight up toward your shoulders explosively.","Lower the weight slowly under control through the full range.","Repeat for the desired number of reps."],"met":5.0},{"id":"chest-press-machine","n":"Développé pectoraux à la machine","en":"Machine Chest Press","c":"strength","eq":"chest_press_machine","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — machine développé pectoraux. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Sit in the machine with your back flat against the pad.","Grip the handles at chest level.","Push the handles forward until your arms are fully extended.","Slowly return to the starting position.","Repeat."],"met":6.0},{"id":"chest-supported-db-row","n":"Rowing haltères buste appuyé","en":"Chest-Supported Dumbbell Row","c":"strength","eq":"dumbbell","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","posterior_deltoid"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — haltères. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Deltoïde postérieur.","ins":["Lie face-down on an incline bench with dumbbells hanging beneath.","Row the dumbbells up to your sides.","Squeeze at the top, then lower.","Repeat."],"met":6.0},{"id":"chest-supported-dumbbell-shrug","n":"Haussements d'épaules haltères buste appuyé","en":"Chest Supported Dumbbell Shrug","c":"strength","eq":"dumbbell","pm":["trapezius"],"sm":["posterior_deltoid","rhomboids"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Trapèzes. En soutien : Deltoïde postérieur, Rhomboïdes.","ins":["Set an incline bench to about 30 degrees.","Lie face down on the bench holding dumbbells at arm's length.","Shrug your shoulders up and back toward your ears.","Squeeze your upper traps at the top.","Lower under control and repeat."],"met":5.0},{"id":"chest-supported-kettlebell-row","n":"Rowing KB buste appuyé","en":"Chest-Supported Kettlebell Row","c":"strength","eq":"kettlebell","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","posterior_deltoid","trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — kettlebell. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Deltoïde postérieur, Trapèzes.","ins":["Lie face down on an incline bench, allowing your arms to hang freely with a kettlebell in each hand.","Brace your core and retract your shoulder blades.","Pull the kettlebells towards your hips, squeezing your shoulder blades together.","Pause briefly at the top, feeling the contraction in your back.","Slowly lower the kettlebells back to the starting position with control."],"met":6.0},{"id":"chest-supported-smith-machine-row","n":"Rowing buste appuyé à la Smith machine","en":"Chest-Supported Smith Machine Row","c":"strength","eq":"smith_machine","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","posterior_deltoid"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — smith machine. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Deltoïde postérieur.","ins":["Set an incline bench inside the Smith machine facing the bar, and set the bar low enough that your arms hang straight when you lean on the pad.","Stand astride the bench with your feet planted and your chest resting against the top of the pad.","Take an overhand grip a little wider than shoulder-width and unhook the bar with your arms extended.","Pull the bar up to your lower chest, leading with your elbows and squeezing the shoulder blades together at the top.","Lower the bar under control until your arms are straight again, and repeat for the desired number of repetitions."],"met":6.0},{"id":"childs-pose","n":"Posture de l'enfant","en":"Child's Pose","c":"stretching","eq":"","pm":["erector_spinae","latissimus_dorsi"],"sm":["trapezius"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Grand dorsal. En soutien : Trapèzes.","ins":["Kneel and sit your hips back toward your heels.","Fold your torso forward over your thighs.","Reach both arms out long on the floor in front.","Hold for 20 to 30 seconds, breathing steadily."],"met":5.0},{"id":"chin-tuck-hold","n":"Rentrée du menton (statique)","en":"Chin Tuck Hold","c":"strength","eq":"","pm":["trapezius"],"sm":["rhomboids"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Trapèzes. En soutien : Rhomboïdes.","ins":["Stand or sit tall with your shoulders relaxed.","Pull your chin straight back, creating a double chin.","Keep your head level without tilting.","Hold the position for the desired duration.","Release and repeat for multiple sets."],"met":5.0},{"id":"chin-ups","n":"Tractions supination","en":"Chin-Ups","c":"strength","eq":"pull_up_bar","pm":["biceps_brachii","latissimus_dorsi"],"sm":["rhomboids"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre de traction. Travaille surtout : Biceps, Grand dorsal. En soutien : Rhomboïdes.","ins":["Hang from a bar with a shoulder-width underhand grip.","Pull yourself up until chin is above the bar.","Lower under control.","Repeat."],"met":6.0},{"id":"clamshells","n":"Clamshell","en":"Clamshells","c":"strength","eq":"","pm":["abductors","gluteus_medius"],"sm":["gluteus_maximus"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Abducteurs, Moyen fessier. En soutien : Grand fessier.","ins":["Lie on your side with knees bent and stacked on top of each other.","Keep your feet together and hips stacked.","Open your top knee toward the ceiling without rotating your hips.","Squeeze your outer glute at the top.","Lower under control. Complete reps on one side, then switch."],"met":5.0},{"id":"clamshells-hold","n":"Clamshell statique","en":"Clamshell Hold","c":"strength","eq":"","pm":["abductors","gluteus_medius"],"sm":["gluteus_maximus"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Abducteurs, Moyen fessier. En soutien : Grand fessier.","ins":["Lie on one side with the hips and knees bent about 45 and 90 degrees, heels together and knees stacked.","Stack the shoulders and hips vertically and brace the trunk so the pelvis cannot roll backwards.","Open the upper knee as far as it goes without the pelvis rotating, keeping the heels touching.","Hold that open position for the prescribed time, breathing normally.","Lower the knee under control and repeat on the other side."],"met":5.0},{"id":"clap-push-ups","n":"Pompes claquées","en":"Clap Push-Ups","c":"strength","eq":"","pm":["pectoralis_major"],"sm":["triceps_brachii"],"d":"advanced","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Pectoraux. En soutien : Triceps.","ins":["Begin in a standard push-up position.","Lower your chest to the floor.","Explosively push up so hands leave the ground.","Clap your hands together and land softly, returning to start.","Repeat."],"met":7.0},{"id":"clean","n":"Épaulé (clean)","en":"Clean","c":"olympic","eq":"barbell","pm":["gluteus_maximus","quadriceps"],"sm":["anterior_deltoid","erector_spinae","hamstrings","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Mouvement d'haltérophilie — barre. Travaille surtout : Grand fessier, Quadriceps. En soutien : Deltoïde antérieur, Lombaires (érecteurs du rachis), Ischio-jambiers, Trapèzes.","ins":["Stand over a loaded barbell with feet hip-width apart.","Grip the bar just outside your knees with an overhand grip.","Drive explosively through your legs and extend your hips.","Pull yourself under the bar and catch it on your front deltoids.","Stand fully upright to complete the lift."],"met":8.0},{"id":"clean-and-jerk","n":"Épaulé-jeté","en":"Clean and Jerk","c":"olympic","eq":"barbell","pm":["anterior_deltoid","gluteus_maximus","quadriceps"],"sm":["erector_spinae","trapezius","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Mouvement d'haltérophilie — barre. Travaille surtout : Deltoïde antérieur, Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Trapèzes, Triceps.","ins":["Pull a loaded barbell from the floor to your shoulders as in a clean.","Stand fully with the bar racked on your front delts.","Dip slightly and drive the bar overhead explosively.","Split your legs to receive the bar with arms locked out.","Recover by stepping your feet back together."],"met":8.0},{"id":"close-grip-barbell-curl","n":"Curl prise serrée à la barre","en":"Close-Grip Barbell Curl","c":"strength","eq":"barbell","pm":["biceps_brachii"],"sm":["brachialis","brachioradialis"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre. Travaille surtout : Biceps. En soutien : Brachial, Brachio-radial.","ins":["Stand holding a barbell with an underhand grip, hands closer than shoulder-width apart.","Start with the bar at the thighs, arms extended, elbows tucked to the sides.","Curl the bar up to the shoulders by flexing the elbows.","Squeeze the biceps at the top, then lower under control.","Repeat for the recommended number of repetitions."],"met":5.0},{"id":"close-grip-bench-press","n":"Développé couché prise serrée","en":"Close-Grip Bench Press","c":"strength","eq":"barbell","pm":["triceps_brachii"],"sm":["anterior_deltoid","pectoralis_major"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Triceps. En soutien : Deltoïde antérieur, Pectoraux.","ins":["Lie on a flat bench and grip the barbell with hands shoulder-width apart.","Lower the bar to your lower chest keeping elbows close to your sides.","Press back up to full extension.","Repeat."],"met":6.0},{"id":"close-grip-db-bench-press","n":"Développé couché prise serrée aux haltères","en":"Close-Grip Dumbbell Bench Press","c":"strength","eq":"dumbbell","pm":["triceps_brachii"],"sm":["anterior_deltoid","pectoralis_major"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Triceps. En soutien : Deltoïde antérieur, Pectoraux.","ins":["Lie on a flat bench and hold two dumbbells together over your chest.","Lower them to your chest keeping elbows close.","Press back up.","Repeat."],"met":6.0},{"id":"close-grip-ez-bar-bench-press","n":"Développé couché prise serrée à la barre EZ","en":"Close-Grip EZ-Bar Bench Press","c":"strength","eq":"ez_bar","pm":["triceps_brachii"],"sm":["anterior_deltoid","pectoralis_major"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre EZ. Travaille surtout : Triceps. En soutien : Deltoïde antérieur, Pectoraux.","ins":["Lie on a flat bench and grip the inner curves of the EZ-bar.","Lower the bar to your chest with elbows tucked.","Press back up to full extension.","Repeat."],"met":6.0},{"id":"close-grip-ez-bar-curl","n":"Curl prise serrée à la barre EZ","en":"Close-Grip EZ-Bar Curl","c":"strength","eq":"ez_bar","pm":["biceps_brachii"],"sm":["brachialis"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre EZ. Travaille surtout : Biceps. En soutien : Brachial.","ins":["Stand holding an EZ-bar with hands on the inner bends, palms up.","Keep the elbows tucked at the sides.","Curl the bar up to shoulder level, squeezing the biceps.","Lower under control to a full stretch.","Repeat for the prescribed reps."],"met":5.0},{"id":"close-grip-incline-bench","n":"Développé incliné prise serrée","en":"Close-Grip Incline Bench Press","c":"strength","eq":"barbell","pm":["triceps_brachii"],"sm":["anterior_deltoid","pectoralis_major"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Triceps. En soutien : Deltoïde antérieur, Pectoraux.","ins":["Set bench to an incline. Grip the barbell with hands shoulder-width or closer.","Lower the bar to your upper chest.","Press back up.","Repeat."],"met":6.0},{"id":"close-grip-lat-pulldown","n":"Tirage vertical prise serrée","en":"Close Grip Lat Pulldown","c":"strength","eq":"cable","pm":["latissimus_dorsi"],"sm":["biceps_brachii","brachialis","posterior_deltoid","rhomboids"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — poulie. Travaille surtout : Grand dorsal. En soutien : Biceps, Brachial, Deltoïde postérieur, Rhomboïdes.","ins":["Sit at a lat pulldown machine and secure your thighs under the pad.","Grip the close-grip handle with palms facing each other.","Pull the handle down to your upper chest.","Squeeze your lats at the bottom.","Return under control and repeat."],"met":6.0},{"id":"close-grip-pull-ups","n":"Tractions prise serrée","en":"Close-Grip Pull-Ups","c":"strength","eq":"pull_up_bar","pm":["biceps_brachii","latissimus_dorsi"],"sm":["rhomboids"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre de traction. Travaille surtout : Biceps, Grand dorsal. En soutien : Rhomboïdes.","ins":["Hang from a pull-up bar with hands shoulder-width or narrower, palms away.","Pull yourself up until chin clears the bar.","Lower under control.","Repeat."],"met":6.0},{"id":"close-grip-push-ups","n":"Pompes prise serrée","en":"Close Grip Push Ups","c":"strength","eq":"","pm":["pectoralis_major","triceps_brachii"],"sm":["anterior_deltoid","serratus_anterior"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Pectoraux, Triceps. En soutien : Deltoïde antérieur, Dentelé antérieur.","ins":["Assume a push-up position with hands directly under your shoulders.","Keep your elbows tucked close to your ribs.","Lower your chest toward the floor.","Press back up to the starting position.","Repeat for the desired number of reps."],"met":5.0},{"id":"close-stance-leg-press","n":"Presse à cuisses pieds serrés","en":"Close-Stance Leg Press","c":"strength","eq":"leg_press","pm":["quadriceps"],"sm":["gluteus_maximus","hamstrings"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — presse à cuisses. Travaille surtout : Quadriceps. En soutien : Grand fessier, Ischio-jambiers.","ins":["Set the seat and back pad so your lower back stays supported throughout the repetition.","Place your feet close together near the middle of the platform, with the toes and knees pointing along the same line.","Lower the sled by bending the knees and hips while keeping both feet flat and the knees tracking over the toes.","Press the platform away through the whole foot until the legs are extended without snapping the knees straight.","Return under control and repeat for the desired number of repetitions."],"met":6.0},{"id":"cobra-stretch","n":"Étirement du cobra","en":"Cobra Stretch","c":"stretching","eq":"","pm":["rectus_abdominis"],"sm":["hip_flexors","transverse_abdominis"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Grand droit (abdominaux). En soutien : Fléchisseurs de hanche, Transverse.","ins":["Lie face down with your hands under your shoulders.","Press through your hands to lift your chest off the floor.","Keep your hips and legs on the floor, shoulders relaxed.","Hold for 20 to 30 seconds, breathing steadily."],"met":5.0},{"id":"cocoons","n":"Cocons (relevés groupés)","en":"Cocoons","c":"strength","eq":"","pm":["rectus_abdominis"],"sm":["hip_flexors","obliques"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Grand droit (abdominaux). En soutien : Fléchisseurs de hanche, Obliques.","ins":["Lie face-up on the floor with arms extended overhead and legs extended, hovering slightly off the floor.","Simultaneously tuck the knees toward the chest and sweep the arms forward into a crunch.","Try to touch the hands to the shins at the top.","Reverse the motion smoothly, re-extending arms and legs back to the hover.","Repeat for the recommended number of repetitions."],"met":5.0},{"id":"commando-pull-up","n":"Traction commando","en":"Commando Pull-Up","c":"strength","eq":"pull_up_bar","pm":["biceps_brachii","latissimus_dorsi"],"sm":["brachialis","brachioradialis","forearm_flexors","obliques","rhomboids","trapezius"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre de traction. Travaille surtout : Biceps, Grand dorsal. En soutien : Brachial, Brachio-radial, Fléchisseurs de l'avant-bras, Obliques, Rhomboïdes, Trapèzes.","ins":["Grip the bar with the hands one in front of the other, palms facing each other, and hang with the arms straight and the body turned sideways.","Brace the trunk and pull the shoulder blades down to start the movement.","Pull yourself up, driving the elbows down, until your head clears the bar on one side of it.","Pause briefly at the top with the chest close to the bar.","Lower under control to a full hang.","Take the head to the other side of the bar on the next repetition, or swap the hand positions each set."],"met":6.0},{"id":"concentration-curl","n":"Curl concentré","en":"Concentration Curl","c":"strength","eq":"dumbbell","pm":["biceps_brachii"],"sm":["brachialis"],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Biceps. En soutien : Brachial. Se fait d'un côté puis de l'autre.","ins":["Sit on a bench with legs spread, holding a dumbbell in one hand.","Brace your elbow against the inside of your thigh.","Curl the dumbbell up toward your shoulder.","Lower with control.","Repeat on both sides."],"met":5.0},{"id":"cossack-squat","n":"Squat cosaque","en":"Cossack Squat","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["adductors","hamstrings"],"d":"intermediate","bw":true,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Adducteurs, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Stand in a wide stance with toes turned slightly out.","Shift your weight to one side, bending that knee and sinking into a deep squat.","Keep the trailing leg straight with the heel down and toes up.","Sink as low as your mobility allows, keeping the chest tall.","Drive through the bent leg back to center, then repeat to the other side."],"met":6.0},{"id":"cow-face-pose","n":"Posture de la tête de vache","en":"Cow Face Pose","c":"stretching","eq":"","pm":["gluteus_maximus","gluteus_medius"],"sm":["posterior_deltoid","triceps_brachii"],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Grand fessier, Moyen fessier. En soutien : Deltoïde postérieur, Triceps. Se fait d'un côté puis de l'autre.","ins":["Sit on the floor and cross one knee directly over the other so the knees stack in the midline.","Walk the feet out towards the hips and settle both sit bones evenly on the floor.","Reach the arm on the top-knee side up and bend it behind the head, then reach the other arm up the back to clasp.","Hold the position for the prescribed time, keeping the chest open and the spine tall.","Release and repeat with the other leg and arm on top."],"met":5.0},{"id":"crab-dips","n":"Dips en crabe","en":"Crab Dips","c":"strength","eq":"","pm":["triceps_brachii"],"sm":["anterior_deltoid","gluteus_maximus","pectoralis_major"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Triceps. En soutien : Deltoïde antérieur, Grand fessier, Pectoraux.","ins":["Sit with the knees bent, the feet flat and the hands on the floor behind you, fingers pointing towards the heels.","Press into the hands and feet and lift the hips until the trunk is roughly level with the knees.","Bend the elbows straight back to lower the hips towards the floor without sitting down.","Push back up until the arms are straight, keeping the hips lifted.","Repeat for the desired number of repetitions and lower the hips to finish."],"met":5.0},{"id":"crescent-lunge","n":"Fente en croissant","en":"Crescent Lunge","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["erector_spinae","hip_flexors"],"d":"intermediate","bw":true,"uni":true,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Fléchisseurs de hanche. Se fait d'un côté puis de l'autre.","ins":["Step one foot forward into a long stance with the back heel lifted and the toes pointing forward.","Bend the front knee to about ninety degrees so it stacks over the ankle.","Draw the back hip forward so both hip points face the front of the mat, then raise the arms overhead.","Hold the position for the prescribed time with the ribs down and the back leg straight.","Step the feet together and repeat on the other side."],"met":5.0},{"id":"cross-body-crunch","n":"Crunch croisé","en":"Cross-Body Crunch","c":"strength","eq":"","pm":["obliques"],"sm":["rectus_abdominis"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation dynamique, au poids du corps. Travaille surtout : Obliques. En soutien : Grand droit (abdominaux).","ins":["Lie face-up on the floor with knees bent and hands lightly behind the ears.","Crunch up and rotate, bringing the right elbow toward the left knee as the knee draws up.","Return to the starting position under control.","Repeat on the other side, alternating every rep."],"met":3.5},{"id":"cross-body-hammer-curl","n":"Curl marteau croisé","en":"Cross Body Hammer Curl","c":"strength","eq":"dumbbell","pm":["brachialis","brachioradialis"],"sm":["biceps_brachii","forearm_flexors"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Brachial, Brachio-radial. En soutien : Biceps, Fléchisseurs de l'avant-bras.","ins":["Stand tall holding a dumbbell in each hand with a neutral grip.","Curl one dumbbell up across your body toward the opposite shoulder.","Keep your elbow stationary at your side.","Lower under control and repeat on the other side.","Continue alternating for the desired number of reps."],"met":5.0},{"id":"cross-body-shoulder-stretch","n":"Étirement d'épaule bras croisé","en":"Cross-Body Shoulder Stretch","c":"stretching","eq":"","pm":["posterior_deltoid"],"sm":["rhomboids"],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Deltoïde postérieur. En soutien : Rhomboïdes. Se fait d'un côté puis de l'autre.","ins":["Stand tall and bring one straight arm across your chest.","Hook your other forearm under it.","Gently pull the arm closer to your chest.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"crow-pose","n":"Posture du corbeau","en":"Crow Pose","c":"strength","eq":"","pm":["anterior_deltoid","triceps_brachii"],"sm":["rectus_abdominis","serratus_anterior"],"d":"advanced","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Deltoïde antérieur, Triceps. En soutien : Grand droit (abdominaux), Dentelé antérieur.","ins":["Squat with the feet close together and place the palms shoulder-width apart on the floor in front of you.","Bend the elbows straight back and set the knees high onto the backs of the upper arms.","Shift the weight forward onto the hands until the feet float off the floor.","Hold the balance for the prescribed time, rounding the upper back and looking slightly forward.","Lower the feet under control."],"met":5.0},{"id":"crunches","n":"Crunchs","en":"Crunches","c":"strength","eq":"","pm":["rectus_abdominis"],"sm":["obliques"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage, au poids du corps. Travaille surtout : Grand droit (abdominaux). En soutien : Obliques.","ins":["Lie on your back with knees bent and hands behind your head.","Curl your upper body toward your knees, lifting your shoulder blades off the floor.","Squeeze your abs at the top.","Lower with control.","Repeat."],"met":3.5},{"id":"dancer-pose","n":"Posture du danseur","en":"Dancer Pose","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["erector_spinae","hip_flexors"],"d":"advanced","bw":true,"uni":true,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Fléchisseurs de hanche. Se fait d'un côté puis de l'autre.","ins":["Stand tall and shift the weight onto one foot, keeping that knee soft.","Bend the other knee and take hold of the inside of that ankle behind you.","Press the lifted foot back into the hand and reach the opposite arm forward as the chest lifts.","Hold the shape for the prescribed time with the standing hip level and the gaze steady.","Release the foot and repeat on the other side."],"met":5.0},{"id":"db-bench-press","n":"Développé couché aux haltères","en":"Dumbbell Bench Press","c":"strength","eq":"dumbbell","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Lie on a flat bench holding a dumbbell in each hand at chest level.","Press the dumbbells up until your arms are fully extended.","Lower them slowly back to the start.","Repeat."],"met":6.0},{"id":"db-fly","n":"Écartés aux haltères","en":"Dumbbell Fly","c":"strength","eq":"dumbbell","pm":["pectoralis_major"],"sm":["anterior_deltoid"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur.","ins":["Lie flat on a bench with dumbbells held above your chest, palms facing each other.","With a slight bend in the elbows, lower the dumbbells out to the sides.","Return to the start by squeezing your chest.","Repeat."],"met":5.0},{"id":"db-kickstand-deadlift","n":"Soulevé de terre décalé aux haltères (kickstand)","en":"Dumbbell Kickstand Deadlift","c":"strength","eq":"dumbbell","pm":["gluteus_maximus","hamstrings"],"sm":["adductors","erector_spinae"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — haltères. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Adducteurs, Lombaires (érecteurs du rachis). Se fait d'un côté puis de l'autre.","ins":["Stand tall and step one foot back so only the toes lightly touch the floor.","Hold a dumbbell in one hand at hip height.","Hinge at the hips, lowering the dumbbell toward mid-shin while keeping the back flat.","Keep most of your weight on the front foot throughout.","Drive through the front heel to return to standing. Complete all reps, then switch sides."],"met":6.0},{"id":"db-lunge","n":"Fente aux haltères","en":"Dumbbell Lunge","c":"strength","eq":"dumbbell","pm":["gluteus_maximus","quadriceps"],"sm":["hamstrings"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Grand fessier, Quadriceps. En soutien : Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Stand holding dumbbells at your sides.","Step forward with one foot and lower your back knee toward the floor.","Push off the front foot to return.","Alternate legs.","Repeat."],"met":6.0},{"id":"db-overhead-carry","n":"Marche haltère au-dessus de la tête","en":"Dumbbell Overhead Carry","c":"strength","eq":"dumbbell","pm":["anterior_deltoid","lateral_deltoid"],"sm":["obliques","quadratus_lumborum","serratus_anterior","transverse_abdominis","trapezius","triceps_brachii"],"d":"intermediate","bw":false,"uni":true,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — haltères. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Obliques, Carré des lombes, Dentelé antérieur, Transverse, Trapèzes, Triceps. Se fait d'un côté puis de l'autre.","ins":["Clean or press a dumbbell to a locked-out position directly above your shoulder.","Push the arm all the way up so the elbow is straight and the biceps is close to your ear.","Brace your ribs down rather than letting your lower back arch to hold the weight up.","Walk forward with controlled strides, keeping the dumbbell stacked over your shoulder and hip.","Keep your eyes forward — tipping your head back to watch the weight drags your posture with it.","Carry for the desired distance, lower under control, then repeat with the other arm."],"met":5.5},{"id":"db-preacher-curl","n":"Curl pupitre aux haltères","en":"Dumbbell Preacher Curl","c":"strength","eq":"dumbbell","pm":["biceps_brachii"],"sm":["brachialis","brachioradialis"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Biceps. En soutien : Brachial, Brachio-radial.","ins":["Adjust the seat so the armpits rest against the top of the pad and the upper arms lie flat along it.","Hold a dumbbell in each hand with an underhand grip and let the arms hang down along the pad.","Curl both dumbbells up toward the shoulders without lifting the elbows off the pad.","Squeeze the biceps briefly at the top.","Lower the dumbbells slowly until the arms are almost fully extended, then repeat."],"met":5.0},{"id":"db-pullover","n":"Pull-over à l'haltère","en":"Dumbbell Pullover","c":"strength","eq":"dumbbell","pm":["latissimus_dorsi","pectoralis_major"],"sm":["triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — haltères. Travaille surtout : Grand dorsal, Pectoraux. En soutien : Triceps.","ins":["Lie on a flat bench with a dumbbell held above your chest, arms extended.","Lower the dumbbell behind your head in an arc, keeping slight bend in elbows.","Stretch until you feel tension in your lats and chest.","Pull the dumbbell back to the starting position.","Repeat."],"met":6.0},{"id":"db-reverse-curl","n":"Curl inversé aux haltères","en":"Dumbbell Reverse Curl","c":"strength","eq":"dumbbell","pm":["brachialis","forearm_extensors"],"sm":["biceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Brachial, Extenseurs de l'avant-bras. En soutien : Biceps.","ins":["Hold dumbbells with an overhand grip at your sides.","Curl them up to shoulder height.","Lower under control.","Repeat."],"met":5.0},{"id":"db-reverse-wrist-curl","n":"Curl poignets inversé aux haltères","en":"Dumbbell Reverse Wrist Curl","c":"strength","eq":"dumbbell","pm":["forearm_extensors"],"sm":[],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Extenseurs de l'avant-bras.","ins":["Sit on a bench holding a dumbbell in each hand, forearms resting on your thighs, palms down.","Let both wrists drop, lowering the dumbbells toward the floor.","Lift the backs of your hands toward the ceiling by extending your wrists.","Squeeze at the top, then lower under control.","Repeat for the desired number of reps."],"met":5.0},{"id":"db-shrug","n":"Haussements d'épaules aux haltères","en":"Dumbbell Shrug","c":"strength","eq":"dumbbell","pm":["trapezius"],"sm":["rhomboids"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Trapèzes. En soutien : Rhomboïdes.","ins":["Stand holding dumbbells at your sides.","Shrug your shoulders straight up as high as possible.","Hold briefly, then lower.","Repeat."],"met":5.0},{"id":"db-skull-crusher","n":"Barre au front aux haltères","en":"Dumbbell Skull Crusher","c":"strength","eq":"dumbbell","pm":["triceps_brachii"],"sm":[],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Triceps.","ins":["Lie on a flat bench holding dumbbells over your chest.","Lower the dumbbells toward the sides of your head.","Extend your arms back up.","Repeat."],"met":5.0},{"id":"db-somersault-squat","n":"Squat salto à l'haltère","en":"Dumbbell Somersault Squat","c":"strength","eq":"dumbbell","pm":["gluteus_maximus","quadriceps"],"sm":["hamstrings","obliques"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Grand fessier, Quadriceps. En soutien : Ischio-jambiers, Obliques. Se fait d'un côté puis de l'autre.","ins":["Stand with feet shoulder-width holding a dumbbell in one hand at the shoulder.","Squat down while reaching the dumbbell forward and across the body.","Reach the bottom of the squat with the dumbbell extended past the opposite knee.","Drive through the heels to stand up, returning the dumbbell to the shoulder.","Complete reps per side, then switch."],"met":6.0},{"id":"db-squat","n":"Squat aux haltères","en":"Dumbbell Squat","c":"strength","eq":"dumbbell","pm":["gluteus_maximus","quadriceps"],"sm":["hamstrings"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Grand fessier, Quadriceps. En soutien : Ischio-jambiers.","ins":["Stand with feet shoulder-width, a dumbbell in each hand at the sides.","Brace the core and keep the chest up.","Squat down by hinging at the hips and bending the knees.","Descend until the thighs are parallel or below.","Drive through the heels to stand back up."],"met":6.0},{"id":"db-sumo-squat","n":"Squat sumo à l'haltère","en":"Dumbbell Sumo Squat","c":"strength","eq":"dumbbell","pm":["gluteus_maximus","quadriceps"],"sm":["adductors","gluteus_medius","hamstrings"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Grand fessier, Quadriceps. En soutien : Adducteurs, Moyen fessier, Ischio-jambiers.","ins":["Stand with feet wider than shoulder-width, toes turned out about 30 degrees.","Hold a dumbbell in each hand at your sides.","Brace the core and keep the chest up.","Bend at the hips and knees to sit straight down into a deep squat.","Drive through the heels to return to standing.","Repeat for the desired number of reps."],"met":6.0},{"id":"db-svend-press","n":"Svend press à l'haltère","en":"Dumbbell Svend Press","c":"strength","eq":"dumbbell","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Stand and press two dumbbells together horizontally at chest height.","Maintain the inward squeeze on the dumbbells throughout.","Press the dumbbells forward to full arm extension.","Pull them back to the chest under control.","Repeat for the prescribed reps."],"met":5.0},{"id":"dead-bug","n":"Dead bug","en":"Dead Bug","c":"strength","eq":"","pm":["rectus_abdominis","transverse_abdominis"],"sm":["hip_flexors"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Grand droit (abdominaux), Transverse. En soutien : Fléchisseurs de hanche.","ins":["Lie on your back with arms extended toward the ceiling and knees at 90 degrees.","Lower your right arm and left leg toward the floor while keeping the lower back pressed down.","Return to start.","Repeat on the other side.","Alternate."],"met":5.0},{"id":"dead-bug-hold","n":"Dead bug statique","en":"Dead Bug Hold","c":"strength","eq":"","pm":["rectus_abdominis","transverse_abdominis"],"sm":["hip_flexors"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Grand droit (abdominaux), Transverse. En soutien : Fléchisseurs de hanche.","ins":["Lie on your back with the arms pointing at the ceiling and the hips and knees bent to 90 degrees.","Press the lower back into the floor and keep it there for the whole set.","Extend one arm overhead and straighten the opposite leg until both hover just above the floor.","Hold that extended position for the prescribed time without letting the ribs flare or the back arch.","Return to the start and repeat with the other arm and leg."],"met":5.0},{"id":"dead-hang","n":"Suspension passive (dead hang)","en":"Dead Hang","c":"strength","eq":"pull_up_bar","pm":["forearm_flexors"],"sm":["latissimus_dorsi","rectus_abdominis","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — barre de traction. Travaille surtout : Fléchisseurs de l'avant-bras. En soutien : Grand dorsal, Grand droit (abdominaux), Trapèzes.","ins":["Grip a pull-up bar with palms facing away, shoulder-width apart.","Hang with your arms fully extended and feet off the ground.","Relax your shoulders and let your body hang.","Keep your core lightly engaged.","Hold for the desired duration."],"met":4.5},{"id":"deadlift","n":"Soulevé de terre à la barre","en":"Barbell Deadlift","c":"strength","eq":"barbell","pm":["erector_spinae","gluteus_maximus","hamstrings"],"sm":["quadriceps","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre. Travaille surtout : Lombaires (érecteurs du rachis), Grand fessier, Ischio-jambiers. En soutien : Quadriceps, Trapèzes.","ins":["Stand with feet hip-width apart, bar over mid-foot.","Hinge at the hips and grip the bar.","Brace your core and lift by extending hips and knees.","Stand tall at the top, then lower under control.","Repeat."],"met":6.0},{"id":"decline-bench-press","n":"Développé décliné","en":"Decline Bench Press","c":"strength","eq":"dumbbell","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Set the bench to a decline angle. Lie down and secure your feet.","Unrack the barbell and lower it to your lower chest.","Press back up to the start.","Repeat."],"met":6.0},{"id":"decline-bench-press-barbell","n":"Développé décliné à la barre","en":"Decline Barbell Bench Press","c":"strength","eq":"barbell","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Set the bench to a decline angle. Lie down and secure your feet.","Grip the bar slightly wider than shoulder-width.","Lower the bar to your lower chest, then press back up.","Repeat."],"met":6.0},{"id":"decline-bench-press-ez-bar","n":"Développé décliné à la barre EZ","en":"Decline EZ-Bar Bench Press","c":"strength","eq":"ez_bar","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre EZ. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Set the bench to a decline. Secure your feet and grip the EZ-bar.","Lower the bar to your lower chest.","Press back up explosively.","Repeat."],"met":6.0},{"id":"decline-crunch","n":"Crunch décliné","en":"Decline Crunch","c":"strength","eq":"","pm":["rectus_abdominis"],"sm":["hip_flexors","obliques"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée, au poids du corps. Travaille surtout : Grand droit (abdominaux). En soutien : Fléchisseurs de hanche, Obliques.","ins":["Secure your feet at the top of a decline bench.","Lie back with hands crossed on your chest or behind your head.","Crunch up by flexing your spine toward your knees.","Squeeze your abs at the top.","Lower under control and repeat."],"met":3.5},{"id":"decline-db-fly","n":"Écartés déclinés aux haltères","en":"Decline Dumbbell Fly","c":"strength","eq":"dumbbell","pm":["pectoralis_major"],"sm":["anterior_deltoid"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur.","ins":["Lie on a decline bench holding dumbbells above your chest.","With a slight elbow bend, lower the dumbbells wide to each side.","Squeeze the chest to bring them back up.","Repeat."],"met":5.0},{"id":"decline-push-up","n":"Pompes déclinées","en":"Decline Push-Up","c":"strength","eq":"","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Place your feet on an elevated surface and hands on the ground.","Lower your chest to the floor in a controlled manner.","Push back up to the start.","Repeat."],"met":5.0},{"id":"deep-squat-hold","n":"Squat profond statique","en":"Deep Squat Hold","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["adductors","erector_spinae","hamstrings","soleus"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Adducteurs, Lombaires (érecteurs du rachis), Ischio-jambiers, Soléaire.","ins":["Stand with the feet slightly wider than the shoulders and the toes turned out.","Clasp the hands in front of the chest and sit the hips down between the heels.","Lower until the hips are below the knees while the heels stay flat on the floor.","Keep the chest up and press the elbows against the knees to push them out.","Hold the position, breathing steadily, then stand up."],"met":5.0},{"id":"deficit-deadlift","n":"Soulevé de terre en déficit","en":"Deficit Deadlift","c":"strength","eq":"barbell","pm":["erector_spinae","gluteus_maximus","hamstrings"],"sm":["latissimus_dorsi","quadriceps","trapezius"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre. Travaille surtout : Lombaires (érecteurs du rachis), Grand fessier, Ischio-jambiers. En soutien : Grand dorsal, Quadriceps, Trapèzes.","ins":["Stand on a small platform with a loaded barbell over your midfoot.","Hinge down and grip the bar just outside your knees.","Drive through your legs to stand up while keeping the bar close.","Lock out your hips and knees at the top.","Lower under control and repeat."],"met":6.0},{"id":"deficit-push-ups","n":"Pompes en déficit","en":"Deficit Push Ups","c":"strength","eq":"","pm":["pectoralis_major"],"sm":["anterior_deltoid","serratus_anterior","triceps_brachii"],"d":"advanced","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Dentelé antérieur, Triceps.","ins":["Place your hands on two elevated surfaces like parallettes or blocks.","Assume a plank position with hands under your shoulders.","Lower your chest below the level of your hands.","Press back up to extend your arms.","Repeat for the desired number of reps."],"met":5.0},{"id":"diamond-push-ups","n":"Pompes diamant","en":"Diamond Push Ups","c":"strength","eq":"","pm":["pectoralis_major","triceps_brachii"],"sm":["anterior_deltoid","serratus_anterior"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Pectoraux, Triceps. En soutien : Deltoïde antérieur, Dentelé antérieur.","ins":["Assume a push-up position with hands close together forming a diamond.","Keep your elbows tucked close to your sides.","Lower your chest toward your hands.","Press back up to extend your arms.","Repeat for the desired number of reps."],"met":5.0},{"id":"dips","n":"Dips pectoraux","en":"Chest Dips","c":"strength","eq":"dip_station","pm":["pectoralis_major","triceps_brachii"],"sm":["anterior_deltoid"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — station de dips. Travaille surtout : Pectoraux, Triceps. En soutien : Deltoïde antérieur.","ins":["Grip parallel dip bars and lift yourself to the top position with arms locked.","Lean your torso forward slightly.","Lower your body by bending your elbows until shoulders are below elbows.","Press back up to the starting position.","Repeat."],"met":6.0},{"id":"dolphin-pose","n":"Posture du dauphin","en":"Dolphin Pose","c":"strength","eq":"","pm":["anterior_deltoid","trapezius"],"sm":["hamstrings","serratus_anterior"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Deltoïde antérieur, Trapèzes. En soutien : Ischio-jambiers, Dentelé antérieur.","ins":["Kneel and place the forearms on the floor shoulder-width apart with the elbows under the shoulders.","Tuck the toes and lift the hips up and back until the body forms an inverted V.","Press the forearms down and draw the shoulders away from the ears; let the heels stay high.","Hold the position for the prescribed time, keeping the neck relaxed between the arms.","Lower the knees to the floor to come out."],"met":5.0},{"id":"donkey-calf-raise","n":"Mollets à l'âne (donkey calf raise)","en":"Donkey Calf Raise","c":"strength","eq":"","pm":["gastrocnemius"],"sm":["soleus"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée, au poids du corps. Travaille surtout : Mollets (gastrocnémiens). En soutien : Soléaire.","ins":["Bend at the hips and rest the forearms on a bench or sturdy support.","Place the balls of the feet on a raised platform with heels free.","Drop the heels below platform level for a full stretch.","Drive up onto the toes as high as possible, squeezing the calves.","Lower under control to a deep stretch."],"met":3.5},{"id":"doorway-chest-stretch","n":"Étirement des pectoraux dans l'encadrement de porte","en":"Doorway Chest Stretch","c":"stretching","eq":"","pm":["pectoralis_major"],"sm":["anterior_deltoid"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur.","ins":["Stand tall and raise your arms into a goalpost position.","Bend your elbows ninety degrees, forearms vertical.","Draw your elbows back and squeeze your shoulder blades.","Hold for 20 to 30 seconds, breathing steadily."],"met":5.0},{"id":"double-db-kickstand-deadlift","n":"Soulevé de terre décalé avec deux haltères","en":"Double Dumbbell Kickstand Deadlift","c":"strength","eq":"dumbbell","pm":["gluteus_maximus","hamstrings"],"sm":["adductors","erector_spinae"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — haltères. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Adducteurs, Lombaires (érecteurs du rachis). Se fait d'un côté puis de l'autre.","ins":["Stand tall and step one foot back so only the toes touch the floor.","Hold a dumbbell in each hand at hip height.","Hinge at the hips, lowering both dumbbells toward mid-shin while keeping the back flat.","Keep most of your weight on the front foot throughout.","Drive through the front heel to return to standing. Switch sides after all reps."],"met":6.0},{"id":"double-db-overhead-carry","n":"Marche deux haltères au-dessus de la tête","en":"Double Dumbbell Overhead Carry","c":"strength","eq":"dumbbell","pm":["anterior_deltoid","lateral_deltoid"],"sm":["erector_spinae","serratus_anterior","transverse_abdominis","trapezius","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — haltères. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Lombaires (érecteurs du rachis), Dentelé antérieur, Transverse, Trapèzes, Triceps.","ins":["Clean or press a dumbbell to lockout above each shoulder.","Straighten both elbows fully and pull your shoulder blades up into the weights rather than shrugging away from them.","Brace hard and keep your ribs down — with both arms overhead the temptation to arch is much stronger.","Walk forward with short, deliberate strides, keeping both dumbbells stacked over your shoulders.","Keep breathing shallowly and steadily instead of holding your breath for the whole carry.","Carry for the desired distance, then lower both weights under control."],"met":5.5},{"id":"double-kettlebell-bicep-curl","n":"Curl biceps avec deux KB","en":"Double Kettlebell Bicep Curl","c":"strength","eq":"kettlebell","pm":["biceps_brachii"],"sm":["brachialis","forearm_flexors"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — kettlebell. Travaille surtout : Biceps. En soutien : Brachial, Fléchisseurs de l'avant-bras.","ins":["Stand holding a kettlebell in each hand by the handle, palms facing forward.","Keep the elbows tucked to the sides and the bells hanging at arm length.","Curl both kettlebells up toward the shoulders by flexing the elbows.","Squeeze the biceps at the top, then lower under control to the starting position.","Repeat for the recommended number of repetitions."],"met":5.0},{"id":"double-kettlebell-clean","n":"Épaulé avec deux KB","en":"Double Kettlebell Clean","c":"strength","eq":"kettlebell","pm":["gluteus_maximus","hamstrings"],"sm":["anterior_deltoid","erector_spinae","forearm_flexors","trapezius"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — kettlebell. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Deltoïde antérieur, Lombaires (érecteurs du rachis), Fléchisseurs de l'avant-bras, Trapèzes.","ins":["Stand with two kettlebells on the floor between your feet, handles angled slightly inward.","Hinge at the hips, grip the handles, and hike the kettlebells back between the legs.","Explosively extend the hips to drive the kettlebells up along the body.","As they reach chest height, spear your hands through the handles to catch them at the rack position on the shoulders.","Lower back to the hang by hinging at the hips and guiding the bells between the legs.","Repeat for the recommended number of repetitions."],"met":8.0},{"id":"double-kettlebell-clean-and-press","n":"Épaulé-développé avec deux KB","en":"Double Kettlebell Clean and Press","c":"strength","eq":"kettlebell","pm":["anterior_deltoid","lateral_deltoid"],"sm":["gluteus_maximus","quadriceps","rectus_abdominis","trapezius","triceps_brachii"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Grand fessier, Quadriceps, Grand droit (abdominaux), Trapèzes, Triceps.","ins":["Stand with two kettlebells on the floor between your feet, feet about hip-width apart, and hinge at the hips to grip one handle in each hand.","Drive through your legs and extend your hips explosively to pull both kettlebells up, then rotate your elbows under and catch the bells in the racked position at the front of your shoulders.","Brace your core and press both kettlebells overhead until your arms are fully locked out.","Lower the kettlebells back to the racked position, then down to the floor under control.","Repeat for the desired number of reps."],"met":8.0},{"id":"double-kettlebell-dead-clean","n":"Épaulé depuis le sol avec deux KB","en":"Double Kettlebell Dead Clean","c":"olympic","eq":"kettlebell","pm":["gluteus_maximus","hamstrings"],"sm":["erector_spinae","forearm_flexors","quadriceps","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Mouvement d'haltérophilie — kettlebell. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis), Fléchisseurs de l'avant-bras, Quadriceps, Trapèzes.","ins":["Set two kettlebells on the floor between your feet.","Hinge down and grip both handles.","Drive explosively through your legs and hips.","Pull the kettlebells up and rotate them to the rack position.","Lower them back to the floor and repeat."],"met":8.0},{"id":"double-kettlebell-dead-split-snatch","n":"Arraché fendu depuis le sol avec deux KB","en":"Double Kettlebell Dead Split Snatch","c":"olympic","eq":"kettlebell","pm":["anterior_deltoid","gluteus_maximus"],"sm":["erector_spinae","hamstrings","quadriceps","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Mouvement d'haltérophilie — kettlebell. Travaille surtout : Deltoïde antérieur, Grand fessier. En soutien : Lombaires (érecteurs du rachis), Ischio-jambiers, Quadriceps, Trapèzes.","ins":["Set two kettlebells on the floor between your feet.","Hinge down and grip both handles firmly.","Explosively pull the kettlebells overhead in one motion.","Drop into a split stance to catch them at lockout.","Recover by stepping feet back together."],"met":8.0},{"id":"double-kettlebell-jerk","n":"Jeté avec deux KB","en":"Double Kettlebell Jerk","c":"strength","eq":"kettlebell","pm":["anterior_deltoid","quadriceps"],"sm":["gluteus_maximus","trapezius","triceps_brachii"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Deltoïde antérieur, Quadriceps. En soutien : Grand fessier, Trapèzes, Triceps.","ins":["Start with two kettlebells racked on the shoulders, elbows resting on the hips.","Perform a short dip at the knees, then explosively extend the legs to drive the kettlebells up.","As the bells rise, perform a second dip under them by bending the knees again.","Catch the kettlebells overhead with arms locked out, then stand fully upright.","Lower them back to the rack under control and repeat."],"met":8.0},{"id":"double-kettlebell-overhead-carry","n":"Marche deux KB au-dessus de la tête","en":"Double Kettlebell Overhead Carry","c":"strength","eq":"kettlebell","pm":["anterior_deltoid","lateral_deltoid"],"sm":["erector_spinae","forearm_extensors","serratus_anterior","transverse_abdominis","trapezius","triceps_brachii"],"d":"advanced","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — kettlebell. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Lombaires (érecteurs du rachis), Extenseurs de l'avant-bras, Dentelé antérieur, Transverse, Trapèzes, Triceps.","ins":["Clean two kettlebells to the rack, then press or push press both to lockout overhead.","Straighten both elbows and settle each bell behind and above its wrist, with your wrists straight.","Pull your ribs down and brace hard before the first step; with both bells overhead there is nothing to counterbalance with.","Walk forward with short, controlled strides, keeping both bells stacked over your shoulders.","Keep looking straight ahead and breathe steadily through the carry.","Cover the desired distance, then lower both bells to the rack and down under control."],"met":5.5},{"id":"double-kettlebell-overhead-press","n":"Développé militaire avec deux KB","en":"Double Kettlebell Overhead Press","c":"strength","eq":"kettlebell","pm":["anterior_deltoid","triceps_brachii"],"sm":["rectus_abdominis","serratus_anterior","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Deltoïde antérieur, Triceps. En soutien : Grand droit (abdominaux), Dentelé antérieur, Trapèzes.","ins":["Clean two kettlebells to the rack position at your shoulders.","Stand tall with feet hip-width apart.","Press both kettlebells straight overhead.","Lock out your arms at the top.","Lower back to the rack position and repeat."],"met":6.0},{"id":"double-kettlebell-push-press","n":"Push press avec deux KB","en":"Double Kettlebell Push Press","c":"strength","eq":"kettlebell","pm":["anterior_deltoid"],"sm":["gluteus_maximus","lateral_deltoid","quadriceps","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Deltoïde antérieur. En soutien : Grand fessier, Deltoïde latéral, Quadriceps, Triceps.","ins":["Stand with two kettlebells racked at the shoulders, elbows down and tucked.","Feet shoulder-width, core braced.","Dip the knees slightly while keeping the torso vertical.","Explosively extend the legs and press both bells overhead in one motion.","Lock out with the bells over the mid-foot.","Lower back to the rack under control.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"double-kettlebell-rear-delt-row","n":"Rowing arrière d'épaule avec deux KB","en":"Double Kettlebell Rear Delt Row","c":"strength","eq":"kettlebell","pm":["posterior_deltoid","rhomboids"],"sm":["biceps_brachii","erector_spinae","latissimus_dorsi","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — kettlebell. Travaille surtout : Deltoïde postérieur, Rhomboïdes. En soutien : Biceps, Lombaires (érecteurs du rachis), Grand dorsal, Trapèzes.","ins":["Stand a kettlebell just outside each foot with your feet about hip-width apart.","Hinge at the hips with a flat back until your torso is close to parallel with the floor, letting your knees bend slightly.","Take both handles with an overhand grip and let your arms hang straight down from your shoulders.","Row both bells up by driving your elbows out to the sides, away from your ribs rather than back along them.","Stop when your upper arms are roughly in line with your shoulders, and squeeze your shoulder blades together.","Lower the bells under control until your arms hang straight again, and repeat for the desired reps."],"met":6.0},{"id":"double-kettlebell-row","n":"Rowing avec deux KB","en":"Double Kettlebell Row","c":"strength","eq":"kettlebell","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","erector_spinae","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — kettlebell. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Lombaires (érecteurs du rachis), Trapèzes.","ins":["Hold a kettlebell in each hand and hinge forward at the hips.","Let your arms hang straight down from your shoulders.","Row both kettlebells to your hips by driving elbows back.","Squeeze your shoulder blades at the top.","Lower under control and repeat."],"met":6.0},{"id":"double-kettlebell-split-jerk","n":"Jeté fendu avec deux KB","en":"Double Kettlebell Split Jerk","c":"olympic","eq":"kettlebell","pm":["anterior_deltoid","quadriceps"],"sm":["gluteus_maximus","trapezius","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Mouvement d'haltérophilie — kettlebell. Travaille surtout : Deltoïde antérieur, Quadriceps. En soutien : Grand fessier, Trapèzes, Triceps.","ins":["Clean two kettlebells to the rack position at your shoulders.","Dip slightly by bending your knees.","Drive the kettlebells overhead explosively.","Split your legs to catch them with locked arms.","Recover by stepping feet back together."],"met":8.0},{"id":"double-kettlebell-swing-snatch","n":"Swing-arraché avec deux KB","en":"Double Kettlebell Swing Snatch","c":"olympic","eq":"kettlebell","pm":["gluteus_maximus","hamstrings"],"sm":["anterior_deltoid","erector_spinae","forearm_flexors","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Mouvement d'haltérophilie — kettlebell. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Deltoïde antérieur, Lombaires (érecteurs du rachis), Fléchisseurs de l'avant-bras, Trapèzes.","ins":["Stand with feet shoulder-width apart holding two kettlebells.","Hinge at the hips to swing the bells between your legs.","Explosively drive your hips forward to swing the bells up.","Punch through to catch both kettlebells overhead with locked arms.","Lower under control and repeat."],"met":8.0},{"id":"downward-dog","n":"Chien tête en bas","en":"Downward-Facing Dog","c":"stretching","eq":"","pm":["gastrocnemius","hamstrings"],"sm":["erector_spinae","gluteus_maximus","latissimus_dorsi"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Mollets (gastrocnémiens), Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis), Grand fessier, Grand dorsal.","ins":["Start on all fours with hands slightly ahead of your shoulders.","Tuck your toes and lift your hips up and back.","Straighten your legs and press your heels toward the floor.","Hold for 20 to 30 seconds, breathing steadily."],"met":5.0},{"id":"downward-dog-knee-tuck","n":"Chien tête en bas avec genou rentré","en":"Downward Dog Knee Tuck","c":"strength","eq":"","pm":["hip_flexors","rectus_abdominis"],"sm":["anterior_deltoid","serratus_anterior","transverse_abdominis"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Deltoïde antérieur, Dentelé antérieur, Transverse.","ins":["Set up in downward dog with the hands shoulder-width apart and the hips high.","Press the floor away and brace the trunk so the lower back stays long.","Draw one knee in towards the chest, rounding the upper back slightly as it comes in.","Extend the leg back to the starting position under control.","Repeat with the other leg and keep alternating for the desired number of repetitions."],"met":5.0},{"id":"downward-dog-pedal","n":"Chien tête en bas en pédalant","en":"Downward Dog Pedal","c":"stretching","eq":"","pm":["gastrocnemius","soleus"],"sm":["hamstrings"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Étirement, au poids du corps. Travaille surtout : Mollets (gastrocnémiens), Soléaire. En soutien : Ischio-jambiers.","ins":["Set up in downward dog with the hands shoulder-width apart and the hips high.","Bend one knee and let that heel lift while the opposite heel presses down towards the floor.","Switch sides smoothly, as if pedalling, keeping the hips high throughout.","Keep the hands pressing evenly so the shoulders stay stable.","Continue alternating for the desired number of repetitions or time."],"met":5.0},{"id":"downward-dog-to-knee-drive","n":"Chien tête en bas vers montée de genou","en":"Downward Dog to Knee Drive","c":"strength","eq":"","pm":["hip_flexors","rectus_abdominis"],"sm":["anterior_deltoid","gluteus_maximus","serratus_anterior"],"d":"intermediate","bw":true,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Deltoïde antérieur, Grand fessier, Dentelé antérieur. Se fait d'un côté puis de l'autre.","ins":["Set up in downward dog and lift one leg behind you into three-legged dog.","Press both hands down and shift the weight slightly forward.","Round the upper back and drive that knee forward towards the elbow or the nose.","Extend the leg back up to three-legged dog under control.","Finish the repetitions on that side and repeat on the other."],"met":5.0},{"id":"downward-dog-to-low-lunge","n":"Chien tête en bas vers fente basse","en":"Downward Dog to Low Lunge","c":"stretching","eq":"","pm":["hip_flexors"],"sm":["gluteus_maximus","quadriceps"],"d":"beginner","bw":true,"uni":true,"img":["start","peak"],"desc":"Étirement, au poids du corps. Travaille surtout : Fléchisseurs de hanche. En soutien : Grand fessier, Quadriceps. Se fait d'un côté puis de l'autre.","ins":["Start in downward dog with the hands shoulder-width apart.","Shift the weight forward and step one foot up between the hands.","Lower the back knee to the floor and sink the hips into a low lunge.","Press back through the hands, lift the back knee and step the front foot back to downward dog.","Repeat on the other side and keep alternating."],"met":5.0},{"id":"downward-dog-to-plank","n":"Chien tête en bas vers planche","en":"Downward Dog to Plank","c":"strength","eq":"","pm":["anterior_deltoid","rectus_abdominis"],"sm":["hamstrings","serratus_anterior","trapezius"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Deltoïde antérieur, Grand droit (abdominaux). En soutien : Ischio-jambiers, Dentelé antérieur, Trapèzes.","ins":["Set up in downward dog with the hips high and the hands shoulder-width apart.","Shift the weight forward and lower the hips until the body forms a straight line in a high plank.","Hold the plank for a moment with the ribs down and the glutes engaged.","Press the floor away and lift the hips back up into downward dog.","Continue alternating for the desired number of repetitions."],"met":5.0},{"id":"downward-dog-to-upward-dog","n":"Chien tête en bas vers chien tête en haut","en":"Downward Dog to Upward Dog","c":"strength","eq":"","pm":["anterior_deltoid","erector_spinae"],"sm":["pectoralis_major","serratus_anterior","triceps_brachii"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Deltoïde antérieur, Lombaires (érecteurs du rachis). En soutien : Pectoraux, Dentelé antérieur, Triceps.","ins":["Start in downward dog with the hips high and the hands shoulder-width apart.","Shift forward through plank and lower slightly, then press the chest through into upward dog with the thighs off the floor.","Draw the shoulders back and down and keep the neck long.","Tuck the toes, press the floor away and lift the hips back into downward dog.","Continue moving between the two positions for the desired number of repetitions."],"met":5.0},{"id":"drag-curl","n":"Drag curl","en":"Drag Curl","c":"strength","eq":"barbell","pm":["biceps_brachii"],"sm":["brachialis"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre. Travaille surtout : Biceps. En soutien : Brachial.","ins":["Stand holding a barbell with an underhand grip, hands shoulder-width apart.","Start with the bar at the thighs and elbows at the sides.","Curl the bar by sliding (dragging) it straight up along your body.","As the bar rises, let the elbows travel backward so the bar stays in contact with your torso.","Stop when the bar reaches mid-chest; the biceps will be fully shortened.","Lower under control along the same path and repeat."],"met":5.0},{"id":"dragon-flag","n":"Dragon flag","en":"Dragon Flag","c":"strength","eq":"","pm":["rectus_abdominis"],"sm":["erector_spinae","hip_flexors","obliques","transverse_abdominis"],"d":"advanced","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Grand droit (abdominaux). En soutien : Lombaires (érecteurs du rachis), Fléchisseurs de hanche, Obliques, Transverse.","ins":["Lie on a bench and grip it firmly behind your head.","Raise your body up so only your upper back stays on the bench.","Keep your body rigid in a straight line.","Lower your body under control until nearly horizontal.","Raise back up and repeat."],"met":5.0},{"id":"dumbbell-bench-pull","n":"Tirage allongé sur banc aux haltères","en":"Dumbbell Bench Pull","c":"strength","eq":"dumbbell","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","posterior_deltoid"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — haltères. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Deltoïde postérieur.","ins":["Lie face down on an incline bench holding dumbbells.","Let your arms hang straight down.","Pull the dumbbells up toward your chest, squeezing your shoulder blades.","Lower with control.","Repeat."],"met":6.0},{"id":"dumbbell-calf-raise","n":"Mollets aux haltères","en":"Dumbbell Calf Raise","c":"strength","eq":"dumbbell","pm":["gastrocnemius","soleus"],"sm":["forearm_flexors"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Mollets (gastrocnémiens), Soléaire. En soutien : Fléchisseurs de l'avant-bras.","ins":["Stand holding a dumbbell in each hand at your sides.","Place the balls of your feet on a raised surface with heels hanging off.","Press through the balls of your feet to raise your heels as high as possible.","Squeeze your calves at the top of the movement.","Lower your heels below the platform to stretch the calves.","Repeat for the desired number of reps."],"met":5.0},{"id":"dumbbell-clean-and-press","n":"Épaulé-développé aux haltères","en":"Dumbbell Clean and Press","c":"olympic","eq":"dumbbell","pm":["anterior_deltoid","gluteus_maximus","quadriceps"],"sm":["erector_spinae","trapezius","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Mouvement d'haltérophilie — haltères. Travaille surtout : Deltoïde antérieur, Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Trapèzes, Triceps.","ins":["Stand with the feet hip-width apart and a dumbbell in each hand, hanging at your sides.","Hinge at the hips and bend the knees slightly to lower the dumbbells to just below the knees.","Explosively extend the hips and knees and shrug to pull the dumbbells up to the shoulders, catching them with the elbows forward.","Dip slightly at the knees and drive the dumbbells straight overhead until the arms are locked out.","Lower the dumbbells back to the shoulders, then to your sides, under control.","Repeat for the desired number of repetitions."],"met":8.0},{"id":"dumbbell-curl-and-press","n":"Curl et développé aux haltères","en":"Dumbbell Curl and Press","c":"strength","eq":"dumbbell","pm":["anterior_deltoid","biceps_brachii"],"sm":["brachialis","lateral_deltoid","trapezius","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Deltoïde antérieur, Biceps. En soutien : Brachial, Deltoïde latéral, Trapèzes, Triceps.","ins":["Stand tall with the feet hip-width apart, holding a dumbbell in each hand at your sides with the palms facing forward.","Curl both dumbbells up to the shoulders, keeping the elbows close to the body.","Press the dumbbells overhead until the arms are fully extended.","Lower the dumbbells back to the shoulders under control.","Lower them to your sides with a controlled reverse curl, then repeat."],"met":6.0},{"id":"dumbbell-deadlift","n":"Soulevé de terre aux haltères","en":"Dumbbell Deadlift","c":"strength","eq":"dumbbell","pm":["erector_spinae","gluteus_maximus","hamstrings"],"sm":["latissimus_dorsi","quadriceps","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — haltères. Travaille surtout : Lombaires (érecteurs du rachis), Grand fessier, Ischio-jambiers. En soutien : Grand dorsal, Quadriceps, Trapèzes.","ins":["Stand with dumbbells in front of your thighs, feet hip-width apart.","Hinge at the hips and lower the dumbbells along your legs with a flat back.","Keep the dumbbells close to your shins throughout the descent.","Drive through your heels to return to standing.","Extend your hips fully at the top without hyperextending your lower back.","Repeat for the desired number of reps."],"met":6.0},{"id":"dumbbell-face-pull","n":"Face pull aux haltères","en":"Dumbbell Face Pull","c":"strength","eq":"dumbbell","pm":["posterior_deltoid","rhomboids"],"sm":["biceps_brachii","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Deltoïde postérieur, Rhomboïdes. En soutien : Biceps, Trapèzes.","ins":["Stand or sit holding a dumbbell in each hand with arms extended forward.","Bend your elbows and pull the dumbbells toward your face.","Flare your elbows out wide to shoulder height.","Squeeze your rear delts and upper back at the peak.","Lower the dumbbells back under control.","Repeat for the desired number of reps."],"met":5.0},{"id":"dumbbell-farmers-walk","n":"Marche du fermier aux haltères","en":"Dumbbell Farmer's Walk","c":"strength","eq":"dumbbell","pm":["forearm_flexors","trapezius"],"sm":["gluteus_maximus","obliques","quadriceps","rectus_abdominis"],"d":"beginner","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — haltères. Travaille surtout : Fléchisseurs de l'avant-bras, Trapèzes. En soutien : Grand fessier, Obliques, Quadriceps, Grand droit (abdominaux).","ins":["Stand tall with a dumbbell in each hand, arms extended at your sides.","Retract your shoulder blades and brace your core, maintaining a neutral spine.","Walk slowly and deliberately for a set distance or duration, taking short, controlled steps.","Keep your chest up and avoid leaning to one side as you walk.","Focus on maintaining a strong, stable posture throughout the movement."],"met":5.5},{"id":"dumbbell-floor-press","n":"Développé au sol aux haltères","en":"Dumbbell Floor Press","c":"strength","eq":"dumbbell","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Lie on the floor with a dumbbell in each hand at chest level.","Press the dumbbells upward until arms are extended.","Lower under control until elbows touch the floor.","Repeat."],"met":6.0},{"id":"dumbbell-front-raise","n":"Élévation frontale aux haltères","en":"Dumbbell Front Raise","c":"strength","eq":"dumbbell","pm":["anterior_deltoid"],"sm":["lateral_deltoid"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Deltoïde antérieur. En soutien : Deltoïde latéral.","ins":["Stand with dumbbells at your sides, palms facing your thighs.","Raise one or both dumbbells forward to shoulder height.","Lower under control.","Repeat."],"met":5.0},{"id":"dumbbell-front-squat","n":"Squat avant aux haltères","en":"Dumbbell Front Squat","c":"strength","eq":"dumbbell","pm":["gluteus_maximus","quadriceps"],"sm":["erector_spinae","hamstrings","rectus_abdominis"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Ischio-jambiers, Grand droit (abdominaux).","ins":["Hold a dumbbell in each hand resting on top of your shoulders.","Keep your elbows high and torso upright.","Lower your hips by bending knees until thighs are parallel to the floor.","Drive through your heels to stand back up.","Maintain a neutral spine throughout.","Repeat for the desired number of reps."],"met":6.0},{"id":"dumbbell-hip-thrust","n":"Hip thrust à l'haltère","en":"Dumbbell Hip Thrust","c":"strength","eq":"dumbbell","pm":["gluteus_maximus"],"sm":["hamstrings","quadriceps"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Grand fessier. En soutien : Ischio-jambiers, Quadriceps.","ins":["Sit on the floor with your upper back against a bench, knees bent, feet flat, and a dumbbell across your hips.","Brace your core and drive through your heels, lifting your hips off the floor until your body forms a straight line from shoulders to knees.","Squeeze your glutes powerfully at the top of the movement, ensuring full hip extension.","Slowly lower your hips back down to the starting position with control, maintaining tension.","Repeat for the desired number of repetitions."],"met":6.0},{"id":"dumbbell-pistol-squat","n":"Pistol squat à l'haltère","en":"Dumbbell Pistol Squat","c":"strength","eq":"dumbbell","pm":["gluteus_maximus","quadriceps"],"sm":["gluteus_medius","hamstrings"],"d":"advanced","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Grand fessier, Quadriceps. En soutien : Moyen fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Stand tall, holding a dumbbell in each hand with your arms hanging at your sides.","Lift one leg straight out in front of you, keeping it extended throughout the movement.","Lower your body by bending the knee of your standing leg, keeping your chest up and back straight.","Descend until your glutes are close to your heel or your thigh is parallel to the floor, maintaining balance.","Push through your heel to return to the starting position, extending your standing leg fully.","Complete all reps on one side, then switch legs and repeat for the other side per set."],"met":6.0},{"id":"dumbbell-push-press","n":"Push press aux haltères","en":"Dumbbell Push Press","c":"strength","eq":"dumbbell","pm":["anterior_deltoid","triceps_brachii"],"sm":["gluteus_maximus","lateral_deltoid","quadriceps","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Deltoïde antérieur, Triceps. En soutien : Grand fessier, Deltoïde latéral, Quadriceps, Trapèzes.","ins":["Stand holding dumbbells at shoulder height with palms facing forward.","Slightly bend your knees into a quarter squat.","Drive through your legs to generate momentum, then press the dumbbells overhead.","Lock out your arms at the top.","Lower the dumbbells back to shoulder height with control."],"met":6.0},{"id":"dumbbell-reverse-fly","n":"Oiseau aux haltères (reverse fly)","en":"Dumbbell Reverse Fly","c":"strength","eq":"dumbbell","pm":["posterior_deltoid"],"sm":["rhomboids","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Deltoïde postérieur. En soutien : Rhomboïdes, Trapèzes.","ins":["Hinge forward at the hips holding dumbbells with arms hanging down.","Keep your back flat and knees slightly bent.","Raise the dumbbells out to the sides until level with your shoulders.","Squeeze your shoulder blades together at the top.","Lower the dumbbells back with control.","Repeat for the desired number of reps."],"met":5.0},{"id":"dumbbell-romanian-deadlift","n":"Soulevé de terre roumain aux haltères","en":"Dumbbell Romanian Deadlift","c":"strength","eq":"dumbbell","pm":["gluteus_maximus","hamstrings"],"sm":["erector_spinae","forearm_flexors"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — haltères. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis), Fléchisseurs de l'avant-bras.","ins":["Stand holding dumbbells in front of your thighs with a soft knee bend.","Hinge at the hips and push your glutes back.","Lower the dumbbells along your legs until you feel a hamstring stretch.","Keep your back flat and shoulders pulled back.","Drive your hips forward to return to standing.","Repeat for the desired number of reps."],"met":6.0},{"id":"dumbbell-shoulder-press","n":"Développé épaules aux haltères","en":"Dumbbell Shoulder Press","c":"strength","eq":"dumbbell","pm":["anterior_deltoid","lateral_deltoid"],"sm":["trapezius","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Trapèzes, Triceps.","ins":["Sit or stand holding dumbbells at shoulder height, palms facing forward.","Press both dumbbells overhead until arms are fully extended.","Keep your core braced and avoid arching your lower back.","Lower the dumbbells under control back to shoulder height.","Do not let the dumbbells drift behind your head.","Repeat for the desired number of reps."],"met":6.0},{"id":"dumbbell-side-bend","n":"Flexion latérale à l'haltère","en":"Dumbbell Side Bend","c":"strength","eq":"dumbbell","pm":["obliques"],"sm":["erector_spinae","quadratus_lumborum","transverse_abdominis"],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Obliques. En soutien : Lombaires (érecteurs du rachis), Carré des lombes, Transverse. Se fait d'un côté puis de l'autre.","ins":["Stand upright holding a dumbbell in one hand at your side.","Keep the opposite hand on your hip or behind your head.","Bend laterally toward the dumbbell side, lowering it along your thigh.","Return to upright, then bend to the opposite side using only your obliques.","Complete all reps per side."],"met":5.0},{"id":"dumbbell-snatch","n":"Arraché à l'haltère","en":"Dumbbell Snatch","c":"olympic","eq":"dumbbell","pm":["anterior_deltoid","gluteus_maximus","trapezius"],"sm":["erector_spinae","hamstrings","quadriceps"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Mouvement d'haltérophilie — haltères. Travaille surtout : Deltoïde antérieur, Grand fessier, Trapèzes. En soutien : Lombaires (érecteurs du rachis), Ischio-jambiers, Quadriceps.","ins":["Stand with feet shoulder-width apart, dumbbell on the floor between your feet.","Hinge and grip the dumbbell with one hand.","Explosively extend hips, knees, and ankles to pull the dumbbell upward.","Punch the dumbbell overhead in one fluid motion.","Lock out your arm and stabilize at the top.","Complete reps on one side, then switch."],"met":8.0},{"id":"dumbbell-split-squat","n":"Fente statique aux haltères","en":"Dumbbell Split Squat","c":"strength","eq":"dumbbell","pm":["gluteus_maximus","quadriceps"],"sm":["gluteus_medius","hamstrings"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Grand fessier, Quadriceps. En soutien : Moyen fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Stand in a split stance holding dumbbells at your sides.","Keep your torso upright and core braced.","Lower your back knee toward the floor by bending both knees.","Stop when your front thigh is parallel to the floor.","Drive through your front heel to return to standing.","Complete reps on one side, then switch."],"met":6.0},{"id":"dumbbell-tricep-extension","n":"Extension triceps à l'haltère","en":"Dumbbell Tricep Extension","c":"strength","eq":"dumbbell","pm":["triceps_brachii"],"sm":[],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Triceps.","ins":["Stand holding a dumbbell in one hand overhead.","Lower the dumbbell behind your head by bending your elbow.","Extend your arm back to the starting position.","Keep your elbow close to your head.","Repeat on both sides."],"met":5.0},{"id":"dumbbell-upright-row","n":"Rowing menton aux haltères","en":"Dumbbell Upright Row","c":"strength","eq":"dumbbell","pm":["lateral_deltoid","trapezius"],"sm":["anterior_deltoid","biceps_brachii","rhomboids"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — haltères. Travaille surtout : Deltoïde latéral, Trapèzes. En soutien : Deltoïde antérieur, Biceps, Rhomboïdes.","ins":["Stand holding two dumbbells in front of your thighs, palms facing your body.","Pull the dumbbells straight up along your body, leading with your elbows.","Raise until the dumbbells reach chin height and elbows are above the wrists.","Pause briefly, then lower with control.","Repeat for the desired reps."],"met":6.0},{"id":"dumbbell-windmill","n":"Moulin à vent à l'haltère","en":"Dumbbell Windmill","c":"strength","eq":"dumbbell","pm":["lateral_deltoid","obliques"],"sm":["anterior_deltoid","gluteus_medius","hamstrings"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — haltères. Travaille surtout : Deltoïde latéral, Obliques. En soutien : Deltoïde antérieur, Moyen fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Stand with feet shoulder-width apart, holding a dumbbell overhead in one hand, arm locked.","Turn your feet slightly away from the dumbbell side, keeping the arm straight and eyes on the weight.","Hinge at your hips, pushing them out to the side of the dumbbell, and slowly lower your torso towards the floor.","Keep your back straight and the dumbbell arm vertical as you reach your free hand towards your foot or the floor.","Reverse the motion by driving through your hips and obliques to return to the starting position.","Complete all reps on one side, then switch and repeat for the other side."],"met":5.0},{"id":"dumbbell-wrist-curl","n":"Curl poignets aux haltères","en":"Dumbbell Wrist Curl","c":"strength","eq":"dumbbell","pm":["forearm_flexors"],"sm":["brachioradialis"],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Fléchisseurs de l'avant-bras. En soutien : Brachio-radial. Se fait d'un côté puis de l'autre.","ins":["Sit on a bench with the forearm resting on the thigh, palm up.","Hold a dumbbell with the wrist hanging off the knee.","Let the dumbbell roll down to the fingertips.","Curl the dumbbell up by flexing the wrist.","Lower under control. Complete reps per side."],"met":5.0},{"id":"eagle-pose","n":"Posture de l'aigle","en":"Eagle Pose","c":"strength","eq":"","pm":["gluteus_medius","quadriceps"],"sm":["posterior_deltoid","trapezius"],"d":"intermediate","bw":true,"uni":true,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Moyen fessier, Quadriceps. En soutien : Deltoïde postérieur, Trapèzes. Se fait d'un côté puis de l'autre.","ins":["Stand tall, bend both knees slightly and shift the weight onto one foot.","Cross the other thigh over the standing thigh and hook the foot behind the calf if it reaches.","Cross the opposite arm underneath, wind the forearms and bring the palms towards each other.","Sit down a little into the standing leg and hold for the prescribed time with the elbows lifted.","Unwind and repeat on the other side."],"met":5.0},{"id":"easy-pose","n":"Posture facile","en":"Easy Pose","c":"stretching","eq":"","pm":["erector_spinae"],"sm":["adductors","gluteus_medius"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis). En soutien : Adducteurs, Moyen fessier.","ins":["Sit on the floor and cross the shins comfortably, each foot under the opposite knee.","Sit up on a folded blanket or cushion until the knees rest below the level of the hips.","Stack the ribs over the pelvis and let the hands rest on the thighs.","Hold the seat for the prescribed time, breathing slowly and evenly.","Switch which shin is in front on the next round so both sides get equal time."],"met":1.5},{"id":"elliptical-trainer","n":"Vélo elliptique","en":"Elliptical Trainer","c":"cardio","eq":"elliptical","pm":["gluteus_maximus","quadriceps"],"sm":["gastrocnemius","hamstrings","latissimus_dorsi","pectoralis_major","soleus","triceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["main"],"desc":"Exercice cardio — vélo elliptique. Travaille surtout : Grand fessier, Quadriceps. En soutien : Mollets (gastrocnémiens), Ischio-jambiers, Grand dorsal, Pectoraux, Soléaire, Triceps.","ins":["Step onto the foot plates one at a time, holding the fixed centre post until you are steady, then take a moving handle in each hand.","Start the pedals turning forward, keeping your whole foot down on the plate rather than lifting your heel.","Push one handle away as the same-side foot travels forward, and pull the other back, so the arms and legs work in opposition.","Stand tall with your hips over the pedals and your core braced instead of hanging back on the handles.","Set the resistance and ramp so you can hold a smooth stride, and continue for the desired time or distance."],"met":8.0},{"id":"extended-side-angle","n":"Posture de l'angle latéral étendu","en":"Extended Side Angle Pose","c":"strength","eq":"","pm":["obliques","quadriceps"],"sm":["adductors","gluteus_medius"],"d":"intermediate","bw":true,"uni":true,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Obliques, Quadriceps. En soutien : Adducteurs, Moyen fessier. Se fait d'un côté puis de l'autre.","ins":["Stand wide with the front foot turned out and the back foot angled slightly in.","Bend the front knee until it stacks over the ankle and keep the back leg straight.","Rest the front forearm on the thigh, or the hand on the floor or a block, and reach the top arm over the ear.","Hold the position for the prescribed time, turning the chest towards the ceiling.","Straighten the front leg to come up and repeat on the other side."],"met":5.0},{"id":"ez-bar-bench-press","n":"Développé couché à la barre EZ","en":"EZ-Bar Bench Press","c":"strength","eq":"ez_bar","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre EZ. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Lie flat on a bench with your feet planted on the floor, gripping the EZ bar's angled bends over your chest.","Unrack the bar and hold it over your lower chest with your arms extended.","Lower the bar under control toward your lower chest.","Press the bar back up to full arm extension.","Repeat for the desired number of reps."],"met":6.0},{"id":"ez-bar-curl","n":"Curl à la barre EZ","en":"EZ-Bar Curl","c":"strength","eq":"ez_bar","pm":["biceps_brachii"],"sm":["brachialis","brachioradialis"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre EZ. Travaille surtout : Biceps. En soutien : Brachial, Brachio-radial.","ins":["Stand holding an EZ-bar with an underhand grip on the angled portions.","Curl the bar up toward your shoulders, keeping your elbows pinned.","Squeeze at the top, then lower under control.","Repeat."],"met":5.0},{"id":"ez-bar-front-raise","n":"Élévation frontale à la barre EZ","en":"EZ-Bar Front Raise","c":"strength","eq":"ez_bar","pm":["anterior_deltoid"],"sm":["serratus_anterior"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — barre EZ. Travaille surtout : Deltoïde antérieur. En soutien : Dentelé antérieur.","ins":["Stand holding an EZ-bar with an overhand grip on the inner bends, arms hanging in front of the thighs.","Keep the elbows slightly bent and fixed throughout.","Raise the bar in a smooth arc up to shoulder height.","Pause briefly at the top, then lower under control.","Repeat for the recommended number of repetitions."],"met":5.0},{"id":"ez-bar-lying-tricep-extension","n":"Barre au front à la barre EZ","en":"EZ-Bar Lying Triceps Extension","c":"strength","eq":"ez_bar","pm":["triceps_brachii"],"sm":[],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — barre EZ. Travaille surtout : Triceps.","ins":["Lie on a flat bench holding an EZ bar over your chest with a narrow grip.","Lower the bar toward your forehead by bending at the elbows.","Extend your arms back to the start.","Repeat."],"met":5.0},{"id":"ez-bar-overhead-extension","n":"Extension triceps au-dessus de la tête à la barre EZ","en":"EZ-Bar Overhead Tricep Extension","c":"strength","eq":"ez_bar","pm":["triceps_brachii"],"sm":[],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — barre EZ. Travaille surtout : Triceps.","ins":["Stand or sit holding an EZ-bar overhead with an overhand grip on the inner bends.","Arms fully extended, bar above the head.","Bend only the elbows to lower the bar behind the head in an arc.","Keep the upper arms vertical and close to the head; only the forearms move.","Extend the elbows to return the bar overhead.","Repeat for the recommended number of repetitions."],"met":5.0},{"id":"ez-bar-pullover","n":"Pull-over à la barre EZ","en":"EZ Bar Pullover","c":"strength","eq":"ez_bar","pm":["latissimus_dorsi","pectoralis_major"],"sm":["serratus_anterior","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre EZ. Travaille surtout : Grand dorsal, Pectoraux. En soutien : Dentelé antérieur, Triceps.","ins":["Lie supine on a flat bench with your head slightly off the end, holding an EZ bar with a pronated grip.","Extend the bar straight above your chest, keeping a slight bend in your elbows.","Slowly lower the bar in an arc behind your head, feeling a stretch in your lats and chest.","Pull the bar back to the starting position using your lats and pectorals.","Maintain control throughout the movement, avoiding momentum."],"met":6.0},{"id":"ez-bar-reverse-curl","n":"Curl inversé à la barre EZ","en":"EZ-Bar Reverse Curl","c":"strength","eq":"ez_bar","pm":["brachialis","forearm_extensors"],"sm":["biceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre EZ. Travaille surtout : Brachial, Extenseurs de l'avant-bras. En soutien : Biceps.","ins":["Hold an EZ-bar with an overhand grip.","Curl the bar up toward your shoulders.","Lower under control.","Repeat."],"met":5.0},{"id":"ez-bar-reverse-grip-row","n":"Rowing prise inversée à la barre EZ","en":"EZ Bar Reverse Grip Row","c":"strength","eq":"ez_bar","pm":["biceps_brachii","latissimus_dorsi"],"sm":["posterior_deltoid","rhomboids","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre EZ. Travaille surtout : Biceps, Grand dorsal. En soutien : Deltoïde postérieur, Rhomboïdes, Trapèzes.","ins":["Stand with feet shoulder-width apart, holding an EZ bar with an underhand, shoulder-width grip.","Hinge at your hips, keeping a slight bend in your knees and your back straight, until your torso is nearly parallel to the floor.","Let the bar hang directly below your shoulders with arms fully extended.","Pull the bar towards your lower abdomen, squeezing your shoulder blades together and driving your elbows up.","Control the eccentric phase, slowly lowering the bar back to the starting position with full arm extension."],"met":6.0},{"id":"ez-bar-romanian-deadlift","n":"Soulevé de terre roumain à la barre EZ","en":"EZ-Bar Romanian Deadlift","c":"strength","eq":"ez_bar","pm":["gluteus_maximus","hamstrings"],"sm":["erector_spinae","forearm_flexors","trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre EZ. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis), Fléchisseurs de l'avant-bras, Trapèzes.","ins":["Stand holding an EZ-bar at mid-thigh with an overhand grip on the inner bends.","Feet hip-width, soft bend in the knees, chest up, lats engaged.","Push the hips back while letting the bar slide down the front of the legs.","Go until you feel a deep hamstring stretch without rounding the lower back.","Drive the hips forward to return to standing, keeping the bar close to the body.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"ez-bar-shrug","n":"Haussements d'épaules à la barre EZ","en":"EZ-Bar Shrug","c":"strength","eq":"ez_bar","pm":["trapezius"],"sm":["rhomboids"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre EZ. Travaille surtout : Trapèzes. En soutien : Rhomboïdes.","ins":["Stand holding an EZ-bar in front of you.","Shrug your shoulders straight up.","Hold at the top, then lower.","Repeat."],"met":5.0},{"id":"ez-bar-spider-curl","n":"Curl araignée à la barre EZ","en":"EZ Bar Spider Curl","c":"strength","eq":"ez_bar","pm":["biceps_brachii"],"sm":["brachialis","brachioradialis"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre EZ. Travaille surtout : Biceps. En soutien : Brachial, Brachio-radial.","ins":["Lie chest down on an incline bench holding an EZ bar with underhand grip.","Let your arms hang straight down from your shoulders.","Curl the bar up toward your shoulders.","Squeeze your biceps at the top of the movement.","Lower the bar back down with control.","Repeat for the desired number of reps."],"met":5.0},{"id":"ez-bar-upright-row","n":"Rowing menton à la barre EZ","en":"EZ-Bar Upright Row","c":"strength","eq":"ez_bar","pm":["lateral_deltoid","trapezius"],"sm":["anterior_deltoid","biceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre EZ. Travaille surtout : Deltoïde latéral, Trapèzes. En soutien : Deltoïde antérieur, Biceps.","ins":["Stand holding an EZ-bar with a shoulder-width grip on the angled portions.","Pull the bar straight up along your body toward your chin.","Lead with your elbows, keeping them above your hands.","Lower with control.","Repeat."],"met":6.0},{"id":"ez-bar-wrist-curl","n":"Curl poignets à la barre EZ","en":"EZ-Bar Wrist Curl","c":"strength","eq":"ez_bar","pm":["forearm_flexors"],"sm":[],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre EZ. Travaille surtout : Fléchisseurs de l'avant-bras.","ins":["Sit on a bench with forearms resting on the thighs, palms up.","Grip an EZ-bar on the inner bends with hands shoulder-width.","Let the bar roll down to the fingertips.","Curl the bar up by flexing the wrists.","Lower under control."],"met":5.0},{"id":"face-pull","n":"Face pull à la poulie","en":"Cable Face Pull","c":"strength","eq":"cable","pm":["posterior_deltoid","rhomboids"],"sm":["trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — poulie. Travaille surtout : Deltoïde postérieur, Rhomboïdes. En soutien : Trapèzes.","ins":["Attach a rope to a high cable pulley.","Pull the rope toward your face, separating the ends.","Squeeze your rear deltoids and external rotators.","Return to the starting position with control.","Repeat."],"met":6.0},{"id":"fire-hydrant","n":"Fire hydrant","en":"Fire Hydrant","c":"strength","eq":"","pm":["abductors","gluteus_medius"],"sm":["gluteus_maximus","transverse_abdominis"],"d":"beginner","bw":true,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée, au poids du corps. Travaille surtout : Abducteurs, Moyen fessier. En soutien : Grand fessier, Transverse. Se fait d'un côté puis de l'autre.","ins":["Set up on hands and knees with the hands under the shoulders, the knees under the hips and the back flat.","Brace the trunk so the hips stay level and square to the floor.","Keeping the knee bent at about 90 degrees, lift one knee out to the side until the thigh is roughly parallel to the floor.","Pause briefly at the top without rotating the pelvis or leaning away from the working side.","Lower the knee back to the starting position under control.","Complete the repetitions on one side, then switch legs."],"met":3.5},{"id":"fish-pose","n":"Posture du poisson","en":"Fish Pose","c":"stretching","eq":"","pm":["erector_spinae","pectoralis_major"],"sm":["anterior_deltoid","hip_flexors"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Pectoraux. En soutien : Deltoïde antérieur, Fléchisseurs de hanche.","ins":["Lie on your back with the legs straight and the arms alongside the body, palms down under the hips.","Press the forearms into the floor and lift the chest towards the ceiling.","Let the crown of the head rest lightly on the floor without putting weight through the neck.","Hold the position for the prescribed time, breathing into the upper chest.","Lift the head, then lower the back down."],"met":5.0},{"id":"flexed-arm-hang","n":"Suspension bras fléchis","en":"Flexed Arm Hang","c":"strength","eq":"pull_up_bar","pm":["biceps_brachii","latissimus_dorsi"],"sm":["brachialis","forearm_flexors","rhomboids","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — barre de traction. Travaille surtout : Biceps, Grand dorsal. En soutien : Brachial, Fléchisseurs de l'avant-bras, Rhomboïdes, Trapèzes.","ins":["Grip a pull-up bar with the palms facing away, a little wider than shoulder-width, or facing you for an easier version.","Pull yourself up, or step up on a box, until the chin is above the bar.","Keep the elbows bent and pointing down, with the shoulders pulled away from the ears.","Hold the position without swinging, keeping the legs together and the trunk tight.","Lower slowly to a full hang when the chin begins to drop."],"met":6.0},{"id":"floor-ez-bar-press","n":"Développé au sol à la barre EZ","en":"Floor EZ-Bar Press","c":"strength","eq":"ez_bar","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre EZ. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Lie on the floor holding an EZ-bar over your chest.","Lower the bar until your elbows touch the floor.","Press back up to full extension.","Repeat."],"met":6.0},{"id":"floor-kettlebell-pullover","n":"Pull-over au sol au KB","en":"Floor Kettlebell Pullover","c":"strength","eq":"kettlebell","pm":["latissimus_dorsi","pectoralis_major"],"sm":["serratus_anterior","triceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — kettlebell. Travaille surtout : Grand dorsal, Pectoraux. En soutien : Dentelé antérieur, Triceps.","ins":["Lie face-up on the floor with knees bent and feet flat.","Hold a kettlebell by the handle with both hands above your chest, arms almost straight (slight elbow bend).","Keeping the elbow angle fixed, lower the bell overhead in an arc until the upper arms touch the floor.","Pull the bell back above the chest along the same arc.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"floor-press","n":"Développé au sol","en":"Floor Press","c":"strength","eq":"barbell","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Lie on the floor and position yourself under a barbell in a rack.","Lower the barbell to your chest until elbows touch the floor.","Press back up to lockout.","Repeat."],"met":6.0},{"id":"flutter-kicks","n":"Battements de jambes","en":"Flutter Kicks","c":"strength","eq":"","pm":["hip_flexors","rectus_abdominis"],"sm":["transverse_abdominis"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Transverse.","ins":["Lie flat on your back with your legs extended.","Place your hands under your glutes for support.","Lift both legs a few inches off the floor.","Alternate kicking your legs up and down in a small range.","Keep your core braced and lower back pressed down.","Continue for the desired duration or reps."],"met":5.0},{"id":"front-lever","n":"Front lever","en":"Front Lever","c":"strength","eq":"pull_up_bar","pm":["latissimus_dorsi","pectoralis_major"],"sm":["anterior_deltoid","biceps_brachii","erector_spinae","rectus_abdominis"],"d":"advanced","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — barre de traction. Travaille surtout : Grand dorsal, Pectoraux. En soutien : Deltoïde antérieur, Biceps, Lombaires (érecteurs du rachis), Grand droit (abdominaux).","ins":["Grip the bar with an overhand grip and hang.","Tuck your knees to your chest and drive your hips upward, rotating forward until your chest faces up.","Extend your body horizontally with arms straight and chest facing the ceiling.","Keep your body rigid and parallel to the floor.","Hold for the desired duration, then tuck and lower under control."],"met":6.0},{"id":"front-squat","n":"Squat avant","en":"Front Squat","c":"strength","eq":"barbell","pm":["gluteus_maximus","quadriceps"],"sm":["erector_spinae","hamstrings"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Ischio-jambiers.","ins":["Clean or rack the bar to your front deltoids with elbows high.","Squat down keeping torso upright until thighs are parallel.","Drive back up.","Repeat."],"met":6.0},{"id":"garland-pose","n":"Posture de la guirlande","en":"Garland Pose","c":"stretching","eq":"","pm":["adductors","gluteus_maximus"],"sm":["quadriceps","soleus"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Adducteurs, Grand fessier. En soutien : Quadriceps, Soléaire.","ins":["Stand with the feet a little wider than the hips and the toes turned slightly out.","Squat down as low as the ankles allow, keeping the heels on the floor.","Bring the palms together at the chest and press the elbows against the inner knees.","Hold the position for the prescribed time with the chest lifted and the spine long.","Press through the feet to stand back up."],"met":5.0},{"id":"glute-bridge","n":"Pont fessier","en":"Glute Bridge","c":"strength","eq":"","pm":["gluteus_maximus"],"sm":["hamstrings"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée, au poids du corps. Travaille surtout : Grand fessier. En soutien : Ischio-jambiers.","ins":["Lie on your back with knees bent and feet flat on the floor.","Drive your hips up by squeezing your glutes.","Hold briefly at the top with hips fully extended.","Lower your hips back down with control.","Repeat."],"met":3.5},{"id":"glute-bridge-hold","n":"Pont fessier statique","en":"Glute Bridge Hold","c":"strength","eq":"","pm":["gluteus_maximus"],"sm":["hamstrings"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation d'isolation statique, au poids du corps. Travaille surtout : Grand fessier. En soutien : Ischio-jambiers.","ins":["Lie on your back with the knees bent and the feet flat, about hip-width apart and close enough to brush your fingertips with your heels.","Push through the heels and lift the hips until the body forms a straight line from the knees to the shoulders.","Squeeze the glutes and tuck the ribs down so the lower back does not take over.","Hold the top position for the prescribed time, keeping the weight in the heels.","Lower the hips under control to finish the set."],"met":3.5},{"id":"glute-kickback","n":"Kickback fessier","en":"Glute Kickback","c":"strength","eq":"","pm":["gluteus_maximus"],"sm":["erector_spinae","gluteus_medius","hamstrings"],"d":"beginner","bw":true,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée, au poids du corps. Travaille surtout : Grand fessier. En soutien : Lombaires (érecteurs du rachis), Moyen fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Begin on all fours with hands under shoulders and knees under hips.","Keeping the knee bent at 90 degrees, drive one heel toward the ceiling.","Squeeze the glute at the top of the movement.","Lower the leg back to the starting position with control.","Complete all reps, then switch sides."],"met":3.5},{"id":"glute-kickback-hold","n":"Kickback fessier statique","en":"Glute Kickback Hold","c":"strength","eq":"","pm":["gluteus_maximus"],"sm":["erector_spinae","gluteus_medius","hamstrings"],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Exercice de musculation d'isolation statique, au poids du corps. Travaille surtout : Grand fessier. En soutien : Lombaires (érecteurs du rachis), Moyen fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Start on all fours with the hands under the shoulders and the knees under the hips.","Brace the trunk and keep the pelvis level; do not let the working side rotate upwards.","Extend one leg back and up until the thigh is in line with the torso.","Hold that position for the prescribed time, keeping the neck long and the lower back flat.","Lower the leg under control and repeat on the other side."],"met":3.5},{"id":"goblet-squat","n":"Goblet squat","en":"Goblet Squat","c":"strength","eq":"kettlebell","pm":["gluteus_maximus","quadriceps"],"sm":["hamstrings"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Grand fessier, Quadriceps. En soutien : Ischio-jambiers.","ins":["Hold a kettlebell at chest height with both hands.","Squat down keeping the weight close to your chest.","Drive back up.","Repeat."],"met":6.0},{"id":"good-morning","n":"Good morning","en":"Good Morning","c":"strength","eq":"barbell","pm":["erector_spinae","gluteus_maximus","hamstrings"],"sm":[],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre. Travaille surtout : Lombaires (érecteurs du rachis), Grand fessier, Ischio-jambiers.","ins":["Stand with a barbell across your upper back.","Hinge at the hips, pushing them back while keeping your back flat.","Lower your torso until it's nearly parallel to the floor.","Drive your hips forward to return to standing.","Repeat."],"met":6.0},{"id":"hack-squat","n":"Hack squat","en":"Hack Squat","c":"strength","eq":"hack_squat","pm":["gluteus_maximus","quadriceps"],"sm":["gastrocnemius","hamstrings"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — hack squat. Travaille surtout : Grand fessier, Quadriceps. En soutien : Mollets (gastrocnémiens), Ischio-jambiers.","ins":["Load the hack squat machine and step on, positioning your back and shoulders against the pads.","Place your feet shoulder-width on the platform with toes turned out slightly.","Unlock the safety handles and lower the sled by bending at the knees and hips.","Descend until your thighs are at least parallel to the platform.","Drive through your heels to extend the legs and push the sled back to the start.","Re-engage the safety handles after your final rep."],"met":6.0},{"id":"hack-squat-calf-raise","n":"Mollets au hack squat","en":"Hack Squat Calf Raise","c":"strength","eq":"hack_squat","pm":["gastrocnemius","soleus"],"sm":[],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — hack squat. Travaille surtout : Mollets (gastrocnémiens), Soléaire.","ins":["Load yourself into a hack squat machine with shoulders under the pads.","Place the balls of your feet on the platform with heels hanging off.","Keep your legs straight with a slight knee bend.","Press through the balls of your feet to raise your heels.","Lower your heels back below the platform for a stretch.","Repeat for the desired number of reps."],"met":5.0},{"id":"half-kneeling-hip-flexor-rock","n":"Bascule du fléchisseur de hanche à demi-genou","en":"Half-Kneeling Hip Flexor Rock","c":"stretching","eq":"","pm":["hip_flexors"],"sm":["gluteus_maximus","quadriceps"],"d":"beginner","bw":true,"uni":true,"img":["start","peak"],"desc":"Étirement, au poids du corps. Travaille surtout : Fléchisseurs de hanche. En soutien : Grand fessier, Quadriceps. Se fait d'un côté puis de l'autre.","ins":["Kneel on one knee with the other foot flat on the floor in front of you.","Tuck the tailbone slightly and brace the trunk so the lower back stays neutral.","Rock the hips forward until you feel the front of the back thigh lengthen.","Rock back out of the position under control and repeat rhythmically.","Switch sides and repeat for the same number of repetitions."],"met":5.0},{"id":"half-moon-pose","n":"Posture de la demi-lune","en":"Half Moon Pose","c":"strength","eq":"","pm":["gluteus_medius","obliques"],"sm":["erector_spinae","quadriceps"],"d":"advanced","bw":true,"uni":true,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Moyen fessier, Obliques. En soutien : Lombaires (érecteurs du rachis), Quadriceps. Se fait d'un côté puis de l'autre.","ins":["From a wide standing stance, bend the front knee and place the bottom hand on the floor or a block ahead of the front foot.","Shift the weight forward and lift the back leg until it is parallel to the floor.","Straighten the standing leg and stack the top hip over the bottom one, reaching the top arm to the ceiling.","Hold the balance for the prescribed time with the lifted foot flexed.","Lower the back foot down and repeat on the other side."],"met":5.0},{"id":"hammer-curl","n":"Curl marteau aux haltères","en":"Dumbbell Hammer Curl","c":"strength","eq":"dumbbell","pm":["biceps_brachii","brachialis"],"sm":["forearm_flexors"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Biceps, Brachial. En soutien : Fléchisseurs de l'avant-bras.","ins":["Stand holding dumbbells at your sides with palms facing each other.","Curl the weights up while keeping your palms facing inward.","Squeeze at the top, then lower under control.","Repeat."],"met":5.0},{"id":"handstand-hold","n":"Équilibre sur les mains (statique)","en":"Handstand Hold","c":"strength","eq":"","pm":["anterior_deltoid","triceps_brachii"],"sm":["forearm_flexors","rectus_abdominis","serratus_anterior","trapezius"],"d":"advanced","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Deltoïde antérieur, Triceps. En soutien : Fléchisseurs de l'avant-bras, Grand droit (abdominaux), Dentelé antérieur, Trapèzes.","ins":["Place the hands about shoulder-width apart on the floor and kick up into an inverted position, one leg after the other.","Press tall through the shoulders and keep the arms locked.","Squeeze the glutes and abdominals so the body forms one straight line from the hands to the toes.","Keep the gaze between the hands and hold the position, making small corrections with the fingers.","Come down under control, one leg at a time, or step out of the hold."],"met":5.0},{"id":"handstand-push-ups","n":"Pompes en équilibre sur les mains","en":"Handstand Push Ups","c":"strength","eq":"","pm":["anterior_deltoid","triceps_brachii"],"sm":["lateral_deltoid","rectus_abdominis","trapezius"],"d":"advanced","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Deltoïde antérieur, Triceps. En soutien : Deltoïde latéral, Grand droit (abdominaux), Trapèzes.","ins":["Kick up into a handstand against a wall with hands shoulder-width apart.","Brace your core and keep your body straight.","Lower your head toward the floor by bending your elbows.","Stop just before your head touches the ground.","Press through your hands to return to full handstand.","Repeat for the desired number of reps."],"met":5.0},{"id":"hang-clean","n":"Épaulé depuis la suspension","en":"Hang Clean","c":"olympic","eq":"barbell","pm":["gluteus_maximus","quadriceps","trapezius"],"sm":["anterior_deltoid","erector_spinae","hamstrings"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Mouvement d'haltérophilie — barre. Travaille surtout : Grand fessier, Quadriceps, Trapèzes. En soutien : Deltoïde antérieur, Lombaires (érecteurs du rachis), Ischio-jambiers.","ins":["Stand holding a barbell with a shoulder-width grip at your thighs.","Hinge at the hips to lower the bar just above your knees.","Explosively extend your hips, knees, and ankles.","Shrug your shoulders and pull the bar up.","Catch the bar on your front shoulders in a quarter squat.","Stand tall, then return to the hang position."],"met":8.0},{"id":"hang-power-clean","n":"Épaulé en puissance depuis la suspension","en":"Hang Power Clean","c":"olympic","eq":"barbell","pm":["gluteus_maximus","quadriceps","trapezius"],"sm":["erector_spinae","hamstrings"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Mouvement d'haltérophilie — barre. Travaille surtout : Grand fessier, Quadriceps, Trapèzes. En soutien : Lombaires (érecteurs du rachis), Ischio-jambiers.","ins":["Stand with feet hip-width apart holding a barbell at your thighs.","Hinge at the hips to lower the bar to just above the knees.","Drive through your hips and legs explosively.","Pull the bar up and catch it on your front shoulders in a partial squat.","Stand tall with the bar racked on your shoulders.","Lower the bar back to the hang position."],"met":8.0},{"id":"hang-snatch","n":"Arraché depuis la suspension","en":"Hang Snatch","c":"olympic","eq":"barbell","pm":["gluteus_maximus","quadriceps","trapezius"],"sm":["anterior_deltoid","erector_spinae","hamstrings"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Mouvement d'haltérophilie — barre. Travaille surtout : Grand fessier, Quadriceps, Trapèzes. En soutien : Deltoïde antérieur, Lombaires (érecteurs du rachis), Ischio-jambiers.","ins":["Stand with a wide snatch grip on a barbell held at the thighs and the feet about hip-width apart.","Hinge at the hips to lower the bar to just above the knees, keeping the back flat and the shoulders over the bar.","Explosively extend the hips, knees and ankles, shrugging as the bar rises.","Pull yourself under the bar and catch it overhead with locked arms in a squat.","Stand up fully with the bar overhead and stable.","Lower the bar under control back to the thighs and reset."],"met":8.0},{"id":"hanging-knee-raise","n":"Relevés de genoux suspendu","en":"Hanging Knee Raise","c":"strength","eq":"pull_up_bar","pm":["hip_flexors","rectus_abdominis"],"sm":["forearm_flexors","obliques"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre de traction. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Fléchisseurs de l'avant-bras, Obliques.","ins":["Hang from a pull-up bar with an overhand grip, arms fully extended.","Engage your core and raise your knees toward your chest.","Hold briefly at the top.","Lower your legs slowly back to the starting position.","Repeat for the desired reps."],"met":6.0},{"id":"hanging-l-sit","n":"L-sit suspendu","en":"Hanging L-Sit","c":"strength","eq":"pull_up_bar","pm":["hip_flexors","rectus_abdominis"],"sm":["forearm_flexors","latissimus_dorsi","quadriceps","transverse_abdominis"],"d":"advanced","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — barre de traction. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Fléchisseurs de l'avant-bras, Grand dorsal, Quadriceps, Transverse.","ins":["Hang from a pull-up bar with an overhand grip, arms straight and the shoulders pulled down.","Brace the abdominals and lift the straight legs until they are parallel to the floor.","Keep the knees locked and the toes pointed, with the legs together.","Hold the position without swinging, breathing steadily.","Lower the legs under control to a dead hang."],"met":6.0},{"id":"hanging-leg-raise","n":"Relevés de jambes suspendu","en":"Hanging Leg Raise","c":"strength","eq":"pull_up_bar","pm":["hip_flexors","rectus_abdominis"],"sm":["obliques"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre de traction. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Obliques.","ins":["Hang from a pull-up bar with an overhand grip.","Raise your legs in front of you until they are parallel to the floor.","Hold briefly, then lower with control.","Avoid swinging.","Repeat."],"met":5.0},{"id":"hanging-pike","n":"Pike suspendu","en":"Hanging Pike","c":"strength","eq":"pull_up_bar","pm":["rectus_abdominis"],"sm":["forearm_flexors","hip_flexors","latissimus_dorsi"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre de traction. Travaille surtout : Grand droit (abdominaux). En soutien : Fléchisseurs de l'avant-bras, Fléchisseurs de hanche, Grand dorsal.","ins":["Hang from a pull-up bar with a shoulder-width overhand grip.","Engage the lats and brace the core to create a hollow body.","Keeping the legs perfectly straight, lift them in a smooth arc up to the bar.","Aim to touch the toes to the bar between the hands.","Lower the legs slowly back to the hanging position and repeat."],"met":4.5},{"id":"hanging-tuck-hold","n":"Position groupée suspendue","en":"Hanging Tuck Hold","c":"strength","eq":"pull_up_bar","pm":["hip_flexors","rectus_abdominis"],"sm":["forearm_flexors","latissimus_dorsi","obliques","transverse_abdominis"],"d":"intermediate","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — barre de traction. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Fléchisseurs de l'avant-bras, Grand dorsal, Obliques, Transverse.","ins":["Hang from a pull-up bar with an overhand grip and the arms straight.","Brace the abdominals and pull the knees up toward the chest, rounding the lower back slightly.","Keep the knees together and the thighs at or above hip height.","Hold the tucked position without swinging and breathe steadily.","Lower the legs under control to a full hang."],"met":6.0},{"id":"happy-baby","n":"Posture du bébé heureux","en":"Happy Baby Pose","c":"stretching","eq":"","pm":["adductors","gluteus_maximus"],"sm":["erector_spinae","hamstrings"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Adducteurs, Grand fessier. En soutien : Lombaires (érecteurs du rachis), Ischio-jambiers.","ins":["Lie on your back and draw both knees towards the chest.","Take hold of the outside edges of the feet, or the shins if the feet are out of reach.","Open the knees wider than the ribs and stack the ankles above the knees, soles facing up.","Press the feet gently into the hands and hold for the prescribed time with the lower back on the floor.","Release the feet and lower the legs."],"met":5.0},{"id":"head-to-knee-pose","n":"Posture tête-genou","en":"Head-to-Knee Pose","c":"stretching","eq":"","pm":["erector_spinae","hamstrings"],"sm":["adductors","gluteus_maximus"],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Ischio-jambiers. En soutien : Adducteurs, Grand fessier. Se fait d'un côté puis de l'autre.","ins":["Sit with one leg straight in front of you and the other knee bent out to the side, that foot at the inner thigh.","Turn the chest towards the straight leg so the navel lines up with the thigh.","Hinge from the hips and reach forward along the straight leg with a long spine.","Hold the fold for the prescribed time, breathing into the back of the leg.","Come up with a flat back and repeat on the other side."],"met":5.0},{"id":"heel-elevated-squat","n":"Squat talons surélevés","en":"Heel-Elevated Squat","c":"strength","eq":"barbell","pm":["gluteus_maximus","quadriceps"],"sm":["adductors","erector_spinae","hamstrings"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Grand fessier, Quadriceps. En soutien : Adducteurs, Lombaires (érecteurs du rachis), Ischio-jambiers.","ins":["Place weight plates or a wedge under your heels, feet shoulder-width apart.","Hold a barbell across your upper back or hold dumbbells at your sides.","Brace your core and descend into a squat, keeping your torso upright.","Squat until thighs are parallel to the floor or lower.","Drive through your feet to return to the starting position."],"met":6.0},{"id":"heel-flicks","n":"Talons-fesses","en":"Heel Flicks","c":"cardio","eq":"","pm":["hamstrings"],"sm":["gastrocnemius","gluteus_maximus","hip_flexors"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Exercice cardio, au poids du corps. Travaille surtout : Ischio-jambiers. En soutien : Mollets (gastrocnémiens), Grand fessier, Fléchisseurs de hanche.","ins":["Stand tall with the feet under the hips and the arms bent as for running.","Begin jogging lightly in place.","Flick one heel up towards the same-side glute without driving the knee forward.","Switch feet quickly and continue alternating at an even rhythm.","Stay light on the forefeet and keep the torso upright for the full interval."],"met":8.0},{"id":"heel-to-toe-walk","n":"Marche talon-pointe","en":"Heel-to-Toe Walk","c":"strength","eq":"","pm":["gluteus_medius","soleus"],"sm":["gastrocnemius","quadriceps","transverse_abdominis"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Moyen fessier, Soléaire. En soutien : Mollets (gastrocnémiens), Quadriceps, Transverse.","ins":["Pick a straight line on the floor and stand on it with your arms out to your sides at shoulder height.","Step forward and place your heel directly in front of — and touching — the toes of the standing foot.","Shift your weight onto the front foot under control, pausing for a moment before the next step.","Bring the back foot through and place it heel to toe again, staying on the line rather than stepping around it.","Look ahead at a fixed point instead of down at your feet, and use your arms to correct any wobble.","Walk the desired number of steps, then turn around and walk back."],"met":2.5},{"id":"heel-touches","n":"Touchers de talons","en":"Heel Touches","c":"strength","eq":"","pm":["obliques","rectus_abdominis"],"sm":[],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Obliques, Grand droit (abdominaux).","ins":["Lie on your back with the knees bent and the feet flat on the floor, about hip-width apart.","Lift the head and shoulders slightly off the floor and reach the arms down along your sides.","Crunch to one side and reach that hand toward the heel on the same side.","Return to the center and reach toward the opposite heel.","Keep alternating sides in a smooth rhythm while the lower back stays on the floor.","Continue for the desired number of repetitions."],"met":5.0},{"id":"hero-pose","n":"Posture du héros","en":"Hero Pose","c":"stretching","eq":"","pm":["quadriceps"],"sm":["erector_spinae","hip_flexors"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Quadriceps. En soutien : Lombaires (érecteurs du rachis), Fléchisseurs de hanche.","ins":["Kneel with the knees together and the feet slightly wider than the hips, tops of the feet flat.","Sit the hips back and down between the heels, using a block or cushion if the floor is out of reach.","Stack the ribs over the pelvis and rest the hands on the thighs.","Hold the seat for the prescribed time, keeping the weight even on both sit bones.","Come out by pressing into the hands and straightening one leg at a time."],"met":1.5},{"id":"hex-bar-deadlift","n":"Soulevé de terre à la trap bar","en":"Hex Bar Deadlift","c":"strength","eq":"trap_bar","pm":["erector_spinae","gluteus_maximus","quadriceps"],"sm":["forearm_flexors","hamstrings","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — trap bar. Travaille surtout : Lombaires (érecteurs du rachis), Grand fessier, Quadriceps. En soutien : Fléchisseurs de l'avant-bras, Ischio-jambiers, Trapèzes.","ins":["Stand inside a loaded trap bar with feet shoulder-width apart.","Hinge at the hips and knees to grip the handles.","Brace your core and set your back flat.","Drive through your heels and extend hips and knees to stand up.","Lock out at the top with shoulders pulled back.","Lower the bar back to the floor under control."],"met":6.0},{"id":"high-foot-leg-press","n":"Presse à cuisses pieds hauts","en":"High-Foot Leg Press","c":"strength","eq":"leg_press","pm":["gluteus_maximus"],"sm":["hamstrings","quadriceps"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — presse à cuisses. Travaille surtout : Grand fessier. En soutien : Ischio-jambiers, Quadriceps.","ins":["Set the back pad and seat so your lower back stays supported and your knees can bend without your pelvis rolling under.","Place both feet high on the platform at about shoulder width, with the toes tracking in the same direction as the knees.","Lower the sled by bending the hips and knees until you reach a comfortable depth without the lower back lifting from the pad.","Press through the whole foot and extend the hips and knees without locking the knees aggressively.","Lower the sled under control and repeat for the desired number of repetitions."],"met":6.0},{"id":"high-knees","n":"Montées de genoux","en":"High Knees","c":"cardio","eq":"","pm":["hip_flexors","quadriceps"],"sm":["gastrocnemius","rectus_abdominis"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Exercice cardio, au poids du corps. Travaille surtout : Fléchisseurs de hanche, Quadriceps. En soutien : Mollets (gastrocnémiens), Grand droit (abdominaux).","ins":["Stand tall with feet hip-width apart.","Drive one knee up toward the chest while pumping the opposite arm.","Quickly switch legs, mirroring the arm action.","Continue alternating at a fast pace.","Continue for the prescribed work interval."],"met":8.0},{"id":"high-plank","n":"Planche bras tendus","en":"High Plank","c":"strength","eq":"","pm":["rectus_abdominis","transverse_abdominis"],"sm":["erector_spinae","obliques"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Grand droit (abdominaux), Transverse. En soutien : Lombaires (érecteurs du rachis), Obliques.","ins":["Start in a push-up position with arms fully extended.","Keep your body in a straight line from head to heels.","Brace your core and hold the position.","Breathe steadily throughout."],"met":5.0},{"id":"hip-abduction","n":"Abduction de hanche à la machine","en":"Machine Hip Abduction","c":"strength","eq":"hip_abduction_machine","pm":["gluteus_medius"],"sm":["abductors"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — machine abducteurs. Travaille surtout : Moyen fessier. En soutien : Abducteurs.","ins":["Sit in the hip abduction machine with pads against your outer thighs.","Push your legs apart against the resistance.","Hold briefly at the widest point.","Return to the starting position with control.","Repeat."],"met":5.0},{"id":"hip-adduction","n":"Adduction de hanche","en":"Hip Adduction","c":"strength","eq":"hip_adduction_machine","pm":["adductors"],"sm":[],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — machine adducteurs. Travaille surtout : Adducteurs.","ins":["Sit on the hip adduction machine with your back against the pad.","Place your legs against the pads with the machine set to a comfortable stretch.","Squeeze your legs together until the pads meet in the middle.","Hold the squeeze briefly in the fully closed position.","Let your legs open back out under control to the start.","Repeat for the desired number of reps."],"met":5.0},{"id":"hip-thrust","n":"Hip thrust à la barre","en":"Barbell Hip Thrust","c":"strength","eq":"barbell","pm":["gluteus_maximus","gluteus_medius"],"sm":["hamstrings"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Grand fessier, Moyen fessier. En soutien : Ischio-jambiers.","ins":["Sit on the floor with your upper back against a bench, barbell across your hips.","Drive your hips up until your thighs are parallel to the floor.","Squeeze your glutes at the top.","Lower your hips back down with control.","Repeat."],"met":6.0},{"id":"hollow-body-hold","n":"Hollow body","en":"Hollow Body Hold","c":"strength","eq":"","pm":["rectus_abdominis"],"sm":["hip_flexors","obliques","transverse_abdominis"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Grand droit (abdominaux). En soutien : Fléchisseurs de hanche, Obliques, Transverse.","ins":["Lie on your back with arms extended overhead and legs straight.","Press the lower back firmly into the floor.","Lift the shoulders, head, and legs slightly off the floor.","Hold the position with arms and legs extended, body in a shallow banana shape.","Hold for the prescribed time."],"met":5.0},{"id":"horizontal-leg-press","n":"Presse à cuisses horizontale","en":"Horizontal Leg Press","c":"strength","eq":"leg_press","pm":["gluteus_maximus","quadriceps"],"sm":["hamstrings"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — presse à cuisses. Travaille surtout : Grand fessier, Quadriceps. En soutien : Ischio-jambiers.","ins":["Sit in a horizontal leg press machine and place feet shoulder-width apart.","Unlock the machine and lower the platform toward your chest.","Press the platform back to the start.","Repeat."],"met":6.0},{"id":"human-flag","n":"Drapeau humain","en":"Human Flag","c":"strength","eq":"pull_up_bar","pm":["latissimus_dorsi","obliques"],"sm":["anterior_deltoid","gluteus_maximus","pectoralis_major","rectus_abdominis","triceps_brachii"],"d":"advanced","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — barre de traction. Travaille surtout : Grand dorsal, Obliques. En soutien : Deltoïde antérieur, Grand fessier, Pectoraux, Grand droit (abdominaux), Triceps.","ins":["Stand close to a sturdy vertical pole.","Grip the pole high with the top hand (overhand) and lower with the bottom hand (underhand).","Kick the legs up and out while pressing the bottom arm hard against the pole.","Extend the body horizontally so it forms a straight line parallel to the ground.","Hold the position with the body rigid for the target time.","Lower under control."],"met":6.0},{"id":"incline-bench-ez-bar-press","n":"Développé incliné à la barre EZ","en":"Incline EZ-Bar Bench Press","c":"strength","eq":"ez_bar","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre EZ. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Set bench to 30–45 degrees. Grip the EZ-bar with hands on the angled sections.","Lower the bar to your upper chest.","Press back up to full extension.","Repeat."],"met":6.0},{"id":"incline-bench-press","n":"Développé incliné à la barre","en":"Incline Barbell Bench Press","c":"strength","eq":"barbell","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Lie on an incline bench set to 30-45 degrees.","Grip the bar slightly wider than shoulder-width and unrack.","Lower the bar to your upper chest.","Press the bar back up to full extension.","Repeat."],"met":6.0},{"id":"incline-db-curl","n":"Curl incliné aux haltères","en":"Incline Dumbbell Curl","c":"strength","eq":"dumbbell","pm":["biceps_brachii"],"sm":["brachialis"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Biceps. En soutien : Brachial.","ins":["Sit on an incline bench set to 45 degrees, holding dumbbells at your sides.","Let your arms hang straight down with palms forward.","Curl the dumbbells up toward your shoulders.","Lower with control to full extension.","Repeat."],"met":5.0},{"id":"incline-db-press","n":"Développé incliné aux haltères","en":"Incline Dumbbell Press","c":"strength","eq":"dumbbell","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Set bench to 30-degree incline and sit back with dumbbells at shoulder level.","Press dumbbells up and together until arms are fully extended.","Lower dumbbells back to shoulder level with control.","Repeat."],"met":6.0},{"id":"incline-dumbbell-fly","n":"Écartés inclinés aux haltères","en":"Incline Dumbbell Fly","c":"strength","eq":"dumbbell","pm":["pectoralis_major"],"sm":["anterior_deltoid","biceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Biceps.","ins":["Lie back on an incline bench holding dumbbells above your chest.","Press the dumbbells up with palms facing each other.","Maintain a slight bend in your elbows throughout.","Lower the dumbbells in a wide arc until you feel a chest stretch.","Squeeze your chest to bring the dumbbells back together.","Repeat for the desired number of reps."],"met":5.0},{"id":"incline-hammer-curl","n":"Curl marteau incliné","en":"Incline Hammer Curl","c":"strength","eq":"dumbbell","pm":["biceps_brachii","brachialis"],"sm":["forearm_flexors"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Biceps, Brachial. En soutien : Fléchisseurs de l'avant-bras.","ins":["Sit on an incline bench holding dumbbells with a neutral grip.","Allow arms to hang straight.","Curl the dumbbells up in a hammer motion.","Lower slowly.","Repeat."],"met":5.0},{"id":"incline-push-ups","n":"Pompes inclinées","en":"Incline Push-Up","c":"strength","eq":"","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Place your hands on a bench or elevated surface, shoulder-width apart.","Extend your legs behind you into a plank position.","Lower your chest toward the bench by bending your elbows.","Push back up to the starting position.","Repeat."],"met":5.0},{"id":"incline-treadmill-walk","n":"Marche sur tapis incliné","en":"Incline Treadmill Walk","c":"cardio","eq":"treadmill","pm":["gluteus_maximus","quadriceps"],"sm":["gastrocnemius","hamstrings","soleus"],"d":"beginner","bw":false,"uni":false,"img":["main"],"desc":"Exercice cardio — tapis de course. Travaille surtout : Grand fessier, Quadriceps. En soutien : Mollets (gastrocnémiens), Ischio-jambiers, Soléaire.","ins":["Start the belt at a slow walking speed and step on, then raise the incline to your target gradient.","Walk with a long, deliberate stride, rolling from heel to toe and pushing the belt away behind you with each step.","Stand tall and lean from the ankles with the hill rather than folding forward at the waist.","Keep at least one foot on the belt at all times — walk the hill, do not break into a jog.","Let your arms swing naturally, or rest them lightly on the rails for balance without carrying your weight on them.","Hold the gradient for the desired time, then lower the incline and walk level for a few minutes to finish."],"met":8.0},{"id":"inverted-row","n":"Traction australienne (rowing inversé)","en":"Inverted Row","c":"strength","eq":"barbell","pm":["latissimus_dorsi","rhomboids","trapezius"],"sm":["biceps_brachii","posterior_deltoid","rectus_abdominis"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre. Travaille surtout : Grand dorsal, Rhomboïdes, Trapèzes. En soutien : Biceps, Deltoïde postérieur, Grand droit (abdominaux).","ins":["Set a barbell in a rack at about waist height.","Lie underneath and grip the bar slightly wider than shoulder-width with an overhand grip.","Hang with arms extended, heels on the floor, body straight from head to ankles.","Pull your chest to the bar, squeezing the shoulder blades together.","Lower yourself under control until arms are fully extended.","Repeat."],"met":6.0},{"id":"isometric-neck-side","n":"Flexion latérale du cou isométrique","en":"Isometric Neck Lateral Flexion","c":"strength","eq":"","pm":["trapezius"],"sm":[],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Exercice de musculation d'isolation statique, au poids du corps. Travaille surtout : Trapèzes. Se fait d'un côté puis de l'autre.","ins":["Sit or stand tall. Place the palm of one hand against the side of the head, above the ear.","Press the head into the hand while resisting equally with the hand — the head does not move.","Hold the isometric contraction for 5 to 10 seconds.","Release slowly, then repeat on the same side for the set.","Switch sides and repeat."],"met":3.5},{"id":"jackknife-sit-up","n":"Relevé de buste en canif","en":"Jackknife Sit-Up","c":"strength","eq":"","pm":["rectus_abdominis"],"sm":["hip_flexors","obliques"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Grand droit (abdominaux). En soutien : Fléchisseurs de hanche, Obliques.","ins":["Lie face-up on the floor with arms extended overhead and legs extended straight.","Simultaneously lift the torso and the straight legs off the floor.","Reach the hands up toward the feet as the feet rise — meet above the hips.","Lower the torso and legs back to the floor under control.","Repeat for the recommended number of repetitions."],"met":5.0},{"id":"jefferson-curl","n":"Jefferson curl","en":"Jefferson Curl","c":"strength","eq":"dumbbell","pm":["erector_spinae","hamstrings"],"sm":["gluteus_maximus"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — haltères. Travaille surtout : Lombaires (érecteurs du rachis), Ischio-jambiers. En soutien : Grand fessier.","ins":["Stand tall holding a light dumbbell with straight arms, feet roughly hip-width.","Tuck your chin and begin rounding the spine from the top, one vertebra at a time.","Curl down slowly, letting the weight hang and keeping the legs mostly straight.","Reach the bottom with the back fully rounded and a stretch through the hamstrings.","Reverse it, restacking the spine from the bottom up back to standing."],"met":6.0},{"id":"jump-rope","n":"Corde à sauter","en":"Jump Rope","c":"cardio","eq":"jump_rope","pm":["gastrocnemius","soleus"],"sm":["forearm_flexors","quadriceps"],"d":"beginner","bw":false,"uni":false,"img":["main"],"desc":"Exercice cardio — corde à sauter. Travaille surtout : Mollets (gastrocnémiens), Soléaire. En soutien : Fléchisseurs de l'avant-bras, Quadriceps.","ins":["Hold a jump rope handle in each hand with the rope behind you.","Swing the rope overhead and forward in a smooth arc.","Hop just high enough for the rope to pass under your feet.","Land softly on the balls of the feet, knees slightly bent.","Keep a steady rhythm for the prescribed interval."],"met":11.8},{"id":"jump-squat","n":"Squat sauté","en":"Jump Squat","c":"plyometrics","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["gastrocnemius","hamstrings"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice pliométrique, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Mollets (gastrocnémiens), Ischio-jambiers.","ins":["Stand with feet shoulder-width apart.","Drop into a quarter-squat with the arms back.","Explode upward, swinging the arms up and jumping as high as you can.","Land softly back into a quarter-squat to absorb impact.","Repeat without pausing for the prescribed reps."],"met":7.0},{"id":"jumping-jacks","n":"Jumping jacks","en":"Jumping Jacks","c":"cardio","eq":"","pm":["gastrocnemius","gluteus_medius","lateral_deltoid"],"sm":["abductors","quadriceps","soleus"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice cardio, au poids du corps. Travaille surtout : Mollets (gastrocnémiens), Moyen fessier, Deltoïde latéral. En soutien : Abducteurs, Quadriceps, Soléaire.","ins":["Stand tall with feet together and arms at your sides.","Simultaneously jump your feet out wide and raise your arms overhead.","Ensure your arms meet or nearly meet above your head.","Jump your feet back together while lowering your arms to your sides.","Maintain a continuous, rhythmic motion."],"met":8.0},{"id":"kettlebell-bulgarian-split-squat","n":"Squat bulgare au KB","en":"Kettlebell Bulgarian Split Squat","c":"strength","eq":"kettlebell","pm":["gluteus_maximus","quadriceps"],"sm":["gluteus_medius","hamstrings"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Grand fessier, Quadriceps. En soutien : Moyen fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Stand facing away from a bench, placing one foot on it behind you, laces down. Hold a kettlebell in the opposite hand.","Maintain an upright torso and engage your core.","Lower your body by bending both knees, allowing your front knee to track over your toes.","Descend until your front thigh is parallel to the floor or slightly below, keeping your rear knee close to the ground.","Drive through your front heel to return to the starting position, extending your hips and knees.","Complete all reps per side before switching."],"met":6.0},{"id":"kettlebell-close-grip-floor-press","n":"Développé au sol prise serrée au KB","en":"Kettlebell Close-Grip Floor Press","c":"strength","eq":"kettlebell","pm":["triceps_brachii"],"sm":["anterior_deltoid","pectoralis_major"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Triceps. En soutien : Deltoïde antérieur, Pectoraux.","ins":["Lie on your back on the floor with the knees bent and feet flat.","Hold a single kettlebell by the handle with both hands, close together, the bell resting on the chest with elbows tucked tight to the ribs.","Brace the core and press the kettlebell straight up until the arms are fully extended.","Lower under control until the upper arms touch the floor and pause briefly.","Press back up to lockout.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"kettlebell-concentration-curl","n":"Curl concentré au KB","en":"Kettlebell Concentration Curl","c":"strength","eq":"kettlebell","pm":["biceps_brachii"],"sm":["brachialis"],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — kettlebell. Travaille surtout : Biceps. En soutien : Brachial. Se fait d'un côté puis de l'autre.","ins":["Sit on a bench with your feet wide, holding a kettlebell in one hand.","Brace the back of your upper arm against the inside of your thigh, letting the kettlebell hang.","Curl the kettlebell up toward your shoulder, keeping the elbow pinned against your leg.","Squeeze the bicep at the top, then lower slowly under control.","Finish all reps on one side, then switch arms."],"met":5.0},{"id":"kettlebell-deadlift","n":"Soulevé de terre au KB","en":"Kettlebell Deadlift","c":"strength","eq":"kettlebell","pm":["erector_spinae","gluteus_maximus","hamstrings"],"sm":["forearm_flexors","quadriceps"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — kettlebell. Travaille surtout : Lombaires (érecteurs du rachis), Grand fessier, Ischio-jambiers. En soutien : Fléchisseurs de l'avant-bras, Quadriceps.","ins":["Stand with feet shoulder-width apart and kettlebell between your feet.","Hinge at the hips and bend your knees to grip the handle.","Brace your core and set your back flat.","Drive through your heels to stand up with the kettlebell.","Lock out at the top with shoulders pulled back.","Lower the kettlebell back to the floor with control."],"met":6.0},{"id":"kettlebell-farmers-walk","n":"Marche du fermier aux KB","en":"Kettlebell Farmer's Walk","c":"strength","eq":"kettlebell","pm":["forearm_flexors","trapezius"],"sm":["erector_spinae","gluteus_maximus","quadriceps","rectus_abdominis"],"d":"intermediate","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — kettlebell. Travaille surtout : Fléchisseurs de l'avant-bras, Trapèzes. En soutien : Lombaires (érecteurs du rachis), Grand fessier, Quadriceps, Grand droit (abdominaux).","ins":["Stand between two heavy dumbbells or farmer handles.","Hinge and grip the handles firmly with a neutral grip.","Stand tall with shoulders back and core braced.","Walk forward with short, controlled steps.","Maintain an upright posture throughout the walk.","Set the weights down at the end of the distance."],"met":5.5},{"id":"kettlebell-floor-press","n":"Développé au sol au KB","en":"Kettlebell Floor Press","c":"strength","eq":"kettlebell","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Lie on your back on the floor with knees bent, feet flat.","Hold a kettlebell in each hand at the chest, bells resting on the outer forearms.","Press both kettlebells straight up until the arms are fully extended.","Lower under control until the triceps touch the floor — do not bounce.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"kettlebell-goblet-lunge","n":"Fente goblet au KB","en":"Kettlebell Goblet Lunge","c":"strength","eq":"kettlebell","pm":["gluteus_maximus","quadriceps"],"sm":["gluteus_medius","hamstrings"],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Grand fessier, Quadriceps. En soutien : Moyen fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Stand tall holding a kettlebell by its horns at chest height, elbows tucked, in the goblet position.","Take a controlled step forward with one leg, lowering your hips until both knees are bent at approximately 90 degrees.","Ensure your front knee is stacked over your ankle and your rear knee hovers just above the floor.","Drive through your front heel to return to the starting position, maintaining balance and core tension.","Complete all repetitions on one side before switching, or alternate legs per set."],"met":6.0},{"id":"kettlebell-halo","n":"Halo au KB","en":"Kettlebell Halo","c":"strength","eq":"kettlebell","pm":["lateral_deltoid"],"sm":["posterior_deltoid","trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation dynamique — kettlebell. Travaille surtout : Deltoïde latéral. En soutien : Deltoïde postérieur, Trapèzes.","ins":["Stand tall, core braced, holding a light kettlebell by the horns (upside down) at chest height.","Raise the bell to one side of your head and pass it around the back in a smooth circle.","Bring it back to the starting position in front of your face.","Reverse direction every few reps.","Repeat for the recommended number of repetitions or time."],"met":5.0},{"id":"kettlebell-hammer-curl","n":"Curl marteau au KB","en":"Kettlebell Hammer Curl","c":"strength","eq":"kettlebell","pm":["biceps_brachii","brachialis"],"sm":["brachioradialis"],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — kettlebell. Travaille surtout : Biceps, Brachial. En soutien : Brachio-radial. Se fait d'un côté puis de l'autre.","ins":["Stand holding a kettlebell in one hand, gripping the handle in a neutral position (palm facing the body).","The bell rests on or beside the forearm.","Keep the elbow tucked to the side and curl the bell up toward the shoulder.","Squeeze at the top, then lower under control.","Complete all reps on one side, then switch."],"met":5.0},{"id":"kettlebell-hip-thrust","n":"Hip thrust au KB","en":"Kettlebell Hip Thrust","c":"strength","eq":"kettlebell","pm":["gluteus_maximus"],"sm":["hamstrings","quadriceps"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Grand fessier. En soutien : Ischio-jambiers, Quadriceps.","ins":["Sit on the floor with your upper back against a bench, knees bent, and feet flat.","Place a kettlebell across your hips, holding it securely with both hands.","Drive through your heels, lifting your hips off the floor until your body forms a straight line from shoulders to knees.","Squeeze your glutes forcefully at the top of the movement.","Slowly lower your hips back down to the starting position with control."],"met":6.0},{"id":"kettlebell-kickstand-deadlift","n":"Soulevé de terre décalé au KB","en":"Kettlebell Kickstand Deadlift","c":"strength","eq":"kettlebell","pm":["gluteus_maximus","hamstrings"],"sm":["adductors","erector_spinae"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — kettlebell. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Adducteurs, Lombaires (érecteurs du rachis). Se fait d'un côté puis de l'autre.","ins":["Stand tall and step one foot back so only the toes touch the floor.","Hold a kettlebell in one hand at hip height.","Hinge at the hips, lowering the kettlebell toward mid-shin while keeping the back flat.","Keep most of your weight on the front foot throughout.","Drive through the front heel to return to standing. Switch sides after all reps."],"met":6.0},{"id":"kettlebell-lunge-press","n":"Fente et développé au KB","en":"Kettlebell Lunge Press","c":"strength","eq":"kettlebell","pm":["anterior_deltoid","gluteus_maximus","quadriceps"],"sm":["hamstrings","rectus_abdominis","triceps_brachii"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Deltoïde antérieur, Grand fessier, Quadriceps. En soutien : Ischio-jambiers, Grand droit (abdominaux), Triceps. Se fait d'un côté puis de l'autre.","ins":["Hold a kettlebell at shoulder height with one arm.","Step forward into a lunge with the opposite leg.","As you lunge, press the kettlebell overhead.","Lock out the arm at the top of the press.","Step back to standing while lowering the kettlebell.","Complete reps on one side, then switch."],"met":6.0},{"id":"kettlebell-offset-reverse-lunge-and-press","n":"Fente arrière décalée et développé au KB","en":"Kettlebell Offset Reverse Lunge and Press","c":"strength","eq":"kettlebell","pm":["anterior_deltoid","gluteus_maximus","quadriceps"],"sm":["hamstrings","obliques","triceps_brachii"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Deltoïde antérieur, Grand fessier, Quadriceps. En soutien : Ischio-jambiers, Obliques, Triceps. Se fait d'un côté puis de l'autre.","ins":["Hold a kettlebell at shoulder height on one side.","Step backward into a reverse lunge with the opposite leg.","As you reach the bottom of the lunge, press the kettlebell overhead.","Drive through your front heel to return to standing.","Lower the kettlebell back to shoulder height.","Complete reps on one side, then switch."],"met":6.0},{"id":"kettlebell-overhead-carry","n":"Marche KB au-dessus de la tête","en":"Kettlebell Overhead Carry","c":"strength","eq":"kettlebell","pm":["anterior_deltoid","lateral_deltoid"],"sm":["forearm_extensors","obliques","quadratus_lumborum","serratus_anterior","trapezius","triceps_brachii"],"d":"intermediate","bw":false,"uni":true,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — kettlebell. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Extenseurs de l'avant-bras, Obliques, Carré des lombes, Dentelé antérieur, Trapèzes, Triceps. Se fait d'un côté puis de l'autre.","ins":["Clean and press a kettlebell to lockout, letting the bell settle on the back of your forearm.","Straighten the elbow fully and turn the arm so the bell sits behind and above your wrist rather than off to the side.","Pack the shoulder — push the weight up and let the shoulder blade travel with it instead of jamming it down.","Brace your trunk and walk forward with even strides, keeping the bell stacked over your shoulder and hip.","Keep your wrist straight; letting it bend back is what makes an overhead bell feel unstable.","Carry for the desired distance, lower under control, then repeat on the other side."],"met":5.5},{"id":"kettlebell-overhead-tricep-extension","n":"Extension triceps au-dessus de la tête au KB","en":"Kettlebell Overhead Tricep Extension","c":"strength","eq":"kettlebell","pm":["triceps_brachii"],"sm":[],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — kettlebell. Travaille surtout : Triceps.","ins":["Stand or sit holding a kettlebell by the horns (upside down) with both hands overhead.","Arms fully extended, bell above the head.","Bend only the elbows to lower the bell behind the head in a controlled arc.","Keep the upper arms vertical and close to the head; only the forearms move.","Extend the elbows to return the bell overhead.","Repeat for the recommended number of repetitions."],"met":5.0},{"id":"kettlebell-pistol-squat","n":"Pistol squat au KB","en":"Kettlebell Pistol Squat","c":"strength","eq":"kettlebell","pm":["gluteus_maximus","quadriceps"],"sm":["gluteus_medius","hamstrings","rectus_abdominis"],"d":"advanced","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Grand fessier, Quadriceps. En soutien : Moyen fessier, Ischio-jambiers, Grand droit (abdominaux). Se fait d'un côté puis de l'autre.","ins":["Hold a kettlebell at your chest with both hands.","Stand on one leg with the other leg extended forward.","Lower your hips down into a one-legged squat.","Keep your raised leg off the floor throughout.","Drive through your standing heel to return to standing.","Complete reps on one side, then switch."],"met":6.0},{"id":"kettlebell-pullover","n":"Pull-over au KB","en":"Kettlebell Pullover","c":"strength","eq":"kettlebell","pm":["latissimus_dorsi","pectoralis_major"],"sm":["serratus_anterior","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — kettlebell. Travaille surtout : Grand dorsal, Pectoraux. En soutien : Dentelé antérieur, Triceps.","ins":["Lie on a flat bench holding a kettlebell by the horns with both hands above the chest, arms nearly straight (slight elbow bend).","Keeping the elbow angle fixed, lower the bell overhead in an arc until the upper arms are in line with the torso.","Pull the bell back above the chest along the same arc.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"kettlebell-reverse-lunge","n":"Fente arrière au KB","en":"Kettlebell Reverse Lunge","c":"strength","eq":"kettlebell","pm":["gluteus_maximus","quadriceps"],"sm":["gluteus_medius","hamstrings","obliques"],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Grand fessier, Quadriceps. En soutien : Moyen fessier, Ischio-jambiers, Obliques. Se fait d'un côté puis de l'autre.","ins":["Stand tall with a kettlebell held in one hand, arm extended down, on the same side as the leg that will lunge back.","Step one leg straight back, lowering your hips until both knees are bent at approximately 90 degrees.","Keep your front shin vertical and your chest upright, ensuring your back knee hovers just above the floor.","Drive through your front heel to return to the starting position.","Complete all reps per side before switching to the other side."],"met":6.0},{"id":"kettlebell-reverse-wrist-curl","n":"Curl poignets inversé au KB","en":"Kettlebell Reverse Wrist Curl","c":"strength","eq":"kettlebell","pm":["forearm_extensors"],"sm":[],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — kettlebell. Travaille surtout : Extenseurs de l'avant-bras. Se fait d'un côté puis de l'autre.","ins":["Sit on a bench with the forearm on the thigh, palm down.","Hold a kettlebell by the handle with the wrist hanging off the knee.","Let the wrist drop, lowering the kettlebell.","Lift the back of the hand by extending the wrist.","Lower under control. Complete reps per side."],"met":5.0},{"id":"kettlebell-rotational-lunge","n":"Fente avec rotation au KB","en":"Kettlebell Rotational Lunge","c":"strength","eq":"kettlebell","pm":["gluteus_maximus","quadriceps"],"sm":["gluteus_medius","hamstrings","obliques"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Grand fessier, Quadriceps. En soutien : Moyen fessier, Ischio-jambiers, Obliques. Se fait d'un côté puis de l'autre.","ins":["Hold a kettlebell with both hands at your chest.","Step to one side into a lateral lunge.","Rotate your torso toward the lunging leg.","Bring the kettlebell down toward the bent knee.","Push off the lunging leg to return to center.","Complete reps on one side, then switch."],"met":6.0},{"id":"kettlebell-russian-twist","n":"Rotation russe au KB","en":"Kettlebell Russian Twist","c":"strength","eq":"kettlebell","pm":["obliques"],"sm":["hip_flexors","rectus_abdominis"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Obliques. En soutien : Fléchisseurs de hanche, Grand droit (abdominaux).","ins":["Sit on the floor with your knees bent and feet lifted off the ground.","Hold a kettlebell with both hands in front of your chest.","Lean back slightly to engage your core.","Rotate your torso to one side, bringing the kettlebell next to your hip.","Rotate to the opposite side in a controlled motion.","Repeat for the desired number of reps."],"met":6.0},{"id":"kettlebell-shrug","n":"Haussements d'épaules au KB","en":"Kettlebell Shrug","c":"strength","eq":"kettlebell","pm":["trapezius"],"sm":["forearm_flexors"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — kettlebell. Travaille surtout : Trapèzes. En soutien : Fléchisseurs de l'avant-bras.","ins":["Stand tall with feet hip-width apart, holding a kettlebell in each hand with palms facing your body.","Keep your arms straight and shoulders relaxed.","Elevate your shoulders straight up towards your ears, squeezing your traps at the top.","Hold the contraction briefly.","Slowly lower your shoulders back to the starting position with control.","Repeat for the desired number of repetitions."],"met":5.0},{"id":"kettlebell-single-leg-deadlift","n":"Soulevé de terre une jambe au KB","en":"Kettlebell Single Leg Deadlift","c":"strength","eq":"kettlebell","pm":["gluteus_maximus","hamstrings"],"sm":["erector_spinae","gluteus_medius"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — kettlebell. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis), Moyen fessier. Se fait d'un côté puis de l'autre.","ins":["Hold a kettlebell in one hand and stand on the opposite leg.","Hinge at the hip and lower the kettlebell toward the floor.","Extend your free leg straight back for balance.","Lower until your torso is parallel to the floor.","Drive through your standing heel to return to standing.","Complete reps on one side, then switch."],"met":6.0},{"id":"kettlebell-skull-crusher","n":"Barre au front au KB","en":"Kettlebell Skull Crusher","c":"strength","eq":"kettlebell","pm":["triceps_brachii"],"sm":[],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — kettlebell. Travaille surtout : Triceps.","ins":["Lie on a flat bench holding a kettlebell by the horns with both hands, arms extended above the chest.","Bend only the elbows to lower the bell toward the forehead in a controlled arc.","Keep the upper arms vertical; only the forearms move.","Extend the elbows to press the bell back up.","Repeat for the recommended number of repetitions."],"met":5.0},{"id":"kettlebell-squat","n":"Squat au KB","en":"Kettlebell Squat","c":"strength","eq":"kettlebell","pm":["quadriceps"],"sm":["gluteus_maximus"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Quadriceps. En soutien : Grand fessier.","ins":["Stand with feet shoulder-width apart, holding a kettlebell with both hands in front of you.","Let the kettlebell hang naturally between your legs as you brace your core.","Bend your hips and knees to squat down, keeping the kettlebell close to your body.","Drive through your feet to stand back up to the starting position.","Repeat for the desired number of reps."],"met":6.0},{"id":"kettlebell-sumo-deadlift","n":"Soulevé de terre sumo au KB","en":"Kettlebell Sumo Deadlift","c":"strength","eq":"kettlebell","pm":["gluteus_maximus","quadriceps"],"sm":["adductors","erector_spinae","hamstrings","trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — kettlebell. Travaille surtout : Grand fessier, Quadriceps. En soutien : Adducteurs, Lombaires (érecteurs du rachis), Ischio-jambiers, Trapèzes.","ins":["Stand in a wide stance with toes pointed slightly out, a kettlebell on the floor between the feet.","Hinge down with a flat back, knees tracking over the toes, and grip the handle with both hands.","Drive through the floor and extend the hips and knees together to stand up.","Squeeze the glutes at the top.","Lower the bell under control back to the floor by pushing the hips back.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"kettlebell-sumo-high-pull","n":"Tirage haut sumo au KB","en":"Kettlebell Sumo High Pull","c":"strength","eq":"kettlebell","pm":["adductors","lateral_deltoid","trapezius"],"sm":["gluteus_maximus","hamstrings","posterior_deltoid"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — kettlebell. Travaille surtout : Adducteurs, Deltoïde latéral, Trapèzes. En soutien : Grand fessier, Ischio-jambiers, Deltoïde postérieur.","ins":["Stand with feet wider than shoulder-width, toes slightly turned out, a kettlebell on the floor between the feet.","Hinge down and grip the handle with both hands.","Drive through the feet and extend the hips explosively to pull the kettlebell up.","As it rises, pull the elbows up and out until the handle reaches chin height.","Lower the kettlebell back between the legs under control.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"kettlebell-svend-press","n":"Svend press au KB","en":"Kettlebell Svend Press","c":"strength","eq":"kettlebell","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — kettlebell. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Stand and press two kettlebells together by squeezing the bells at chest height.","Hold the kettlebells horizontal — bells touching, handles outward.","Press the kettlebells forward to full arm extension.","Pull them back to the chest under control.","Repeat for the prescribed reps."],"met":5.0},{"id":"kettlebell-swing","n":"Swing KB","en":"Kettlebell Swing","c":"strength","eq":"kettlebell","pm":["gluteus_maximus","hamstrings"],"sm":["erector_spinae","quadriceps"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique — kettlebell. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis), Quadriceps.","ins":["Stand with feet shoulder-width apart, kettlebell on the floor in front.","Hinge at the hips, grip the kettlebell, and hike it back between your legs.","Explosively drive your hips forward to swing the kettlebell to chest height.","Let the kettlebell swing back between your legs.","Repeat in a fluid motion."],"met":8.0},{"id":"kettlebell-swing-clean","n":"Swing-épaulé au KB","en":"Kettlebell Swing Clean","c":"olympic","eq":"kettlebell","pm":["gluteus_maximus","hamstrings"],"sm":["anterior_deltoid","erector_spinae","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Mouvement d'haltérophilie — kettlebell. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Deltoïde antérieur, Lombaires (érecteurs du rachis), Trapèzes.","ins":["Stand with feet shoulder-width apart, kettlebell between your feet.","Hinge at the hips and grip the handle with one hand.","Swing the kettlebell back between your legs.","Drive your hips forward to pull the kettlebell up to your shoulder.","Catch the kettlebell in the rack position on your shoulder.","Complete reps on one side, then switch."],"met":8.0},{"id":"kettlebell-tibialis-raise","n":"Relevés de pointes de pieds au KB (tibias)","en":"Kettlebell Tibialis Raise","c":"strength","eq":"kettlebell","pm":["tibialis_anterior"],"sm":[],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — kettlebell. Travaille surtout : Tibial antérieur. Se fait d'un côté puis de l'autre.","ins":["Sit at the end of a flat bench with one leg extended and the heel resting on the floor.","Hang a kettlebell by its handle from the front of the foot, over the toes.","Pull the toes up toward the shin as far as is comfortable while the heel stays on the floor.","Hold briefly at the top.","Lower the foot slowly until the toes point toward the floor.","Complete the repetitions, then switch legs."],"met":5.0},{"id":"kettlebell-turkish-get-ups","n":"Turkish get-up au KB","en":"Kettlebell Turkish Get Ups","c":"strength","eq":"kettlebell","pm":["anterior_deltoid","gluteus_maximus","rectus_abdominis"],"sm":["obliques","quadriceps","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Deltoïde antérieur, Grand fessier, Grand droit (abdominaux). En soutien : Obliques, Quadriceps, Triceps.","ins":["Lie on your back holding a kettlebell pressed overhead in one hand.","Bend the knee on the same side and plant the foot flat.","Roll up onto your opposite elbow, then to your hand.","Drive your hips up and sweep your straight leg back into a lunge.","Stand up fully while keeping the kettlebell locked out overhead.","Reverse the sequence to return to the start."],"met":6.0},{"id":"kettlebell-windmills","n":"Moulin à vent au KB","en":"Kettlebell Windmills","c":"strength","eq":"kettlebell","pm":["adductors","anterior_deltoid","obliques"],"sm":["erector_spinae","gluteus_maximus","hamstrings"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — kettlebell. Travaille surtout : Adducteurs, Deltoïde antérieur, Obliques. En soutien : Lombaires (érecteurs du rachis), Grand fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Stand holding a kettlebell locked out overhead in one hand.","Turn your feet about 45 degrees away from the working arm.","Keeping the kettlebell up, hinge at the hips sideways.","Reach your opposite hand down toward your foot.","Drive your hips back to stand up tall.","Complete reps on one side, then switch."],"met":5.0},{"id":"kettlebell-wrist-curl","n":"Curl poignets au KB","en":"Kettlebell Wrist Curl","c":"strength","eq":"kettlebell","pm":["forearm_flexors"],"sm":[],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — kettlebell. Travaille surtout : Fléchisseurs de l'avant-bras. Se fait d'un côté puis de l'autre.","ins":["Sit on a bench with the forearm on the thigh, palm up.","Hold a kettlebell by the handle with the wrist hanging off the knee.","Let the kettlebell rotate down toward the fingertips.","Curl it up by flexing the wrist, controlling the offset weight.","Lower under control. Complete reps per side."],"met":5.0},{"id":"knee-push-ups","n":"Pompes sur les genoux","en":"Knee Push Ups","c":"strength","eq":"","pm":["pectoralis_major"],"sm":["anterior_deltoid","rectus_abdominis","triceps_brachii"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Grand droit (abdominaux), Triceps.","ins":["Start in a push-up position with your knees on the floor.","Place your hands shoulder-width apart on the ground.","Keep your body in a straight line from knees to shoulders.","Lower your chest toward the floor by bending your elbows.","Press through your hands to return to the starting position.","Repeat for the desired number of reps."],"met":5.0},{"id":"knee-to-chest-stretch","n":"Étirement genou-poitrine","en":"Knee-to-Chest Stretch","c":"stretching","eq":"","pm":["gluteus_maximus"],"sm":["erector_spinae"],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Grand fessier. En soutien : Lombaires (érecteurs du rachis). Se fait d'un côté puis de l'autre.","ins":["Lie on your back with both legs straight.","Pull one knee in and hug it to your chest with both hands.","Keep the other leg relaxed on the floor.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"kneeling-cable-row","n":"Rowing à genoux à la poulie","en":"Kneeling Cable Row","c":"strength","eq":"cable","pm":["latissimus_dorsi"],"sm":["biceps_brachii","posterior_deltoid","rhomboids","trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — poulie. Travaille surtout : Grand dorsal. En soutien : Biceps, Deltoïde postérieur, Rhomboïdes, Trapèzes.","ins":["Set a cable pulley to about chest height and attach a rope or double-D handle.","Kneel upright facing the stack far enough back that the weight stack doesn't bottom out.","Grab the handle with both hands and hold it out in front at chest height.","Row the handle to the sternum by driving the elbows back and squeezing the shoulder blades together.","Return under control to the stretched starting position.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"kneeling-hip-flexor-stretch","n":"Étirement du fléchisseur de hanche à genoux","en":"Kneeling Hip Flexor Stretch","c":"stretching","eq":"","pm":["hip_flexors"],"sm":["adductors","quadriceps"],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Fléchisseurs de hanche. En soutien : Adducteurs, Quadriceps. Se fait d'un côté puis de l'autre.","ins":["Kneel on one knee with the other foot flat in front.","Keep your torso upright and core gently braced.","Press your hips forward until the front of the rear hip stretches.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"kneeling-wrist-stretch","n":"Étirement des poignets à genoux","en":"Kneeling Wrist Stretch","c":"stretching","eq":"","pm":["forearm_flexors"],"sm":[],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Fléchisseurs de l'avant-bras.","ins":["Kneel on all fours and place your palms flat on the floor.","Turn your hands so the fingers point back toward your knees.","Keep your palms down and rock your weight back gently.","Hold for 20 to 30 seconds, breathing steadily."],"met":5.0},{"id":"l-sit","n":"L-sit","en":"L Sit","c":"strength","eq":"dip_station","pm":["hip_flexors","rectus_abdominis"],"sm":["latissimus_dorsi","quadriceps","triceps_brachii"],"d":"advanced","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — station de dips. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Grand dorsal, Quadriceps, Triceps.","ins":["Sit on the floor or press up on parallel bars with arms straight.","Lock your elbows and depress your shoulders.","Lift your legs straight out in front of you parallel to the floor.","Form an L shape with your body.","Hold the position for the prescribed duration.","Lower your legs with control to exit."],"met":6.0},{"id":"landmine-press","n":"Développé landmine","en":"Landmine Press","c":"strength","eq":"barbell","pm":["anterior_deltoid","pectoralis_major"],"sm":["serratus_anterior","triceps_brachii"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Deltoïde antérieur, Pectoraux. En soutien : Dentelé antérieur, Triceps. Se fait d'un côté puis de l'autre.","ins":["Load one end of a barbell into a landmine attachment and load the other end with a plate.","Stand in a staggered or square stance and cup the sleeve end of the barbell in both hands at chest height.","Brace your core and press the bar forward and upward along its natural arc.","Fully extend your arms without locking the elbows, then lower the bar back under control.","Keep both hands on the bar throughout and repeat for the desired number of reps."],"met":6.0},{"id":"lat-pulldown","n":"Tirage vertical","en":"Lat Pulldown","c":"strength","eq":"cable","pm":["latissimus_dorsi"],"sm":["biceps_brachii","posterior_deltoid","rhomboids"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — poulie. Travaille surtout : Grand dorsal. En soutien : Biceps, Deltoïde postérieur, Rhomboïdes.","ins":["Sit at the lat pulldown machine with thighs secured under the pads.","Grip the wide bar with an overhand grip.","Pull the bar down to your upper chest, squeezing your lats.","Slowly return the bar to the starting position.","Repeat."],"met":6.0},{"id":"lateral-leg-swing","n":"Balancier de jambe latéral","en":"Lateral Leg Swing","c":"stretching","eq":"","pm":["abductors","adductors"],"sm":["gluteus_medius","hip_flexors"],"d":"beginner","bw":true,"uni":true,"img":["start","peak"],"desc":"Étirement, au poids du corps. Travaille surtout : Abducteurs, Adducteurs. En soutien : Moyen fessier, Fléchisseurs de hanche. Se fait d'un côté puis de l'autre.","ins":["Stand tall and brace the trunk, using a stable support if needed.","Shift the weight onto one leg and lift the other foot slightly from the floor.","Swing the free leg across the front of the body.","Reverse the motion and swing it out to the side through a comfortable range.","Continue smoothly, then change legs."],"met":3.5},{"id":"lateral-raise","n":"Élévation latérale aux haltères","en":"Dumbbell Lateral Raise","c":"strength","eq":"dumbbell","pm":["lateral_deltoid"],"sm":["anterior_deltoid"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Deltoïde latéral. En soutien : Deltoïde antérieur.","ins":["Stand holding dumbbells at your sides.","Raise the dumbbells out to the sides until arms are parallel to the floor.","Lower under control.","Repeat."],"met":5.0},{"id":"leg-curl","n":"Leg curl allongé","en":"Lying Leg Curl","c":"strength","eq":"leg_curl","pm":["hamstrings"],"sm":["gastrocnemius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — machine leg curl. Travaille surtout : Ischio-jambiers. En soutien : Mollets (gastrocnémiens).","ins":["Lie face down on the leg curl machine with ankles under the pad.","Curl your heels toward your glutes.","Squeeze your hamstrings at the top.","Lower with control.","Repeat."],"met":5.0},{"id":"leg-extension","n":"Leg extension","en":"Leg Extension","c":"strength","eq":"leg_extension","pm":["quadriceps"],"sm":[],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — machine leg extension. Travaille surtout : Quadriceps.","ins":["Sit in the leg extension machine with ankles behind the pad.","Extend your legs until they are straight.","Squeeze your quads at the top.","Lower with control.","Repeat."],"met":5.0},{"id":"leg-press","n":"Presse à cuisses","en":"Leg Press","c":"strength","eq":"leg_press","pm":["gluteus_maximus","quadriceps"],"sm":["hamstrings"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — presse à cuisses. Travaille surtout : Grand fessier, Quadriceps. En soutien : Ischio-jambiers.","ins":["Sit in the leg press machine with feet shoulder-width apart on the platform.","Release the safety catches and lower the platform by bending your knees.","Push the platform back up until legs are nearly straight.","Do not lock your knees at the top.","Repeat."],"met":6.0},{"id":"leg-swing-front-to-back","n":"Balancier de jambe avant-arrière","en":"Front-to-Back Leg Swing","c":"stretching","eq":"","pm":["gluteus_maximus","hip_flexors"],"sm":["hamstrings","rectus_abdominis"],"d":"beginner","bw":true,"uni":true,"img":["start","peak"],"desc":"Étirement, au poids du corps. Travaille surtout : Grand fessier, Fléchisseurs de hanche. En soutien : Ischio-jambiers, Grand droit (abdominaux). Se fait d'un côté puis de l'autre.","ins":["Stand tall beside a stable support and shift the weight onto the inside leg.","Brace the trunk and lift the outside foot slightly from the floor.","Swing the free leg forwards through a comfortable range.","Let it travel back behind the body without arching the lower back.","Continue smoothly, then repeat with the other leg."],"met":3.5},{"id":"legs-up-the-wall","n":"Posture jambes contre le mur","en":"Legs-Up-the-Wall Pose","c":"stretching","eq":"","pm":["hamstrings"],"sm":["erector_spinae"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis).","ins":["Sit sideways next to a wall with one hip touching it.","Swing the legs up the wall as you lie back, so the hips end close to the base of the wall.","Let the legs rest against the wall with the feet relaxed and the arms open at the sides.","Stay for the prescribed time, breathing slowly.","Bend the knees and roll to one side to come out."],"met":1.5},{"id":"lizard-stretch","n":"Étirement du lézard","en":"Lizard Stretch","c":"stretching","eq":"","pm":["adductors","hip_flexors"],"sm":["gluteus_maximus","hamstrings"],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Adducteurs, Fléchisseurs de hanche. En soutien : Grand fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Step one foot forward into a deep lunge, foot placed wide.","Lower both forearms toward the floor inside the front foot.","Extend the back leg straight and let the hips sink.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"locust-pose","n":"Posture de la sauterelle","en":"Locust Pose","c":"strength","eq":"","pm":["erector_spinae","gluteus_maximus"],"sm":["hamstrings","posterior_deltoid"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Grand fessier. En soutien : Ischio-jambiers, Deltoïde postérieur.","ins":["Lie face down with the arms alongside the body and the forehead on the mat.","Lengthen the back of the neck and reach the fingertips towards the feet.","Lift the chest, arms and both legs off the floor at the same time.","Hold the lifted position for the prescribed time, keeping the gaze down.","Lower everything down together and rest."],"met":5.0},{"id":"low-lunge","n":"Fente basse","en":"Low Lunge","c":"stretching","eq":"","pm":["hip_flexors","quadriceps"],"sm":["erector_spinae","gluteus_maximus"],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Fléchisseurs de hanche, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Grand fessier. Se fait d'un côté puis de l'autre.","ins":["From kneeling, step one foot forward so the knee stacks over the ankle.","Lower the back knee to the floor and untuck that foot.","Tuck the tailbone slightly and press the hips forward until you feel the front of the back thigh lengthen.","Lift the chest, raise the arms if it feels good, and hold for the prescribed time.","Step back and repeat on the other side."],"met":5.0},{"id":"low-lunge-to-half-split","n":"Fente basse vers demi-grand écart","en":"Low Lunge to Half Split","c":"stretching","eq":"","pm":["hamstrings"],"sm":["gastrocnemius","hip_flexors"],"d":"beginner","bw":true,"uni":true,"img":["start","peak"],"desc":"Étirement, au poids du corps. Travaille surtout : Ischio-jambiers. En soutien : Mollets (gastrocnémiens), Fléchisseurs de hanche. Se fait d'un côté puis de l'autre.","ins":["Start in a low lunge with the back knee on the floor and the front knee over the ankle.","Press the hands into the floor or onto blocks either side of the front foot.","Shift the hips back over the back knee and straighten the front leg, flexing that foot.","Hold the half split briefly, then glide the hips forward into the low lunge again.","Repeat for the desired number of repetitions and change sides."],"met":5.0},{"id":"lunge","n":"Fente","en":"Lunge","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["erector_spinae","gluteus_medius","hamstrings"],"d":"intermediate","bw":true,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Moyen fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Stand tall with your feet hip-width apart.","Step forward with one leg into a long stride.","Lower your back knee toward the floor until both knees form 90-degree angles.","Drive through your front heel to return to standing.","Complete reps on one side, then switch."],"met":5.0},{"id":"lying-leg-raise","n":"Relevés de jambes allongé","en":"Lying Leg Raise","c":"strength","eq":"","pm":["hip_flexors","rectus_abdominis"],"sm":["obliques","transverse_abdominis"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage, au poids du corps. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Obliques, Transverse.","ins":["Lie flat on your back with legs straight and hands under your lower back or gripping a stable surface behind your head.","Keeping your legs together and core braced, raise them to vertical (or as high as flexibility allows).","Pause briefly at the top.","Lower your legs slowly toward the floor without letting them touch.","Repeat for the desired reps."],"met":5.0},{"id":"lying-tricep-extension","n":"Extension triceps allongé","en":"Lying Tricep Extension","c":"strength","eq":"dumbbell","pm":["triceps_brachii"],"sm":["anterior_deltoid"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Triceps. En soutien : Deltoïde antérieur.","ins":["Lie flat on a bench with a barbell or dumbbells held overhead.","Keep your upper arms vertical and elbows pointed forward.","Lower the weight toward your forehead by bending your elbows.","Extend your arms back to the starting position.","Squeeze your triceps at the top.","Repeat for the desired number of reps."],"met":5.0},{"id":"machine-back-extension","n":"Extension lombaire à la machine","en":"Machine Back Extension","c":"strength","eq":"back_extension_machine","pm":["erector_spinae"],"sm":["gluteus_maximus","hamstrings"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — banc à lombaires. Travaille surtout : Lombaires (érecteurs du rachis). En soutien : Grand fessier, Ischio-jambiers.","ins":["Sit in the back extension machine with your feet flat on the foot platform and the roller pad set behind your upper back, just below the shoulder blades.","Grip the handles at your sides and let your torso come forward into a slight flexion — this is the starting position.","Push back against the pad by extending your spine until your torso is leaning back and your lower back is fully contracted.","Pause briefly at full extension, then return to the starting position under control, resisting the weight stack on the way back.","Repeat for the desired number of reps."],"met":5.0},{"id":"machine-bicep-curl","n":"Curl biceps à la machine","en":"Machine Bicep Curl","c":"strength","eq":"bicep_curl_machine","pm":["biceps_brachii"],"sm":["brachialis"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — machine à biceps. Travaille surtout : Biceps. En soutien : Brachial.","ins":["Sit in the machine and adjust the pad to your arm length.","Grip the handles with an underhand grip.","Curl the handles toward your shoulders.","Lower with control.","Repeat."],"met":5.0},{"id":"machine-calf-raise","n":"Mollets à la machine","en":"Machine Calf Raise","c":"strength","eq":"standing_calf_raise_machine","pm":["gastrocnemius","soleus"],"sm":[],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — machine mollets debout. Travaille surtout : Mollets (gastrocnémiens), Soléaire.","ins":["Stand in the calf raise machine with the balls of your feet on the platform.","Position the shoulder pads firmly.","Lower your heels below the platform for a full stretch.","Push through the balls of your feet to rise onto your toes.","Squeeze your calves at the top.","Lower with control and repeat."],"met":5.0},{"id":"machine-chest-fly","n":"Écartés pectoraux à la machine","en":"Machine Chest Fly","c":"strength","eq":"chest_fly_machine","pm":["pectoralis_major"],"sm":["anterior_deltoid","serratus_anterior"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — machine à écartés. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Dentelé antérieur.","ins":["Sit in the chest fly machine and adjust the seat so the handles align with your chest.","Grip the handles with a slight bend in your elbows.","Bring the handles together in front of your chest in a smooth arc.","Squeeze your pectorals at the point of peak contraction.","Return under control to the starting position without slamming the weight.","Repeat for the desired number of reps."],"met":5.0},{"id":"machine-preacher-curl","n":"Curl pupitre à la machine","en":"Machine Preacher Curl","c":"strength","eq":"preacher_curl_machine","pm":["biceps_brachii"],"sm":["brachialis"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — machine curl pupitre. Travaille surtout : Biceps. En soutien : Brachial.","ins":["Sit at a preacher curl machine and adjust the seat so your armpits sit at the top of the pad.","Place the upper arms flat on the pad and grip the handles.","Start with the arms extended — but not locked — at the bottom.","Curl the handles up by flexing the elbows; squeeze hard at the top.","Lower slowly back to the starting position and repeat."],"met":5.0},{"id":"machine-seated-crunch","n":"Crunch assis à la machine","en":"Machine Seated Crunch","c":"strength","eq":"ab_crunch_machine","pm":["rectus_abdominis"],"sm":["obliques","transverse_abdominis"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — machine à abdos. Travaille surtout : Grand droit (abdominaux). En soutien : Obliques, Transverse.","ins":["Sit in the abdominal crunch machine and grip the handles.","Position the chest pad against your upper body.","Contract your abs to crunch your torso forward and down.","Squeeze at the bottom of the movement.","Return to the starting position with control.","Repeat for the desired number of reps."],"met":5.0},{"id":"machine-shoulder-press","n":"Développé épaules à la machine","en":"Machine Shoulder Press","c":"strength","eq":"shoulder_press_machine","pm":["anterior_deltoid","lateral_deltoid"],"sm":["trapezius","triceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — machine développé épaules. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Trapèzes, Triceps.","ins":["Sit in the machine with your back against the pad.","Grip the handles at shoulder level.","Press the handles overhead until arms are fully extended.","Lower with control to the starting position.","Repeat."],"met":6.0},{"id":"machine-triceps-extension","n":"Extension triceps à la machine","en":"Machine Triceps Extension","c":"strength","eq":"tricep_extension_machine","pm":["triceps_brachii"],"sm":[],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — machine à triceps. Travaille surtout : Triceps.","ins":["Sit in the tricep extension machine with your back against the seat pad and your upper arms resting flat on the arm pad in front of your chest.","Take a handle in each hand with your elbows bent and your hands up near shoulder height.","Keeping your upper arms pressed into the pad, extend your elbows to drive the handles down and away until your arms are straight.","Squeeze your triceps at full extension, then bend your elbows to return to the start under control.","Repeat for the desired number of reps."],"met":5.0},{"id":"medicine-ball-slam","n":"Slam au medicine ball","en":"Medicine Ball Slam","c":"strength","eq":"slam_ball","pm":["rectus_abdominis"],"sm":["gluteus_maximus","latissimus_dorsi","obliques"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique — medicine ball. Travaille surtout : Grand droit (abdominaux). En soutien : Grand fessier, Grand dorsal, Obliques.","ins":["Stand with feet shoulder-width apart, holding a slam ball in front of your hips.","Lift the ball overhead by extending the hips and reaching tall.","Forcefully slam the ball into the floor between your feet, crunching through the core.","Catch the ball on the bounce or pick it up from the floor.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"mountain-climbers","n":"Mountain climbers","en":"Mountain Climbers","c":"cardio","eq":"","pm":["hip_flexors","rectus_abdominis"],"sm":["obliques","quadriceps"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice cardio, au poids du corps. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Obliques, Quadriceps.","ins":["Start in a high plank position.","Drive one knee toward your chest.","Quickly switch legs, driving the other knee forward.","Continue alternating at a brisk pace.","Repeat."],"met":8.0},{"id":"mountain-pose","n":"Posture de la montagne","en":"Mountain Pose","c":"stretching","eq":"","pm":["erector_spinae"],"sm":["gastrocnemius","quadriceps"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis). En soutien : Mollets (gastrocnémiens), Quadriceps.","ins":["Stand with the feet hip-width apart and spread the weight evenly across both feet.","Engage the thighs lightly and let the tailbone drop so the pelvis is neutral.","Stack the ribs over the pelvis and the head over the ribs, arms relaxed by the sides.","Hold the posture for the prescribed time, breathing evenly.","Notice where the weight sits and rebalance it towards the middle of each foot."],"met":2.0},{"id":"muscle-snatch","n":"Arraché musculaire (muscle snatch)","en":"Muscle Snatch","c":"olympic","eq":"barbell","pm":["lateral_deltoid","trapezius"],"sm":["erector_spinae","gluteus_maximus","hamstrings"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Mouvement d'haltérophilie — barre. Travaille surtout : Deltoïde latéral, Trapèzes. En soutien : Lombaires (érecteurs du rachis), Grand fessier, Ischio-jambiers.","ins":["Stand with feet hip-width apart and grip the bar wide with a hook grip.","Pull the bar explosively from the floor, keeping it close to your body.","Shrug hard and pull the bar overhead without dipping under.","Lock out the bar overhead with straight arms.","Lower the bar under control to the starting position.","Repeat for the desired number of reps."],"met":8.0},{"id":"muscle-ups","n":"Muscle-ups","en":"Muscle Ups","c":"strength","eq":"pull_up_bar","pm":["latissimus_dorsi","triceps_brachii"],"sm":["anterior_deltoid","biceps_brachii","pectoralis_major"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre de traction. Travaille surtout : Grand dorsal, Triceps. En soutien : Deltoïde antérieur, Biceps, Pectoraux.","ins":["Hang from a pull-up bar with a false grip.","Pull yourself up explosively toward the bar.","As your chest reaches the bar, rotate your elbows over and transition into a dip.","Press your body up until your arms are fully extended above the bar.","Lower back down with control through the same path.","Repeat for the desired number of reps."],"met":6.0},{"id":"neck-side-stretch","n":"Étirement latéral du cou","en":"Neck Side Stretch","c":"stretching","eq":"","pm":["trapezius"],"sm":[],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Trapèzes. Se fait d'un côté puis de l'autre.","ins":["Sit or stand tall with your shoulders relaxed.","Tilt your head so one ear drops toward that shoulder.","Rest that hand lightly over your head for gentle weight.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"negative-pull-ups","n":"Tractions négatives","en":"Negative Pull Ups","c":"strength","eq":"pull_up_bar","pm":["latissimus_dorsi"],"sm":["biceps_brachii","forearm_flexors","posterior_deltoid","rhomboids"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre de traction. Travaille surtout : Grand dorsal. En soutien : Biceps, Fléchisseurs de l'avant-bras, Deltoïde postérieur, Rhomboïdes.","ins":["Use a box or jump to position yourself at the top of a pull-up.","Grip the bar with hands shoulder-width apart.","Hold your chin above the bar briefly.","Lower yourself slowly over 3-5 seconds with control.","Fully extend your arms at the bottom.","Reset and repeat for the desired number of reps."],"met":6.0},{"id":"neutral-grip-pull-ups","n":"Tractions prise neutre","en":"Neutral Grip Pull Ups","c":"strength","eq":"pull_up_bar","pm":["latissimus_dorsi"],"sm":["biceps_brachii","brachialis","forearm_flexors","rhomboids"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre de traction. Travaille surtout : Grand dorsal. En soutien : Biceps, Brachial, Fléchisseurs de l'avant-bras, Rhomboïdes.","ins":["Grip parallel bars with palms facing each other.","Hang with your arms fully extended.","Pull yourself up until your chin clears the bar.","Squeeze your lats at the top of the movement.","Lower yourself with control to the starting position.","Repeat for the desired number of reps."],"met":6.0},{"id":"nordic-hamstring-curl","n":"Nordic hamstring curl","en":"Nordic Hamstring Curl","c":"strength","eq":"glute_ham_developer","pm":["hamstrings"],"sm":["gastrocnemius","gluteus_maximus"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — banc GHD. Travaille surtout : Ischio-jambiers. En soutien : Mollets (gastrocnémiens), Grand fessier.","ins":["Kneel on a pad with your ankles anchored under a fixed support.","Keep your torso upright and your hips extended.","Slowly lower your body forward by resisting with your hamstrings.","Catch yourself with your hands just before hitting the floor.","Push back up and pull yourself to the starting position.","Repeat for the desired number of reps."],"met":5.0},{"id":"ohp","n":"Développé militaire à la barre","en":"Barbell Overhead Press","c":"strength","eq":"barbell","pm":["anterior_deltoid","lateral_deltoid"],"sm":["trapezius","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Trapèzes, Triceps.","ins":["Stand with feet shoulder-width apart, bar at collarbone level.","Brace your core and press the bar overhead.","Lock out at the top with the bar over your mid-foot.","Lower the bar back to collarbone height.","Repeat."],"met":6.0},{"id":"one-arm-dumbbell-preacher-curl","n":"Curl pupitre un bras à l'haltère","en":"One Arm Dumbbell Preacher Curl","c":"strength","eq":"dumbbell","pm":["biceps_brachii"],"sm":["brachialis","brachioradialis"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Biceps. En soutien : Brachial, Brachio-radial. Se fait d'un côté puis de l'autre.","ins":["Sit at a preacher bench and rest the back of one upper arm flat on the pad.","Hold a dumbbell in that hand with the palm facing up and the arm almost fully extended.","Curl the dumbbell toward the shoulder without lifting the elbow off the pad.","Squeeze the biceps at the top of the movement.","Lower the dumbbell slowly until the arm is almost straight.","Complete the repetitions, then switch arms."],"met":5.0},{"id":"one-arm-dumbbell-push-press","n":"Push press un bras à l'haltère","en":"One-Arm Dumbbell Push Press","c":"strength","eq":"dumbbell","pm":["anterior_deltoid"],"sm":["gluteus_maximus","lateral_deltoid","obliques","quadriceps","triceps_brachii"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Deltoïde antérieur. En soutien : Grand fessier, Deltoïde latéral, Obliques, Quadriceps, Triceps. Se fait d'un côté puis de l'autre.","ins":["Stand holding a dumbbell at one shoulder, palm facing inward (neutral).","Feet shoulder-width, core braced, free arm out to the side for balance.","Dip by bending the knees slightly, keeping the torso vertical.","Explosively extend the legs and press the dumbbell overhead in one motion.","Lock out overhead, then lower back to the shoulder under control.","Complete all reps on one side, then switch."],"met":6.0},{"id":"one-arm-dumbbell-shoulder-press","n":"Développé épaules un bras à l'haltère","en":"One Arm Dumbbell Shoulder Press","c":"strength","eq":"dumbbell","pm":["anterior_deltoid","triceps_brachii"],"sm":["lateral_deltoid","obliques","serratus_anterior","trapezius"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Deltoïde antérieur, Triceps. En soutien : Deltoïde latéral, Obliques, Dentelé antérieur, Trapèzes. Se fait d'un côté puis de l'autre.","ins":["Stand with the feet hip-width apart and hold a dumbbell at one shoulder with the palm facing forward.","Brace the abdominals and keep the free arm relaxed at your side.","Press the dumbbell straight overhead until the arm is fully extended.","Pause briefly at the top with the upper arm next to the ear.","Lower the dumbbell back to the shoulder under control.","Complete the repetitions on one arm, then switch sides."],"met":6.0},{"id":"one-arm-dumbbell-swing","n":"Swing un bras à l'haltère","en":"One-Arm Dumbbell Swing","c":"strength","eq":"dumbbell","pm":["gluteus_maximus","hamstrings"],"sm":["erector_spinae","forearm_flexors","lateral_deltoid"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique — haltères. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis), Fléchisseurs de l'avant-bras, Deltoïde latéral. Se fait d'un côté puis de l'autre.","ins":["Stand with feet shoulder-width apart, a dumbbell on the floor slightly in front of you.","Hinge at your hips, keeping a flat back, and grasp the dumbbell with one hand.","Hike the dumbbell back between your legs, then explosively drive your hips forward.","Swing the dumbbell up to chest height, keeping your arm relaxed and straight.","Allow the dumbbell to swing back down, hinging at the hips as it descends.","Repeat for desired reps per side, maintaining control."],"met":8.0},{"id":"one-arm-kettlebell-bicep-curl","n":"Curl biceps un bras au KB","en":"One Arm Kettlebell Bicep Curl","c":"strength","eq":"kettlebell","pm":["biceps_brachii"],"sm":["brachialis","forearm_flexors"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — kettlebell. Travaille surtout : Biceps. En soutien : Brachial, Fléchisseurs de l'avant-bras. Se fait d'un côté puis de l'autre.","ins":["Stand tall holding a kettlebell in one hand.","Keep your elbow pinned to your side.","Curl the kettlebell toward your shoulder by flexing your bicep.","Squeeze at the top of the movement.","Lower the kettlebell with control.","Complete reps on one side, then switch."],"met":5.0},{"id":"one-arm-kettlebell-bottoms-up-press","n":"Développé KB à l'envers (bottoms-up) un bras","en":"One-Arm Kettlebell Bottoms-Up Press","c":"strength","eq":"kettlebell","pm":["anterior_deltoid"],"sm":["forearm_flexors","lateral_deltoid","serratus_anterior","triceps_brachii"],"d":"advanced","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Deltoïde antérieur. En soutien : Fléchisseurs de l'avant-bras, Deltoïde latéral, Dentelé antérieur, Triceps. Se fait d'un côté puis de l'autre.","ins":["Clean a light kettlebell to the rack position, then tilt it so the bell points up and the handle is at the palm.","Grip the handle hard; wrist absolutely straight and vertical.","Brace the core and press the bell straight up without letting it tip.","Lock out overhead with the bell still perfectly upright.","Lower slowly back to the rack position keeping the bell vertical the entire descent.","Complete all reps on one side, then switch."],"met":6.0},{"id":"one-arm-kettlebell-floor-glute-bridge-press","n":"Pont fessier et développé au sol un bras au KB","en":"One Arm Kettlebell Floor Glute Bridge Press","c":"strength","eq":"kettlebell","pm":["gluteus_maximus","pectoralis_major"],"sm":["anterior_deltoid","hamstrings","triceps_brachii"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — kettlebell. Travaille surtout : Grand fessier, Pectoraux. En soutien : Deltoïde antérieur, Ischio-jambiers, Triceps. Se fait d'un côté puis de l'autre.","ins":["Lie on your back with knees bent and feet flat on the floor.","Hold a kettlebell in one hand at your shoulder.","Drive your hips up into a glute bridge.","Press the kettlebell straight up toward the ceiling.","Lower the kettlebell and your hips with control.","Complete reps on one side, then switch."],"met":6.0},{"id":"one-arm-kettlebell-floor-press","n":"Développé au sol un bras au KB","en":"One Arm Kettlebell Floor Press","c":"strength","eq":"kettlebell","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps. Se fait d'un côté puis de l'autre.","ins":["Lie flat on the floor with knees bent.","Hold a kettlebell at your shoulder with one hand.","Press the kettlebell straight up until your arm is fully extended.","Lower the kettlebell until your upper arm touches the floor.","Keep your core braced throughout.","Complete reps on one side, then switch."],"met":6.0},{"id":"one-arm-kettlebell-front-squat","n":"Squat avant un bras au KB","en":"One Arm Kettlebell Front Squat","c":"strength","eq":"kettlebell","pm":["gluteus_maximus","quadriceps"],"sm":["erector_spinae","hamstrings","obliques"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Ischio-jambiers, Obliques. Se fait d'un côté puis de l'autre.","ins":["Hold a kettlebell in the racked position at one shoulder.","Stand with feet shoulder-width apart.","Squat down by bending your knees and hips.","Keep your chest up and torso upright throughout.","Drive through your heels to stand back up.","Complete reps on one side, then switch."],"met":6.0},{"id":"one-arm-kettlebell-push-press","n":"Push press un bras au KB","en":"One Arm Kettlebell Push Press","c":"strength","eq":"kettlebell","pm":["anterior_deltoid"],"sm":["gluteus_maximus","quadriceps","trapezius","triceps_brachii"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Deltoïde antérieur. En soutien : Grand fessier, Quadriceps, Trapèzes, Triceps. Se fait d'un côté puis de l'autre.","ins":["Hold a kettlebell in the racked position at one shoulder.","Stand with feet shoulder-width apart.","Dip by bending your knees slightly.","Drive explosively through your legs and press the kettlebell overhead.","Lock out your arm at the top.","Lower the kettlebell to your shoulder with control.","Complete reps on one side, then switch."],"met":6.0},{"id":"one-arm-kettlebell-row","n":"Rowing un bras au KB","en":"One Arm Kettlebell Row","c":"strength","eq":"kettlebell","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","posterior_deltoid","trapezius"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — kettlebell. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Deltoïde postérieur, Trapèzes. Se fait d'un côté puis de l'autre.","ins":["Place one hand and knee on a bench for support.","Hold a kettlebell in the opposite hand with your arm extended.","Pull the kettlebell toward your hip by driving your elbow back.","Squeeze your back at the top of the movement.","Lower the kettlebell with control.","Complete reps on one side, then switch."],"met":6.0},{"id":"one-arm-kettlebell-shoulder-press","n":"Développé épaules un bras au KB","en":"One Arm Kettlebell Shoulder Press","c":"strength","eq":"kettlebell","pm":["anterior_deltoid","lateral_deltoid"],"sm":["obliques","trapezius","triceps_brachii"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — kettlebell. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Obliques, Trapèzes, Triceps. Se fait d'un côté puis de l'autre.","ins":["Hold a kettlebell in the racked position at one shoulder.","Stand tall with feet hip-width apart.","Press the kettlebell straight overhead until your arm is locked out.","Keep your core tight throughout.","Lower the kettlebell back to the rack position with control.","Complete reps on one side, then switch."],"met":6.0},{"id":"one-arm-kettlebell-swing","n":"Swing un bras au KB","en":"One Arm Kettlebell Swing","c":"strength","eq":"kettlebell","pm":["gluteus_maximus","hamstrings"],"sm":["anterior_deltoid","erector_spinae","obliques"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique — kettlebell. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Deltoïde antérieur, Lombaires (érecteurs du rachis), Obliques. Se fait d'un côté puis de l'autre.","ins":["Stand with feet shoulder-width apart and a kettlebell on the floor in front of you.","Hinge at the hips and grip the kettlebell with one hand.","Hike the kettlebell back between your legs.","Drive your hips forward to swing the kettlebell to chest height.","Let gravity bring the kettlebell back between your legs.","Complete reps on one side, then switch."],"met":8.0},{"id":"one-arm-kettlebell-tricep-kickback","n":"Kickback triceps un bras au KB","en":"One-Arm Kettlebell Tricep Kickback","c":"strength","eq":"kettlebell","pm":["triceps_brachii"],"sm":["posterior_deltoid"],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — kettlebell. Travaille surtout : Triceps. En soutien : Deltoïde postérieur. Se fait d'un côté puis de l'autre.","ins":["Hinge forward at the hips with a flat back, knees softly bent.","Hold a kettlebell by the handle in one hand, palm facing the body.","Pin the upper arm to the side so it is parallel to the floor; the forearm hangs straight down.","Extend the elbow back to straighten the arm fully behind you, keeping the upper arm motionless.","Squeeze the tricep at lockout, then return under control to the starting position.","Complete all reps on one side, then switch hands."],"met":5.0},{"id":"one-arm-landmine-press","n":"Développé landmine un bras","en":"One-Arm Landmine Press","c":"strength","eq":"barbell","pm":["anterior_deltoid","pectoralis_major"],"sm":["obliques","serratus_anterior","triceps_brachii"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Deltoïde antérieur, Pectoraux. En soutien : Obliques, Dentelé antérieur, Triceps. Se fait d'un côté puis de l'autre.","ins":["Anchor one end of a barbell in a landmine attachment and load the free end.","Kneel on one knee or stand and grip the sleeve end at shoulder height with one hand.","Press the bar upward and forward along its arc until the arm is fully extended.","Lower the bar back to shoulder height under control.","Complete all reps before switching sides."],"met":6.0},{"id":"one-arm-lat-pulldown","n":"Tirage vertical un bras","en":"One-Arm Lat Pulldown","c":"strength","eq":"cable","pm":["latissimus_dorsi"],"sm":["biceps_brachii","posterior_deltoid","rhomboids"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — poulie. Travaille surtout : Grand dorsal. En soutien : Biceps, Deltoïde postérieur, Rhomboïdes. Se fait d'un côté puis de l'autre.","ins":["Attach a single-handle to the cable pulldown station and sit with your thighs secured under the pad.","Reach up and grasp the handle with one hand, arm fully extended.","Pull the handle down toward your shoulder, driving your elbow toward your hip.","Pause briefly at full contraction, then return to the starting position with control.","Complete all reps on one side before switching."],"met":6.0},{"id":"one-arm-seated-cable-row","n":"Rowing assis un bras à la poulie","en":"One-Arm Seated Cable Row","c":"strength","eq":"cable","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","posterior_deltoid","trapezius"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — poulie. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Deltoïde postérieur, Trapèzes. Se fait d'un côté puis de l'autre.","ins":["Sit at the cable row station and hold one handle with the working arm extended.","Plant the feet, sit tall and brace the trunk without leaning back.","Pull the handle towards the lower ribs while drawing the shoulder blade back.","Pause briefly without rotating the torso or shrugging the shoulder.","Extend the arm under control, finish the set and repeat on the other side."],"met":6.0},{"id":"one-arm-single-leg-dumbbell-romanian-deadlift","n":"Soulevé de terre roumain une jambe un bras à l'haltère","en":"One-Arm Single-Leg Dumbbell Romanian Deadlift","c":"strength","eq":"dumbbell","pm":["gluteus_maximus","hamstrings"],"sm":["erector_spinae","forearm_flexors","gluteus_medius","obliques"],"d":"advanced","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — haltères. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis), Fléchisseurs de l'avant-bras, Moyen fessier, Obliques. Se fait d'un côté puis de l'autre.","ins":["Stand on one leg holding a dumbbell in the opposite hand.","Free arm out to the side for balance, free leg hovering just off the floor.","Hinge at the standing hip, pushing it back while the free leg extends behind to counterbalance.","Keep the hips square to the floor — do not open them to the side.","Lower the dumbbell toward the foot of the standing leg, feeling a deep hamstring stretch.","Drive the hip forward to return to standing under control.","Complete all reps on one side, then switch."],"met":6.0},{"id":"one-arm-single-leg-kettlebell-romanian-deadlift","n":"Soulevé de terre roumain une jambe un bras au KB","en":"One-Arm Single-Leg Kettlebell Romanian Deadlift","c":"strength","eq":"kettlebell","pm":["gluteus_maximus","hamstrings"],"sm":["erector_spinae","forearm_flexors","gluteus_medius","obliques"],"d":"advanced","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — kettlebell. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis), Fléchisseurs de l'avant-bras, Moyen fessier, Obliques. Se fait d'un côté puis de l'autre.","ins":["Stand on one leg holding a kettlebell in the opposite hand by the handle.","Free arm out to the side for balance, free leg hovering behind.","Hinge at the standing hip, pushing it back while the free leg extends to counterbalance.","Keep hips square to the floor; the kettlebell tracks straight down the shin.","Feel a deep hamstring stretch on the standing leg at the bottom.","Drive the hip forward to return to standing.","Complete all reps on one side, then switch."],"met":6.0},{"id":"overhead-squat","n":"Squat bras tendus au-dessus de la tête","en":"Overhead Squat","c":"strength","eq":"barbell","pm":["gluteus_maximus","quadriceps"],"sm":["erector_spinae","lateral_deltoid","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Deltoïde latéral, Trapèzes.","ins":["Hold a barbell overhead with a wide snatch grip and arms locked out.","Stand with feet slightly wider than shoulder-width.","Squat down by pushing your hips back and bending your knees.","Keep the bar directly over the middle of your feet.","Drive through your heels to stand back up.","Repeat for the desired number of reps."],"met":6.0},{"id":"overhead-tricep-extension","n":"Extension triceps au-dessus de la tête","en":"Overhead Tricep Extension","c":"strength","eq":"dumbbell","pm":["triceps_brachii"],"sm":[],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Triceps.","ins":["Stand or sit holding a dumbbell overhead with both hands.","Lower the dumbbell behind your head by bending your elbows.","Extend your arms back to the starting position.","Keep your elbows close to your head throughout.","Repeat."],"met":5.0},{"id":"overhead-triceps-stretch","n":"Étirement des triceps au-dessus de la tête","en":"Overhead Triceps Stretch","c":"stretching","eq":"","pm":["triceps_brachii"],"sm":["latissimus_dorsi"],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Triceps. En soutien : Grand dorsal. Se fait d'un côté puis de l'autre.","ins":["Raise one arm overhead and bend the elbow.","Let your hand drop down behind your head.","Use the other hand to press the bent elbow back.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"pause-deadlift","n":"Soulevé de terre avec pause","en":"Pause Deadlift","c":"strength","eq":"barbell","pm":["erector_spinae","gluteus_maximus","hamstrings"],"sm":["quadriceps","trapezius"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre. Travaille surtout : Lombaires (érecteurs du rachis), Grand fessier, Ischio-jambiers. En soutien : Quadriceps, Trapèzes.","ins":["Set up for a conventional deadlift.","Pull the bar off the floor and pause when it passes your knees.","Hold for 2–3 seconds, then complete the lift.","Lower under control.","Repeat."],"met":6.0},{"id":"pause-pull-up","n":"Traction avec pause","en":"Pause Pull-Up","c":"strength","eq":"pull_up_bar","pm":["latissimus_dorsi"],"sm":["biceps_brachii","posterior_deltoid","rhomboids","trapezius"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre de traction. Travaille surtout : Grand dorsal. En soutien : Biceps, Deltoïde postérieur, Rhomboïdes, Trapèzes.","ins":["Hang from a pull-up bar with an overhand grip, arms fully extended.","Pull yourself up until your chin clears the bar.","Pause and hold that top position for a moment.","Lower yourself back down under control to a full hang.","Repeat for the desired number of reps."],"met":6.0},{"id":"pause-squat","n":"Squat avec pause","en":"Pause Squat","c":"strength","eq":"barbell","pm":["gluteus_maximus","quadriceps"],"sm":["erector_spinae","gluteus_medius","hamstrings"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Moyen fessier, Ischio-jambiers.","ins":["Unrack a barbell and rest it across your upper back.","Stand with feet shoulder-width apart.","Squat down until your thighs are parallel to the floor.","Hold the bottom position for 2-3 seconds.","Drive through your heels to stand back up.","Repeat for the desired number of reps."],"met":6.0},{"id":"paused-bench-press","n":"Développé couché avec pause","en":"Paused Bench Press","c":"strength","eq":"barbell","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Lie on a flat bench and grip the barbell slightly wider than shoulder-width.","Unrack the bar and lower it to your chest.","Pause on your chest for 1-2 seconds.","Press the bar back up until your arms are fully extended.","Control the descent on every rep.","Repeat for the desired number of reps."],"met":6.0},{"id":"paused-incline-bench-press","n":"Développé incliné avec pause","en":"Paused Incline Bench Press","c":"strength","eq":"barbell","pm":["anterior_deltoid","pectoralis_major"],"sm":["triceps_brachii"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Deltoïde antérieur, Pectoraux. En soutien : Triceps.","ins":["Lie on an incline bench and grip the barbell slightly wider than shoulder-width.","Unrack the bar and lower it to your upper chest.","Pause on your chest for 1-2 seconds.","Press the bar back up until your arms are fully extended.","Keep your shoulder blades retracted throughout.","Repeat for the desired number of reps."],"met":6.0},{"id":"paused-ohp","n":"Développé militaire avec pause","en":"Paused Overhead Press","c":"strength","eq":"barbell","pm":["anterior_deltoid","lateral_deltoid"],"sm":["trapezius","triceps_brachii"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Trapèzes, Triceps.","ins":["Set up with a barbell racked at shoulder height, feet shoulder-width apart, and the core braced.","Press the bar straight overhead until the elbows are fully locked out.","Lower the bar under control back down to the front of the shoulders.","Hold a full one-second pause at the shoulders, keeping tension and eliminating any bounce.","Press back up from the dead stop without using leg drive."],"met":6.0},{"id":"pec-deck","n":"Pec deck (butterfly)","en":"Pec Deck","c":"strength","eq":"pec_deck","pm":["pectoralis_major"],"sm":["anterior_deltoid","serratus_anterior"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — pec deck. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Dentelé antérieur.","ins":["Sit in the pec deck machine and place your forearms against the pads.","Adjust the seat so pads align with mid-chest height.","Squeeze the pads together in front of your chest.","Hold the contraction briefly at the center.","Return under control to the starting position.","Repeat for the desired number of reps."],"met":5.0},{"id":"pendlay-row","n":"Rowing Pendlay","en":"Pendlay Row","c":"strength","eq":"barbell","pm":["latissimus_dorsi","rhomboids","trapezius"],"sm":["biceps_brachii","erector_spinae","posterior_deltoid"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre. Travaille surtout : Grand dorsal, Rhomboïdes, Trapèzes. En soutien : Biceps, Lombaires (érecteurs du rachis), Deltoïde postérieur.","ins":["Load a barbell and set it on the floor.","Hinge at the hips until your torso is parallel to the ground, knees slightly bent.","Grip the bar slightly wider than shoulder-width with an overhand grip.","Explosively pull the bar to your lower chest.","Lower the bar back to the floor under control and pause before the next rep.","Repeat."],"met":6.0},{"id":"pigeon-stretch","n":"Étirement du pigeon","en":"Pigeon Stretch","c":"stretching","eq":"","pm":["gluteus_maximus"],"sm":["gluteus_medius","hip_flexors"],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Grand fessier. En soutien : Moyen fessier, Fléchisseurs de hanche. Se fait d'un côté puis de l'autre.","ins":["From all fours, bring one knee forward and lay the shin across in front.","Extend the other leg straight back, top of the foot down.","Sink your hips toward the floor and keep them square.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"pike-push-ups","n":"Pompes piquées (pike)","en":"Pike Push Ups","c":"strength","eq":"","pm":["anterior_deltoid","lateral_deltoid"],"sm":["trapezius","triceps_brachii"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Trapèzes, Triceps.","ins":["Start in a downward dog position with hips high and hands shoulder-width apart.","Walk your feet closer to your hands.","Bend your elbows and lower your head toward the floor.","Keep your hips high throughout.","Press back up until your arms are fully extended.","Repeat for the desired number of reps."],"met":5.0},{"id":"pilates-kneeling-side-kick","n":"Coup de pied latéral à genoux (Pilates)","en":"Pilates Kneeling Side Kick","c":"strength","eq":"","pm":["gluteus_medius","obliques"],"sm":["gluteus_maximus","hip_flexors"],"d":"intermediate","bw":true,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Moyen fessier, Obliques. En soutien : Grand fessier, Fléchisseurs de hanche. Se fait d'un côté puis de l'autre.","ins":["Kneel on one knee and place the same-side hand on the floor, the other hand behind the head.","Extend the top leg out to the side at hip height with the foot flexed.","Keep the trunk perfectly still and swing the leg forward as far as the pelvis stays square.","Swing the leg back behind the line of the body without arching the lower back.","Repeat for the desired number of repetitions and change sides."],"met":5.0},{"id":"pilates-leg-pull-back","n":"Leg pull dos au sol (Pilates)","en":"Pilates Leg Pull Back","c":"strength","eq":"","pm":["erector_spinae","gluteus_maximus"],"sm":["hamstrings","posterior_deltoid","triceps_brachii"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Grand fessier. En soutien : Ischio-jambiers, Deltoïde postérieur, Triceps.","ins":["Sit with the legs straight and the hands on the floor behind the hips, fingers pointing forward.","Press into the hands and heels and lift the hips into a reverse plank.","Keeping the hips level and high, lift one straight leg as far as the pelvis stays still.","Lower the leg under control and repeat with the other one.","Finish the set and lower the hips to the floor."],"met":5.0},{"id":"pilates-leg-pull-front","n":"Leg pull face au sol (Pilates)","en":"Pilates Leg Pull Front","c":"strength","eq":"","pm":["gluteus_maximus","rectus_abdominis"],"sm":["anterior_deltoid","erector_spinae","transverse_abdominis"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Grand fessier, Grand droit (abdominaux). En soutien : Deltoïde antérieur, Lombaires (érecteurs du rachis), Transverse.","ins":["Set up in a high plank with the hands under the shoulders and the body in one line.","Brace the trunk and squeeze the glutes so the hips cannot rotate.","Lift one straight leg a few centimetres above hip height without letting the pelvis tilt.","Lower it under control and repeat with the other leg.","Keep alternating for the desired number of repetitions."],"met":5.0},{"id":"pilates-roll-down","n":"Déroulé vertébral (Pilates)","en":"Pilates Roll Down","c":"stretching","eq":"","pm":["erector_spinae"],"sm":["hamstrings","rectus_abdominis"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis). En soutien : Ischio-jambiers, Grand droit (abdominaux).","ins":["Stand tall with the feet hip-width apart and the arms hanging at the sides.","Drop the chin to the chest and start rolling down one vertebra at a time.","Let the arms and head hang heavy once the spine is fully rolled down.","Roll back up the same way, stacking the vertebrae one by one, head last.","Repeat for the desired number of repetitions."],"met":5.0},{"id":"pilates-roll-over","n":"Roll over (Pilates)","en":"Pilates Roll Over","c":"strength","eq":"","pm":["rectus_abdominis","transverse_abdominis"],"sm":["erector_spinae","hip_flexors"],"d":"advanced","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Grand droit (abdominaux), Transverse. En soutien : Lombaires (érecteurs du rachis), Fléchisseurs de hanche.","ins":["Lie on your back with the legs straight and the arms pressed into the mat beside you.","Lift both legs to vertical without letting the lower back arch.","Press the arms down and take the legs overhead until they are parallel to the floor behind you.","Open the legs slightly, flex the feet, and roll the spine down one vertebra at a time.","Return the legs to vertical and repeat for the desired number of repetitions."],"met":5.0},{"id":"pilates-saw","n":"La scie (Pilates)","en":"Pilates Saw","c":"stretching","eq":"","pm":["erector_spinae","obliques"],"sm":["adductors","hamstrings"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Obliques. En soutien : Adducteurs, Ischio-jambiers.","ins":["Sit tall with the legs straight and slightly wider than the hips, arms out to the sides.","Rotate the torso to one side, keeping both sit bones on the floor.","Fold forward over that leg and reach the opposite hand past the little toe.","Roll back up through the spine and return to the centre.","Repeat to the other side and continue alternating."],"met":5.0},{"id":"pilates-side-bend","n":"Flexion latérale (Pilates)","en":"Pilates Side Bend","c":"strength","eq":"","pm":["gluteus_medius","obliques"],"sm":["anterior_deltoid","transverse_abdominis"],"d":"intermediate","bw":true,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Moyen fessier, Obliques. En soutien : Deltoïde antérieur, Transverse. Se fait d'un côté puis de l'autre.","ins":["Sit on one hip with the legs bent to the side and the supporting hand on the floor under the shoulder.","Press into the hand and the lower leg to lift the hips off the floor.","Reach the top arm overhead so the body forms a long arc from the hand to the feet.","Lower the hips under control back towards the mat.","Complete the repetitions and change sides."],"met":5.0},{"id":"pilates-spine-stretch-forward","n":"Étirement du dos vers l'avant (Pilates)","en":"Pilates Spine Stretch Forward","c":"stretching","eq":"","pm":["erector_spinae","rectus_abdominis"],"sm":["hamstrings","transverse_abdominis"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Grand droit (abdominaux). En soutien : Ischio-jambiers, Transverse.","ins":["Sit tall with the legs straight and slightly wider than the hips, feet flexed.","Reach the arms forward at shoulder height.","Drop the chin and curl the spine forward one vertebra at a time, reaching past the toes.","Restack the spine from the base upwards until you are sitting tall again.","Repeat for the desired number of repetitions."],"met":5.0},{"id":"pilates-spine-twist","n":"Rotation du buste (Pilates)","en":"Pilates Spine Twist","c":"stretching","eq":"","pm":["obliques"],"sm":["erector_spinae","transverse_abdominis"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Étirement, au poids du corps. Travaille surtout : Obliques. En soutien : Lombaires (érecteurs du rachis), Transverse.","ins":["Sit tall with the legs straight and together, feet flexed, arms out to the sides at shoulder height.","Grow tall through the spine and press both sit bones into the floor.","Rotate the trunk to one side as far as the hips stay square, then return to the centre.","Rotate to the other side in the same way.","Keep alternating for the desired number of repetitions."],"met":5.0},{"id":"pistol-squat","n":"Pistol squat","en":"Pistol Squat","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["gluteus_medius","hamstrings","hip_flexors"],"d":"advanced","bw":true,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Moyen fessier, Ischio-jambiers, Fléchisseurs de hanche. Se fait d'un côté puis de l'autre.","ins":["Stand on one leg with the other extended forward, arms out for balance.","Hinge at the hips and bend the standing knee, keeping the chest up.","Descend slowly until the back of the thigh touches the calf.","Drive through the standing heel to return to standing.","Complete reps per side, then switch legs."],"met":6.0},{"id":"planche","n":"Planche (planche gymnique)","en":"Planche","c":"strength","eq":"","pm":["anterior_deltoid","pectoralis_major"],"sm":["serratus_anterior","triceps_brachii"],"d":"advanced","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Deltoïde antérieur, Pectoraux. En soutien : Dentelé antérieur, Triceps.","ins":["Begin in a push-up position with hands turned outward.","Lean forward until your center of mass is over your hands.","Lift your feet off the ground keeping the body horizontal.","Hold the position.","Return to the floor with control."],"met":6.0},{"id":"plank","n":"Gainage (planche)","en":"Plank","c":"strength","eq":"","pm":["rectus_abdominis","transverse_abdominis"],"sm":["erector_spinae"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Grand droit (abdominaux), Transverse. En soutien : Lombaires (érecteurs du rachis).","ins":["Place your forearms on the floor with elbows under your shoulders.","Extend your legs back and rise onto your toes.","Keep your body in a straight line from head to heels.","Brace your core and squeeze your glutes.","Hold the position for the desired duration.","Lower your knees to exit the hold."],"met":3.5},{"id":"plank-knee-tuck","n":"Planche avec genou rentré","en":"Plank Knee Tuck","c":"strength","eq":"","pm":["hip_flexors","rectus_abdominis"],"sm":["anterior_deltoid","obliques","serratus_anterior","transverse_abdominis"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Deltoïde antérieur, Obliques, Dentelé antérieur, Transverse.","ins":["Set up in a high plank with the hands under the shoulders and the body in a straight line from head to heels.","Press the floor away and brace the trunk so the hips neither sag nor pike.","Draw one knee in towards the chest without letting the hips rise.","Extend the leg back to the starting position under control.","Repeat with the other leg and keep alternating for the desired number of repetitions."],"met":5.0},{"id":"plate-loaded-donkey-calf-raise","n":"Mollets à l'âne chargés","en":"Plate-Loaded Donkey Calf Raise","c":"strength","eq":"donkey_calf_raise_machine","pm":["gastrocnemius"],"sm":["soleus"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — machine mollets à l'âne. Travaille surtout : Mollets (gastrocnémiens). En soutien : Soléaire.","ins":["Load the plate horns and step onto the platform with the balls of your feet on the edge and your heels hanging free.","Bend forward at the hips and settle the pad across your hips, then rest your forearms on the support in front of you.","Keep your knees straight and your back flat, with your torso close to parallel to the floor.","Push through the balls of your feet and raise your heels as high as you can, pausing briefly at the top.","Lower your heels below the platform until you feel a strong calf stretch, and repeat for the desired number of repetitions."],"met":5.0},{"id":"plate-loaded-glute-drive","n":"Glute drive chargé","en":"Plate-Loaded Glute Drive","c":"strength","eq":"hip_thrust_machine","pm":["gluteus_maximus"],"sm":["gluteus_medius","hamstrings","quadriceps"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — machine hip thrust. Travaille surtout : Grand fessier. En soutien : Moyen fessier, Ischio-jambiers, Quadriceps.","ins":["Load the plate horns evenly and sit into the machine with your upper back against the pad and your feet flat on the platform.","Pull the hip pad or lap bar across your hips and adjust it so it sits on the crease of the hips, not on your stomach.","Set your feet so that your shins will be roughly vertical when your hips are at the top, and take hold of the handles.","Drive your hips up by squeezing the glutes until your thighs are level with your torso, and hold briefly at the top.","Lower under control until your hips are just short of the bottom of the range, and repeat for the desired number of repetitions."],"met":6.0},{"id":"plate-loaded-lateral-raise","n":"Élévation latérale chargée (machine)","en":"Plate-Loaded Lateral Raise","c":"strength","eq":"plate_loaded_lateral_raise_machine","pm":["lateral_deltoid"],"sm":["anterior_deltoid","trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — machine élévations latérales. Travaille surtout : Deltoïde latéral. En soutien : Deltoïde antérieur, Trapèzes.","ins":["Set the seat height so that the pivot of the arm pads lines up with the point of your shoulders when you sit down.","Load the plate horns evenly on both sides and sit with your back flat against the pad.","Place the outside of your upper arms against the pads with your elbows bent and your arms hanging down.","Push out and up against the pads until your upper arms are roughly level with your shoulders.","Lower under control until your arms are back at your sides, and repeat for the desired number of repetitions."],"met":5.0},{"id":"plate-loaded-shrug","n":"Haussements d'épaules chargés (machine)","en":"Plate-Loaded Shrug","c":"strength","eq":"shrug_machine","pm":["trapezius"],"sm":["forearm_flexors"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — machine à shrugs. Travaille surtout : Trapèzes. En soutien : Fléchisseurs de l'avant-bras.","ins":["Load the plate horns evenly and stand on the machine platform, facing away from the frame.","Take a handle in each hand with your arms hanging straight down at your sides and your shoulders relaxed.","Stand tall with your chest up, your chin level and your knees soft.","Shrug your shoulders straight up toward your ears as high as they will go, and hold for a moment at the top.","Lower under control until your shoulders are fully down, and repeat for the desired number of repetitions."],"met":5.0},{"id":"plate-pinch","n":"Pince de disques","en":"Plate Pinch","c":"strength","eq":"plates","pm":["forearm_flexors"],"sm":["trapezius"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation statique — disques. Travaille surtout : Fléchisseurs de l'avant-bras. En soutien : Trapèzes. Se fait d'un côté puis de l'autre.","ins":["Place two weight plates on the floor side by side with the smooth sides facing out.","Squat down, grip both plates together between the fingers and thumb of one hand — no handles, just pinch.","Stand up and hold the plates at the side for time, keeping the arm straight.","Set them back down under control.","Repeat on the other hand."],"met":5.0},{"id":"plate-pullover","n":"Pull-over au disque","en":"Plate Pullover","c":"strength","eq":"plates","pm":["latissimus_dorsi","pectoralis_major"],"sm":["serratus_anterior","triceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — disques. Travaille surtout : Grand dorsal, Pectoraux. En soutien : Dentelé antérieur, Triceps.","ins":["Lie flat on a bench holding a plate with both hands.","Press the plate over the chest with arms nearly straight.","Lower the plate back in an arc behind the head until you feel a stretch.","Pull the plate back over the chest along the same arc.","Repeat for the prescribed reps."],"met":6.0},{"id":"plow-pose","n":"Posture de la charrue","en":"Plow Pose","c":"stretching","eq":"","pm":["erector_spinae","hamstrings"],"sm":["gluteus_maximus","trapezius"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Ischio-jambiers. En soutien : Grand fessier, Trapèzes.","ins":["Lie on your back with the arms alongside the body, palms down.","Lift both legs overhead and support the lower back with the hands.","Lower the toes towards the floor behind the head, keeping the legs as straight as comfort allows.","Hold the position for the prescribed time, breathing steadily and keeping the head still.","Roll down one vertebra at a time with the hands supporting the back."],"met":5.0},{"id":"plyo-lunge","n":"Fentes sautées","en":"Plyo Lunge","c":"plyometrics","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["gluteus_medius","hamstrings"],"d":"intermediate","bw":true,"uni":true,"img":["start","peak"],"desc":"Exercice pliométrique, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Moyen fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Start in a forward lunge with one foot ahead of the other.","Drop into a deep lunge with the back knee almost touching the floor.","Drive both feet off the floor, switching legs in mid-air.","Land softly in a lunge with the opposite leg forward.","Continue alternating without pausing."],"met":7.0},{"id":"plyo-push-up","n":"Pompes plyométriques","en":"Plyo Push-Up","c":"plyometrics","eq":"","pm":["pectoralis_major","triceps_brachii"],"sm":["anterior_deltoid"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice pliométrique, au poids du corps. Travaille surtout : Pectoraux, Triceps. En soutien : Deltoïde antérieur.","ins":["Set up in a standard push-up position with hands shoulder-width.","Lower yourself with control until the chest nearly touches the floor.","Drive up explosively so the hands leave the floor.","Land softly with the elbows slightly bent.","Repeat without pausing for the prescribed reps."],"met":7.0},{"id":"preacher-curl","n":"Curl pupitre","en":"Preacher Curl","c":"strength","eq":"ez_bar","pm":["biceps_brachii"],"sm":["brachialis"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre EZ. Travaille surtout : Biceps. En soutien : Brachial.","ins":["Sit at a preacher bench with your upper arms resting on the pad.","Hold an EZ-bar with an underhand grip.","Curl the bar up toward your shoulders.","Lower with control until arms are nearly straight.","Repeat."],"met":5.0},{"id":"preacher-hammer-curl","n":"Curl marteau au pupitre","en":"Preacher Hammer Curl","c":"strength","eq":"dumbbell","pm":["brachialis","brachioradialis"],"sm":["biceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Brachial, Brachio-radial. En soutien : Biceps.","ins":["Sit at a preacher bench with a dumbbell in each hand.","Rest your upper arms on the pad with palms facing each other.","Curl the dumbbells up while keeping your wrists neutral.","Squeeze your biceps at the top of the movement.","Lower the dumbbells with control.","Repeat for the desired number of reps."],"met":5.0},{"id":"pseudo-planche-push-ups","n":"Pompes pseudo-planche","en":"Pseudo Planche Push Ups","c":"strength","eq":"","pm":["anterior_deltoid","pectoralis_major"],"sm":["serratus_anterior","triceps_brachii"],"d":"advanced","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Deltoïde antérieur, Pectoraux. En soutien : Dentelé antérieur, Triceps.","ins":["Start in a push-up position with your hands turned so fingers point back.","Lean your shoulders forward past your wrists.","Lower your chest toward the floor by bending your elbows.","Keep your body in a straight line.","Press back up while maintaining the forward lean.","Repeat for the desired number of reps."],"met":5.0},{"id":"pull-up","n":"Traction pronation","en":"Pull-Up","c":"strength","eq":"pull_up_bar","pm":["latissimus_dorsi"],"sm":["biceps_brachii","posterior_deltoid","rhomboids"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre de traction. Travaille surtout : Grand dorsal. En soutien : Biceps, Deltoïde postérieur, Rhomboïdes.","ins":["Hang from a bar with an overhand grip, slightly wider than shoulder-width.","Pull yourself up until your chin is over the bar.","Lower yourself under control to a dead hang.","Repeat."],"met":6.0},{"id":"puppy-pose","n":"Posture du chiot","en":"Puppy Pose","c":"stretching","eq":"","pm":["latissimus_dorsi","posterior_deltoid"],"sm":["erector_spinae","trapezius"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Grand dorsal, Deltoïde postérieur. En soutien : Lombaires (érecteurs du rachis), Trapèzes.","ins":["Kneel on all fours with the hips over the knees and the hands under the shoulders.","Walk the hands forward and lower the chest towards the floor, keeping the hips high.","Rest the forehead or the chin on the mat and let the armpits soften downwards.","Hold the position for the prescribed time, breathing into the upper back.","Walk the hands back and sit onto the heels to come out."],"met":5.0},{"id":"push-jerk","n":"Push jerk","en":"Push Jerk","c":"olympic","eq":"barbell","pm":["anterior_deltoid","triceps_brachii"],"sm":["gluteus_maximus","quadriceps","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Mouvement d'haltérophilie — barre. Travaille surtout : Deltoïde antérieur, Triceps. En soutien : Grand fessier, Quadriceps, Trapèzes.","ins":["Hold a barbell in the front rack position at your shoulders.","Stand with feet hip-width apart.","Dip by bending your knees slightly.","Drive explosively through your legs and press the bar overhead.","Drop into a quarter-squat under the bar and lock out your arms.","Stand up fully and lower the bar to repeat."],"met":8.0},{"id":"push-press","n":"Push press","en":"Push Press","c":"strength","eq":"barbell","pm":["anterior_deltoid","lateral_deltoid"],"sm":["quadriceps","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Quadriceps, Triceps.","ins":["Stand with a barbell racked on your front deltoids.","Dip slightly at the knees.","Drive up with your legs and press the bar overhead.","Lock out fully.","Lower to the start.","Repeat."],"met":6.0},{"id":"push-up","n":"Pompes","en":"Push-Up","c":"strength","eq":"","pm":["pectoralis_major","triceps_brachii"],"sm":["anterior_deltoid"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Pectoraux, Triceps. En soutien : Deltoïde antérieur.","ins":["Start in a high plank position with hands shoulder-width apart.","Lower your body until your chest nearly touches the floor.","Push back up to the starting position.","Keep your body in a straight line throughout.","Repeat."],"met":5.0},{"id":"pyramid-pose","n":"Posture de la pyramide","en":"Pyramid Pose","c":"stretching","eq":"","pm":["hamstrings"],"sm":["erector_spinae","gastrocnemius"],"d":"intermediate","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis), Mollets (gastrocnémiens). Se fait d'un côté puis de l'autre.","ins":["Step one foot back about a leg's length and turn the back foot out slightly.","Square both hip points towards the front of the mat and keep both legs straight.","Hinge from the hips and fold over the front leg, bringing the hands to the floor, blocks or the shin.","Hold the fold for the prescribed time with the spine long rather than rounded.","Press into the feet to come up and repeat on the other side."],"met":5.0},{"id":"rack-pull","n":"Soulevé de terre partiel (rack pull)","en":"Rack Pull","c":"strength","eq":"barbell","pm":["erector_spinae","gluteus_maximus","hamstrings","trapezius"],"sm":["forearm_flexors","forearms","latissimus_dorsi"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre. Travaille surtout : Lombaires (érecteurs du rachis), Grand fessier, Ischio-jambiers, Trapèzes. En soutien : Fléchisseurs de l'avant-bras, Avant-bras, Grand dorsal.","ins":["Set the safety pins in a power rack at knee height and place a loaded barbell on them.","Stand with feet hip-width apart and grip the bar just outside your legs.","Brace your core, retract your shoulder blades, and drive through your legs to lift the bar.","Lock out your hips and knees fully at the top.","Return the bar to the pins under control and reset before the next rep."],"met":6.0},{"id":"rear-delt-fly","n":"Oiseau (arrière d'épaule)","en":"Rear Delt Fly","c":"strength","eq":"dumbbell","pm":["posterior_deltoid","rhomboids"],"sm":["trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Deltoïde postérieur, Rhomboïdes. En soutien : Trapèzes.","ins":["Hold dumbbells and hinge forward at the hips.","With a slight bend in elbows, raise the dumbbells out to the sides.","Squeeze your shoulder blades at the top.","Lower with control.","Repeat."],"met":5.0},{"id":"renegade-row","n":"Rowing renegade","en":"Renegade Row","c":"strength","eq":"dumbbell","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","obliques","rectus_abdominis"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — haltères. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Obliques, Grand droit (abdominaux).","ins":["Start in a high plank with a hand on each of two dumbbells, shoulder-width apart, and the feet set wide for stability.","Brace the trunk so the body forms a straight line from head to heels.","Row one dumbbell up toward the hip, driving the elbow back along the ribs.","Keep the hips square to the floor and do not let the body twist.","Lower the dumbbell to the floor under control.","Repeat on the other side and keep alternating."],"met":6.0},{"id":"reverse-crunches","n":"Crunchs inversés","en":"Reverse Crunches","c":"strength","eq":"","pm":["rectus_abdominis"],"sm":["hip_flexors","obliques","transverse_abdominis"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée, au poids du corps. Travaille surtout : Grand droit (abdominaux). En soutien : Fléchisseurs de hanche, Obliques, Transverse.","ins":["Lie on your back with your arms at your sides.","Raise your legs with knees bent to 90 degrees.","Curl your hips off the floor by contracting your lower abs.","Bring your knees toward your chest.","Lower your hips with control.","Repeat for the desired number of reps."],"met":3.5},{"id":"reverse-curl","n":"Curl inversé","en":"Reverse Curl","c":"strength","eq":"barbell","pm":["brachialis","forearm_extensors"],"sm":["biceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre. Travaille surtout : Brachial, Extenseurs de l'avant-bras. En soutien : Biceps.","ins":["Stand and hold a barbell with an overhand grip.","Curl the bar up toward your shoulders.","Lower under control.","Repeat."],"met":5.0},{"id":"reverse-grip-bent-over-row","n":"Rowing buste penché prise inversée","en":"Reverse Grip Bent Over Row","c":"strength","eq":"barbell","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","erector_spinae","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Lombaires (érecteurs du rachis), Trapèzes.","ins":["Stand with feet shoulder-width apart and grip a barbell underhand.","Hinge forward at the hips with a slight knee bend.","Let the bar hang with your arms extended.","Pull the bar to your lower abdomen by driving your elbows back.","Squeeze your back at the top.","Lower the bar with control.","Repeat for the desired number of reps."],"met":6.0},{"id":"reverse-grip-lat-pulldown","n":"Tirage vertical prise inversée","en":"Reverse Grip Lat Pulldown","c":"strength","eq":"cable","pm":["biceps_brachii","latissimus_dorsi"],"sm":["posterior_deltoid","rhomboids"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — poulie. Travaille surtout : Biceps, Grand dorsal. En soutien : Deltoïde postérieur, Rhomboïdes.","ins":["Attach a straight bar to a lat pulldown machine.","Grip the bar with an underhand grip, shoulder-width apart.","Sit and secure your thighs under the pad.","Pull the bar down to your upper chest.","Squeeze your lats and biceps at the bottom.","Return the bar to the starting position with control.","Repeat for the desired number of reps."],"met":6.0},{"id":"reverse-lunge","n":"Fente arrière","en":"Reverse Lunge","c":"strength","eq":"dumbbell","pm":["gluteus_maximus","quadriceps"],"sm":["hamstrings"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Grand fessier, Quadriceps. En soutien : Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Stand holding dumbbells at your sides.","Step one leg back and lower your knee toward the floor.","Lower until your front thigh is parallel to the floor.","Push through your front heel to return to standing.","Repeat on both sides."],"met":6.0},{"id":"reverse-nordic-curl","n":"Nordic inversé","en":"Reverse Nordic Curl","c":"strength","eq":"","pm":["quadriceps"],"sm":["hip_flexors","rectus_abdominis"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage, au poids du corps. Travaille surtout : Quadriceps. En soutien : Fléchisseurs de hanche, Grand droit (abdominaux).","ins":["Kneel on a pad with your feet flat and torso upright.","Keep your hips extended and core braced.","Slowly lean your torso backward while keeping your body in a straight line.","Lower as far as you can control with your quadriceps.","Pull yourself back up to the starting position.","Repeat for the desired number of reps."],"met":3.5},{"id":"reverse-plank","n":"Planche inversée","en":"Reverse Plank","c":"strength","eq":"","pm":["erector_spinae","gluteus_maximus"],"sm":["hamstrings","posterior_deltoid","triceps_brachii"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Grand fessier. En soutien : Ischio-jambiers, Deltoïde postérieur, Triceps.","ins":["Sit on the floor with your legs extended in front of you.","Place your hands behind you with fingers pointing toward your feet.","Lift your hips off the floor to form a straight line from head to heels.","Squeeze your glutes and brace your core.","Hold the position for the desired duration.","Lower your hips with control to exit."],"met":5.0},{"id":"reverse-plank-dips","n":"Dips en planche inversée","en":"Reverse Plank Dips","c":"strength","eq":"","pm":["triceps_brachii"],"sm":["erector_spinae","gluteus_maximus","posterior_deltoid"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Triceps. En soutien : Lombaires (érecteurs du rachis), Grand fessier, Deltoïde postérieur.","ins":["Sit with the legs straight and the hands on the floor behind the hips, fingers pointing forward.","Press into the hands and heels and lift the hips into a straight-leg reverse plank.","Bend the elbows straight back and lower the hips a short way towards the floor.","Push back up until the arms lock out, keeping the hips high.","Repeat for the desired number of repetitions."],"met":5.0},{"id":"reverse-tabletop-hip-pulses","n":"Pulsations de hanches en table inversée","en":"Reverse Tabletop Hip Pulses","c":"strength","eq":"","pm":["gluteus_maximus"],"sm":["erector_spinae","hamstrings"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Grand fessier. En soutien : Lombaires (érecteurs du rachis), Ischio-jambiers.","ins":["Sit with the knees bent, the feet flat and the hands on the floor behind you.","Press into the hands and feet and lift the hips until the trunk is level with the knees.","Keeping the elbows straight, lower the hips a few centimetres.","Squeeze the glutes to lift them back to level.","Pulse for the desired number of repetitions and lower down."],"met":5.0},{"id":"reverse-tabletop-hold","n":"Table inversée statique","en":"Reverse Tabletop Hold","c":"strength","eq":"","pm":["erector_spinae","gluteus_maximus"],"sm":["hamstrings","posterior_deltoid","triceps_brachii"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Grand fessier. En soutien : Ischio-jambiers, Deltoïde postérieur, Triceps.","ins":["Sit with the knees bent, the feet flat and the hands on the floor behind you, fingers pointing towards the heels.","Press into the hands and feet and lift the hips until the trunk is level with the knees.","Open the chest, draw the shoulders away from the ears and look straight ahead.","Hold the position for the prescribed time with the hips high.","Lower the hips under control to finish."],"met":5.0},{"id":"revolved-chair-pose","n":"Posture de la chaise en torsion","en":"Revolved Chair Pose","c":"strength","eq":"","pm":["obliques","quadriceps"],"sm":["erector_spinae","gluteus_maximus"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Obliques, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Grand fessier.","ins":["Set up in chair pose with the knees bent, the hips back and the palms together at the chest.","Keep the knees level with each other so the hips do not open into the twist.","Rotate the chest to one side and hook the opposite elbow outside that thigh.","Press the palms together and hold for the prescribed time, lengthening the spine on each inhale.","Come back to centre and repeat on the other side."],"met":5.0},{"id":"revolved-crescent-lunge","n":"Fente en croissant en torsion","en":"Revolved Crescent Lunge","c":"strength","eq":"","pm":["obliques","quadriceps"],"sm":["erector_spinae","hip_flexors"],"d":"intermediate","bw":true,"uni":true,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Obliques, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Fléchisseurs de hanche. Se fait d'un côté puis de l'autre.","ins":["Step into a high lunge with the front knee over the ankle and the back heel lifted.","Bring the palms together at the chest and square both hips towards the front of the mat.","Rotate the chest towards the front leg and hook the opposite elbow outside the thigh.","Hold the twist for the prescribed time, pressing the back heel towards the wall behind you.","Unwind and repeat on the other side."],"met":5.0},{"id":"ring-dead-hang","n":"Suspension aux anneaux","en":"Ring Dead Hang","c":"strength","eq":"rings","pm":["forearm_flexors"],"sm":["latissimus_dorsi","rectus_abdominis","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — anneaux. Travaille surtout : Fléchisseurs de l'avant-bras. En soutien : Grand dorsal, Grand droit (abdominaux), Trapèzes.","ins":["Grip a pair of gymnastic rings with a neutral grip, palms facing each other.","Hang with your arms fully extended and feet off the ground.","Let the rings rotate naturally; do not fight the grip.","Keep your shoulders engaged (no shrug to the ears) and core lightly braced.","Hold for the desired duration."],"met":4.5},{"id":"ring-dips","n":"Dips aux anneaux","en":"Ring Dips","c":"strength","eq":"rings","pm":["pectoralis_major","triceps_brachii"],"sm":["anterior_deltoid"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — anneaux. Travaille surtout : Pectoraux, Triceps. En soutien : Deltoïde antérieur.","ins":["Support yourself on the rings with arms locked out.","Lower your body by bending the elbows until upper arms are parallel to the ground.","Press back up to the starting position.","Repeat."],"met":6.0},{"id":"ring-face-pull","n":"Face pull aux anneaux","en":"Ring Face Pull","c":"strength","eq":"rings","pm":["posterior_deltoid","rhomboids"],"sm":["trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — anneaux. Travaille surtout : Deltoïde postérieur, Rhomboïdes. En soutien : Trapèzes.","ins":["Grip the rings and lean back so your body is at an angle.","Pull the rings toward your face, flaring elbows to the sides.","Hold briefly, then return.","Repeat."],"met":6.0},{"id":"ring-l-sit","n":"L-sit aux anneaux","en":"Ring L-Sit","c":"strength","eq":"rings","pm":["hip_flexors","rectus_abdominis"],"sm":["anterior_deltoid","latissimus_dorsi","quadriceps","triceps_brachii"],"d":"advanced","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — anneaux. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Deltoïde antérieur, Grand dorsal, Quadriceps, Triceps.","ins":["Set the rings at about hip height and grip them with the arms straight beside the body.","Press down on the rings and lift the body into the support position, with the shoulders pushed down and away from the ears.","Turn the rings out slightly, brace the abdominals and raise the straight legs until they are parallel to the floor.","Hold the position, keeping the rings steady and the knees locked.","Lower the legs, then the body, under control."],"met":6.0},{"id":"ring-muscle-up","n":"Muscle-up aux anneaux","en":"Ring Muscle-Up","c":"strength","eq":"rings","pm":["latissimus_dorsi","pectoralis_major","triceps_brachii"],"sm":["anterior_deltoid","biceps_brachii","rhomboids"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — anneaux. Travaille surtout : Grand dorsal, Pectoraux, Triceps. En soutien : Deltoïde antérieur, Biceps, Rhomboïdes.","ins":["Hang from the rings with a false grip, palms facing each other.","Pull explosively, driving the chest up to the rings.","Transition the elbows over the rings as the chest rises.","Press to full arm extension at the top.","Lower under control through the transition back to the hang."],"met":6.0},{"id":"ring-plank","n":"Gainage aux anneaux","en":"Ring Plank","c":"strength","eq":"rings","pm":["rectus_abdominis","transverse_abdominis"],"sm":["anterior_deltoid","obliques","pectoralis_major","serratus_anterior"],"d":"advanced","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — anneaux. Travaille surtout : Grand droit (abdominaux), Transverse. En soutien : Deltoïde antérieur, Obliques, Pectoraux, Dentelé antérieur.","ins":["Set the rings at about knee height and take hold of them with the arms straight under the shoulders.","Step the feet back into a plank, with the body in a straight line from head to heels.","Brace the abdominals and glutes and press the rings down and slightly out to keep them steady.","Hold the position without letting the hips sag or the rings drift apart.","Step the feet in and stand up to finish."],"met":6.0},{"id":"ring-push-up","n":"Pompes aux anneaux","en":"Ring Push-Up","c":"strength","eq":"rings","pm":["pectoralis_major","triceps_brachii"],"sm":["anterior_deltoid","serratus_anterior"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — anneaux. Travaille surtout : Pectoraux, Triceps. En soutien : Deltoïde antérieur, Dentelé antérieur.","ins":["Set the rings just above floor height.","Grip the rings and assume a plank position with arms straight.","Lower the chest toward the rings, keeping the elbows close to the body.","Press back up to full arm extension.","Repeat for the prescribed reps."],"met":6.0},{"id":"ring-row","n":"Rowing aux anneaux","en":"Ring Row","c":"strength","eq":"rings","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","posterior_deltoid","trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — anneaux. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Deltoïde postérieur, Trapèzes.","ins":["Set the rings at hip to chest height.","Grip the rings with palms facing each other, lean back at an angle with arms straight.","Brace the core and pull the chest toward the rings.","Squeeze the shoulder blades together at the top.","Lower under control to a full-arm extension."],"met":6.0},{"id":"rings-inverted-row","n":"Rowing inversé aux anneaux","en":"Rings Inverted Row","c":"strength","eq":"rings","pm":["latissimus_dorsi","rhomboids","trapezius"],"sm":["biceps_brachii","forearm_flexors","posterior_deltoid","rectus_abdominis"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — anneaux. Travaille surtout : Grand dorsal, Rhomboïdes, Trapèzes. En soutien : Biceps, Fléchisseurs de l'avant-bras, Deltoïde postérieur, Grand droit (abdominaux).","ins":["Set the rings just above hip height.","Lie under the rings and grip them with palms facing each other.","Walk the feet forward so the body forms a straight line.","Pull the chest toward the rings, squeezing the shoulder blades.","Lower under control to a full-arm extension."],"met":6.0},{"id":"romanian-deadlift","n":"Soulevé de terre roumain","en":"Romanian Deadlift","c":"strength","eq":"barbell","pm":["gluteus_maximus","hamstrings"],"sm":["erector_spinae"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis).","ins":["Stand holding a barbell at hip level with an overhand grip.","Hinge at the hips, pushing them back while keeping legs nearly straight.","Lower the bar along your legs until you feel a hamstring stretch.","Drive your hips forward to return to standing.","Repeat."],"met":6.0},{"id":"rope-climb","n":"Grimper de corde","en":"Rope Climb","c":"strength","eq":"climbing_rope","pm":["latissimus_dorsi"],"sm":["biceps_brachii","forearm_flexors","rectus_abdominis"],"d":"advanced","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire de tirage — corde à grimper. Travaille surtout : Grand dorsal. En soutien : Biceps, Fléchisseurs de l'avant-bras, Grand droit (abdominaux).","ins":["Grip the rope as high as you can with both hands.","Either wrap the rope around one foot (S-hook or J-hook) or pinch it between both feet.","Pull yourself up while the feet squeeze to support body weight and release rope.","Reach higher with one hand, then the other, and re-clamp with the feet.","Repeat until you reach the top of the rope.","Descend hand-under-hand with the feet controlling the speed — never slide."],"met":6.0},{"id":"rowing-machine","n":"Rameur","en":"Rowing Machine","c":"cardio","eq":"rower","pm":["latissimus_dorsi","quadriceps"],"sm":["biceps_brachii","erector_spinae","gluteus_maximus","hamstrings","rhomboids","trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice cardio — rameur. Travaille surtout : Grand dorsal, Quadriceps. En soutien : Biceps, Lombaires (érecteurs du rachis), Grand fessier, Ischio-jambiers, Rhomboïdes, Trapèzes.","ins":["Sit on the rower, strap your feet into the footplates and take the handle with an overhand grip.","Slide forward into the catch: shins vertical, torso leaning slightly ahead of the hips, arms straight out toward the flywheel.","Drive through your legs first, pushing the seat back until your knees are almost straight.","Swing your torso back past vertical, then pull the handle in to your lower ribs with your elbows travelling past your sides.","Reverse the order on the recovery — arms away, torso forward, then bend the knees — and slide back to the catch for the next stroke.","Continue for the desired time, distance or number of strokes."],"met":8.0},{"id":"running","n":"Course à pied","en":"Running","c":"cardio","eq":"","pm":["gastrocnemius","quadriceps"],"sm":["gluteus_maximus","hamstrings","hip_flexors","soleus"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Exercice cardio, au poids du corps. Travaille surtout : Mollets (gastrocnémiens), Quadriceps. En soutien : Grand fessier, Ischio-jambiers, Fléchisseurs de hanche, Soléaire.","ins":["Start from an easy jog and build into your pace over the first few minutes rather than setting off at target speed.","Land with your foot under your hips, not out in front, and keep the contact with the ground short and quiet.","Run tall through the hips with a slight forward lean from the ankles, not a fold at the waist.","Bend your elbows to about ninety degrees and drive your arms forward and back, keeping them off your chest.","Breathe rhythmically and keep your shoulders, jaw and hands loose.","Hold the pace for the desired time or distance, then jog and walk for a few minutes to finish."],"met":8.0},{"id":"russian-twist","n":"Rotation russe","en":"Russian Twist","c":"strength","eq":"","pm":["obliques","rectus_abdominis"],"sm":["hip_flexors"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage, au poids du corps. Travaille surtout : Obliques, Grand droit (abdominaux). En soutien : Fléchisseurs de hanche.","ins":["Sit on the floor with knees bent, lean back slightly.","Hold your hands together or hold a weight at chest level.","Rotate your torso to one side, then the other.","Keep your core braced throughout.","Repeat."],"met":3.5},{"id":"savasana","n":"Posture du cadavre","en":"Corpse Pose","c":"stretching","eq":"","pm":["erector_spinae"],"sm":[],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis).","ins":["Lie on your back with the legs a comfortable distance apart and the feet falling open.","Rest the arms slightly away from the body with the palms facing up.","Let the whole body soften into the floor, including the jaw, the eyes and the hands.","Stay for the prescribed time, breathing naturally without controlling the breath.","Bend the knees and roll to one side before sitting up slowly."],"met":1.3},{"id":"scapular-pull-ups","n":"Tractions scapulaires","en":"Scapular Pull Ups","c":"strength","eq":"pull_up_bar","pm":["latissimus_dorsi","trapezius"],"sm":["forearm_flexors","rhomboids"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre de traction. Travaille surtout : Grand dorsal, Trapèzes. En soutien : Fléchisseurs de l'avant-bras, Rhomboïdes.","ins":["Hang from a pull-up bar with arms fully extended.","Keep your arms straight throughout the movement.","Depress and retract your shoulder blades to lift your chest.","Pause briefly at the top of the movement.","Return to a fully hanging position.","Repeat for the desired number of reps."],"met":6.0},{"id":"scissor-kicks","n":"Ciseaux","en":"Scissor Kicks","c":"strength","eq":"","pm":["hip_flexors","rectus_abdominis"],"sm":["obliques","transverse_abdominis"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Obliques, Transverse.","ins":["Lie flat on your back with your hands under your glutes.","Lift both legs a few inches off the floor.","Alternate crossing one leg over the other in a scissor motion.","Keep your lower back pressed into the floor.","Maintain a steady rhythm throughout.","Repeat for the desired number of reps."],"met":5.0},{"id":"seated-barbell-overhead-press","n":"Développé militaire assis à la barre","en":"Seated Barbell Overhead Press","c":"strength","eq":"barbell","pm":["anterior_deltoid"],"sm":["lateral_deltoid","trapezius","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Deltoïde antérieur. En soutien : Deltoïde latéral, Trapèzes, Triceps.","ins":["Set an upright bench inside a rack with the pins at about shoulder height when seated.","Sit with your back flat against the pad and unrack the barbell at the front of the shoulders.","Press the bar overhead until the arms are fully extended, tucking the head through at the top.","Lower the bar back to the collarbones under control.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"seated-cable-row","n":"Rowing assis à la poulie","en":"Seated Cable Row","c":"strength","eq":"cable","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","erector_spinae","posterior_deltoid"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — poulie. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Lombaires (érecteurs du rachis), Deltoïde postérieur.","ins":["Sit at the cable row station and place your feet on the footrests.","Grip the handle and sit upright with a slight forward lean.","Drive your elbows back and pull the handle toward your lower abdomen.","Squeeze your shoulder blades together at the end of the pull.","Extend your arms under control back to the starting position.","Repeat for the desired number of reps."],"met":6.0},{"id":"seated-calf-raise","n":"Mollets assis","en":"Seated Calf Raise","c":"strength","eq":"seated_calf_raise_machine","pm":["soleus"],"sm":["gastrocnemius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — machine mollets assis. Travaille surtout : Soléaire. En soutien : Mollets (gastrocnémiens).","ins":["Sit at a calf raise machine with the pads resting on your thighs.","Lower your heels as far as possible.","Raise up onto your toes.","Lower under control.","Repeat."],"met":5.0},{"id":"seated-db-press","n":"Développé épaules assis aux haltères","en":"Seated Dumbbell Shoulder Press","c":"strength","eq":"dumbbell","pm":["anterior_deltoid","lateral_deltoid"],"sm":["trapezius","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Trapèzes, Triceps.","ins":["Sit on a bench with back support, holding dumbbells at shoulder height.","Press the dumbbells overhead until arms are fully extended.","Lower the dumbbells back to shoulder level.","Repeat."],"met":6.0},{"id":"seated-dumbbell-curl","n":"Curl assis aux haltères","en":"Seated Dumbbell Curl","c":"strength","eq":"dumbbell","pm":["biceps_brachii"],"sm":["brachialis","brachioradialis"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Biceps. En soutien : Brachial, Brachio-radial.","ins":["Sit on a bench with a dumbbell in each hand.","Let your arms hang at your sides with palms facing forward.","Curl both dumbbells toward your shoulders by flexing your biceps.","Squeeze at the top of the movement.","Lower the dumbbells with control.","Repeat for the desired number of reps."],"met":5.0},{"id":"seated-dumbbell-lateral-raise","n":"Élévation latérale assis aux haltères","en":"Seated Dumbbell Lateral Raise","c":"strength","eq":"dumbbell","pm":["lateral_deltoid"],"sm":["anterior_deltoid","trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Deltoïde latéral. En soutien : Deltoïde antérieur, Trapèzes.","ins":["Sit on a bench with a dumbbell in each hand at your sides.","Keep your back upright and core braced.","Raise both dumbbells out to the sides until they reach shoulder height.","Keep a slight bend in your elbows.","Lower the dumbbells with control.","Repeat for the desired number of reps."],"met":5.0},{"id":"seated-dumbbell-tricep-extension","n":"Extension triceps assis à l'haltère","en":"Seated Dumbbell Tricep Extension","c":"strength","eq":"dumbbell","pm":["triceps_brachii"],"sm":["anterior_deltoid"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Triceps. En soutien : Deltoïde antérieur.","ins":["Sit on a bench with a dumbbell held overhead in both hands.","Keep your upper arms vertical next to your ears.","Lower the dumbbell behind your head by bending your elbows.","Extend your arms to press the dumbbell back overhead.","Squeeze your triceps at the top.","Repeat for the desired number of reps."],"met":5.0},{"id":"seated-forward-fold","n":"Flexion avant assise","en":"Seated Forward Fold","c":"stretching","eq":"","pm":["hamstrings"],"sm":["erector_spinae"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis).","ins":["Sit on the floor with both legs straight out in front.","Keep your back long and hinge forward from the hips.","Reach your hands toward your feet.","Hold for 20 to 30 seconds, breathing steadily."],"met":5.0},{"id":"seated-leg-curl","n":"Leg curl assis","en":"Seated Leg Curl","c":"strength","eq":"leg_curl","pm":["hamstrings"],"sm":["gastrocnemius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — machine leg curl. Travaille surtout : Ischio-jambiers. En soutien : Mollets (gastrocnémiens).","ins":["Adjust the seat back and ankle pad so your knees align with the machine's pivot point.","Sit upright, place the backs of your ankles on top of the pad, and grip the handles.","Curl your lower legs down and back under the seat as far as the machine allows.","Pause at peak contraction, then return the weight slowly to the starting position.","Repeat for the desired reps."],"met":5.0},{"id":"seated-smith-machine-shoulder-press","n":"Développé épaules assis à la Smith machine","en":"Seated Smith Machine Shoulder Press","c":"strength","eq":"smith_machine","pm":["anterior_deltoid","lateral_deltoid"],"sm":["trapezius","triceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — smith machine. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Trapèzes, Triceps.","ins":["Position a bench inside a Smith machine.","Sit facing forward with the bar at shoulder height.","Grip the bar slightly wider than shoulder-width.","Unrack and press the bar straight up until your arms are extended.","Lower the bar back to shoulder height with control.","Repeat for the desired number of reps."],"met":6.0},{"id":"seated-spinal-twist","n":"Torsion vertébrale assise","en":"Seated Spinal Twist","c":"stretching","eq":"","pm":["erector_spinae","obliques"],"sm":["gluteus_maximus"],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Obliques. En soutien : Grand fessier. Se fait d'un côté puis de l'autre.","ins":["Sit with one leg straight and cross the other foot over it.","Brace the opposite elbow against the outside of the bent knee.","Rotate your torso toward the bent knee and look over your shoulder.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"seated-straddle-stretch","n":"Étirement assis jambes écartées","en":"Seated Straddle Stretch","c":"stretching","eq":"","pm":["adductors","hamstrings"],"sm":["erector_spinae"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Adducteurs, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis).","ins":["Sit with your legs straight and spread wide in a V.","Keep your back long and hinge forward from the hips.","Walk your hands forward along the floor.","Hold for 20 to 30 seconds, breathing steadily."],"met":5.0},{"id":"shrug","n":"Haussements d'épaules à la barre","en":"Barbell Shrug","c":"strength","eq":"barbell","pm":["trapezius"],"sm":["rhomboids"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — barre. Travaille surtout : Trapèzes. En soutien : Rhomboïdes.","ins":["Stand holding a barbell at arm's length with an overhand grip.","Shrug your shoulders straight up toward your ears.","Hold briefly at the top.","Lower your shoulders back down with control.","Repeat."],"met":5.0},{"id":"side-lunge","n":"Fente latérale","en":"Side Lunge","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["gluteus_medius","hamstrings","hip_flexors"],"d":"intermediate","bw":true,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Moyen fessier, Ischio-jambiers, Fléchisseurs de hanche. Se fait d'un côté puis de l'autre.","ins":["Stand with feet hip-width apart and hands at your chest.","Step one leg wide to the side, keeping the other leg straight.","Bend the stepping knee and push your hips back into a lateral squat.","Keep your chest up and the working heel planted.","Drive through the bent leg to return to standing.","Complete reps on one side, then switch."],"met":5.0},{"id":"side-lying-hip-abduction","n":"Abduction de hanche allongé sur le côté","en":"Side-Lying Hip Abduction","c":"strength","eq":"","pm":["abductors","gluteus_medius"],"sm":[],"d":"beginner","bw":true,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée, au poids du corps. Travaille surtout : Abducteurs, Moyen fessier. Se fait d'un côté puis de l'autre.","ins":["Lie on your side with legs stacked.","Keep the bottom leg slightly bent.","Raise the top leg toward the ceiling.","Lower under control.","Repeat on both sides."],"met":3.5},{"id":"side-lying-hip-abduction-hold","n":"Abduction de hanche allongé sur le côté (statique)","en":"Side-Lying Hip Abduction Hold","c":"strength","eq":"","pm":["abductors","gluteus_medius"],"sm":[],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Exercice de musculation d'isolation statique, au poids du corps. Travaille surtout : Abducteurs, Moyen fessier. Se fait d'un côté puis de l'autre.","ins":["Lie on one side with the legs stacked and straight, and support the head on the lower arm.","Brace the trunk so the torso stays square and does not roll backwards.","Lift the top leg to about 30 to 45 degrees, keeping the toes pointing forward.","Hold the leg there for the prescribed time, breathing normally.","Lower the leg under control and repeat on the other side."],"met":3.5},{"id":"side-lying-hip-adduction","n":"Adduction de hanche allongé sur le côté","en":"Side Lying Hip Adduction","c":"strength","eq":"","pm":["adductors"],"sm":[],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage, au poids du corps. Travaille surtout : Adducteurs.","ins":["Lie on your side with your bottom leg straight.","Bend your top leg and place its foot flat in front of the bottom thigh.","Support your head with your bottom arm.","Lift the bottom leg upward toward the ceiling.","Lower the leg back down under control.","Complete reps on one side, then switch."],"met":3.5},{"id":"side-lying-hip-adduction-hold","n":"Adduction de hanche allongé sur le côté (statique)","en":"Side-Lying Hip Adduction Hold","c":"strength","eq":"","pm":["adductors"],"sm":[],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation d'isolation statique, au poids du corps. Travaille surtout : Adducteurs.","ins":["Lie on one side with the bottom leg straight and the top leg crossed over it, foot flat on the floor.","Support the head on the lower arm and keep the hips stacked vertically.","Lift the bottom leg as high as it will go with the knee straight and the toes pointing forward.","Hold that lifted position for the prescribed time without rolling the hips back.","Lower the leg under control and repeat on the other side."],"met":3.5},{"id":"side-lying-lateral-raise","n":"Élévation latérale allongé sur le côté","en":"Side-Lying Lateral Raise","c":"strength","eq":"dumbbell","pm":["lateral_deltoid"],"sm":["supraspinatus","trapezius"],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Deltoïde latéral. En soutien : Sus-épineux, Trapèzes. Se fait d'un côté puis de l'autre.","ins":["Lie on your side on a flat bench with your bottom arm supporting your head or gripping the bench edge.","Hold a dumbbell in your top hand with your arm resting along your side.","Keeping your elbow slightly bent, raise the dumbbell upward until your arm is perpendicular to the floor.","Pause briefly at the top, then lower the dumbbell slowly back to your side.","Complete all reps on one side before switching."],"met":5.0},{"id":"side-plank","n":"Gainage latéral","en":"Side Plank","c":"strength","eq":"","pm":["obliques","transverse_abdominis"],"sm":["gluteus_medius","rectus_abdominis"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Obliques, Transverse. En soutien : Moyen fessier, Grand droit (abdominaux).","ins":["Lie on your side with your forearm on the floor, elbow under your shoulder.","Lift your hips off the floor, forming a straight line from head to feet.","Hold the position, keeping your core tight.","Breathe steadily.","Repeat on both sides."],"met":3.5},{"id":"side-plank-leg-lift","n":"Gainage latéral avec levée de jambe","en":"Side Plank with Leg Lift","c":"strength","eq":"","pm":["gluteus_medius","obliques"],"sm":["gluteus_maximus","rectus_abdominis","transverse_abdominis"],"d":"intermediate","bw":true,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Moyen fessier, Obliques. En soutien : Grand fessier, Grand droit (abdominaux), Transverse. Se fait d'un côté puis de l'autre.","ins":["Lie on your side with the forearm on the floor, elbow under the shoulder.","Stack the feet and lift the hips into a side plank.","From this stable side plank, raise the top leg straight up toward the ceiling.","Lower the leg back down with control without dropping the hips.","Complete reps on one side, then switch."],"met":5.0},{"id":"side-plank-leg-lift-hold","n":"Gainage latéral jambe levée (statique)","en":"Side Plank Leg Lift Hold","c":"strength","eq":"","pm":["gluteus_medius","obliques"],"sm":["gluteus_maximus","rectus_abdominis","transverse_abdominis"],"d":"intermediate","bw":true,"uni":true,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Moyen fessier, Obliques. En soutien : Grand fessier, Grand droit (abdominaux), Transverse. Se fait d'un côté puis de l'autre.","ins":["Set up in a side plank on the forearm with the elbow under the shoulder and the feet stacked.","Lift the hips until the body forms a straight line from the ankles to the head.","Raise the top leg to roughly hip height, keeping the toes pointing forward.","Hold the position for the prescribed time, keeping the hips high and the shoulder stacked.","Lower the leg and the hips under control and repeat on the other side."],"met":5.0},{"id":"single-arm-chest-supported-dumbbell-row","n":"Rowing un bras buste appuyé à l'haltère","en":"Single-Arm Chest-Supported Dumbbell Row","c":"strength","eq":"dumbbell","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","posterior_deltoid"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — haltères. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Deltoïde postérieur. Se fait d'un côté puis de l'autre.","ins":["Lie face-down on an incline bench holding a dumbbell in one hand, arm hanging straight down.","Row the dumbbell up to your side, driving your elbow past your torso.","Squeeze your shoulder blade at the top, then lower under control.","Complete all reps on one side before switching arms."],"met":6.0},{"id":"single-arm-db-row","n":"Rowing un bras à l'haltère","en":"Single-Arm Dumbbell Row","c":"strength","eq":"dumbbell","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","posterior_deltoid"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — haltères. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Deltoïde postérieur. Se fait d'un côté puis de l'autre.","ins":["Place one knee and hand on a bench for support.","Hold a dumbbell in the other hand with arm extended.","Pull the dumbbell up toward your hip, squeezing your shoulder blade.","Lower the dumbbell with control.","Repeat on both sides."],"met":6.0},{"id":"single-arm-dumbbell-bench-press","n":"Développé couché un bras à l'haltère","en":"Single Arm Dumbbell Bench Press","c":"strength","eq":"dumbbell","pm":["pectoralis_major","triceps_brachii"],"sm":["anterior_deltoid","obliques","serratus_anterior"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — haltères. Travaille surtout : Pectoraux, Triceps. En soutien : Deltoïde antérieur, Obliques, Dentelé antérieur. Se fait d'un côté puis de l'autre.","ins":["Lie back on a flat bench with the feet planted on the floor and a dumbbell held at chest level in one hand.","Rest the free hand on your stomach or hold it out to the side for balance.","Press the dumbbell up over the chest until the arm is straight.","Pause briefly at the top without letting the body roll toward the pressing arm.","Lower the dumbbell slowly to the side of the chest.","Complete the repetitions on one side, then switch arms."],"met":6.0},{"id":"single-arm-dumbbell-overhead-tricep-extension","n":"Extension triceps au-dessus de la tête un bras","en":"Single-Arm Dumbbell Overhead Tricep Extension","c":"strength","eq":"dumbbell","pm":["triceps_brachii"],"sm":["obliques"],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Triceps. En soutien : Obliques. Se fait d'un côté puis de l'autre.","ins":["Stand or sit holding a dumbbell in one hand overhead, arm fully extended.","The palm faces forward; the other hand can hold your waist or an upright for stability.","Bend the elbow to lower the dumbbell behind the head in a controlled arc.","Keep the upper arm vertical and close to the head throughout.","Extend the elbow to return the dumbbell overhead.","Complete all reps on one side, then switch."],"met":5.0},{"id":"single-arm-hammer-curl","n":"Curl marteau un bras","en":"Single-Arm Hammer Curl","c":"strength","eq":"dumbbell","pm":["brachialis","brachioradialis"],"sm":["biceps_brachii","forearm_flexors"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Brachial, Brachio-radial. En soutien : Biceps, Fléchisseurs de l'avant-bras. Se fait d'un côté puis de l'autre.","ins":["Stand with your feet about hip-width apart and hold one dumbbell at your side with the palm facing inward.","Brace your trunk and keep the working upper arm beside your ribs as the arm hangs straight.","Curl the dumbbell toward your shoulder without rotating the palm or swinging the torso.","Squeeze the elbow flexors at the top, then lower the dumbbell under control until the arm is straight.","Complete the repetitions on one side, then switch arms and repeat."],"met":5.0},{"id":"single-arm-machine-shoulder-press","n":"Développé épaules un bras à la machine","en":"Single-Arm Machine Shoulder Press","c":"strength","eq":"shoulder_press_machine","pm":["anterior_deltoid","lateral_deltoid"],"sm":["trapezius","triceps_brachii"],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — machine développé épaules. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Trapèzes, Triceps. Se fait d'un côté puis de l'autre.","ins":["Adjust the seat so the working handle starts around shoulder height and sit with your back firmly against the pad.","Grip one handle with the wrist straight and keep the free hand on the support or resting comfortably.","Press the handle upward without leaning away from the back pad or rotating the torso.","Lower the handle under control until the elbow is just below the starting line, then repeat.","Complete the repetitions on one side, adjust the seat if needed, and train the other side."],"met":6.0},{"id":"single-arm-plate-loaded-lateral-raise","n":"Élévation latérale un bras chargée (machine)","en":"Single-Arm Plate-Loaded Lateral Raise","c":"strength","eq":"plate_loaded_lateral_raise_machine","pm":["lateral_deltoid"],"sm":["anterior_deltoid","trapezius"],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — machine élévations latérales. Travaille surtout : Deltoïde latéral. En soutien : Deltoïde antérieur, Trapèzes. Se fait d'un côté puis de l'autre.","ins":["Set the seat height so the pad pivot lines up with your shoulder, and load only the side you are about to work.","Sit with your back flat against the pad and place the outside of your working upper arm against its pad.","Hold the handle on the free side or rest that hand in your lap, and keep your torso square to the seat.","Push the working arm out and up against the pad until the upper arm is level with your shoulder, then lower it under control.","Complete all the repetitions on that side, then load and work the other side."],"met":5.0},{"id":"single-arm-tricep-pushdown","n":"Extension triceps un bras à la poulie","en":"Single Arm Tricep Pushdown","c":"strength","eq":"cable","pm":["triceps_brachii"],"sm":["forearm_extensors"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — poulie. Travaille surtout : Triceps. En soutien : Extenseurs de l'avant-bras. Se fait d'un côté puis de l'autre.","ins":["Attach a single handle to a high cable pulley.","Grasp the handle with one hand and keep your elbow pinned to your side.","Press the handle down until your arm is fully extended.","Squeeze the triceps at the bottom.","Slowly return to the start position.","Complete reps on one side, then switch."],"met":6.0},{"id":"single-db-svend-press","n":"Svend press à un haltère","en":"Single Dumbbell Svend Press","c":"strength","eq":"dumbbell","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Stand tall and hold a single dumbbell upright in front of your sternum, the handle running vertically between your flat palms.","Squeeze your palms hard into the dumbbell so the chest takes the tension and the weight cannot slip.","Press the dumbbell straight forward until your arms are fully extended, keeping it at chest height the whole way out.","Pause briefly without letting the squeeze go, then draw the dumbbell back to your chest under control.","Repeat for the recommended number of repetitions."],"met":5.0},{"id":"single-leg-calf-raise","n":"Mollets sur une jambe","en":"Single Leg Calf Raise","c":"strength","eq":"","pm":["gastrocnemius"],"sm":["soleus"],"d":"beginner","bw":true,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée, au poids du corps. Travaille surtout : Mollets (gastrocnémiens). En soutien : Soléaire. Se fait d'un côté puis de l'autre.","ins":["Stand on one foot with the ball of the foot on a raised platform, heel free.","Hold a wall or rail for balance with one hand.","Drop the heel below platform level for a deep stretch.","Drive up onto the toes as high as possible.","Lower under control. Complete reps per side, then switch."],"met":3.5},{"id":"single-leg-extension","n":"Leg extension une jambe","en":"Single Leg Extension","c":"strength","eq":"leg_extension","pm":["quadriceps"],"sm":[],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — machine leg extension. Travaille surtout : Quadriceps. Se fait d'un côté puis de l'autre.","ins":["Sit on a leg extension machine and place one foot under the pad.","Rest the other foot on the floor or let it hang.","Extend the working leg until it is nearly straight.","Squeeze the quadriceps at the top.","Lower the leg back down under control.","Complete reps on one side, then switch."],"met":5.0},{"id":"single-leg-glute-bridge","n":"Pont fessier une jambe","en":"Single Leg Glute Bridge","c":"strength","eq":"","pm":["gluteus_maximus"],"sm":["erector_spinae","hamstrings"],"d":"intermediate","bw":true,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Grand fessier. En soutien : Lombaires (érecteurs du rachis), Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Lie on your back with one knee bent, foot flat, the other leg extended straight.","Brace the core and squeeze the glute on the working side.","Drive the hips up by pressing through the working heel.","Pause at the top with the body in a straight line from shoulders to knee.","Lower under control. Complete reps per side, then switch."],"met":5.0},{"id":"single-leg-glute-bridge-hold","n":"Pont fessier une jambe (statique)","en":"Single-Leg Glute Bridge Hold","c":"strength","eq":"","pm":["gluteus_maximus"],"sm":["erector_spinae","hamstrings"],"d":"intermediate","bw":true,"uni":true,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Grand fessier. En soutien : Lombaires (érecteurs du rachis), Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Lie on your back with one knee bent and that foot flat, and lift the other leg so the thigh is roughly vertical.","Push through the heel of the planted foot and lift the hips until the body is straight from the knee to the shoulders.","Level the pelvis so the lifted side does not drop, and tuck the ribs down.","Hold the top position for the prescribed time, keeping the lifted knee still.","Lower the hips under control and repeat on the other side."],"met":5.0},{"id":"single-leg-lying-leg-curl","n":"Leg curl allongé une jambe","en":"Single Leg Lying Leg Curl","c":"strength","eq":"leg_curl","pm":["hamstrings"],"sm":["gastrocnemius"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — machine leg curl. Travaille surtout : Ischio-jambiers. En soutien : Mollets (gastrocnémiens). Se fait d'un côté puis de l'autre.","ins":["Lie face down on a lying leg curl machine.","Position one ankle under the pad, keeping the other foot off the machine.","Curl the working leg by bringing your heel toward your glute.","Squeeze the hamstring at the top.","Lower the leg back down under control.","Complete reps on one side, then switch."],"met":5.0},{"id":"single-leg-press","n":"Presse à cuisses une jambe","en":"Single Leg Press","c":"strength","eq":"leg_press","pm":["gluteus_maximus","quadriceps"],"sm":["hamstrings"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — presse à cuisses. Travaille surtout : Grand fessier, Quadriceps. En soutien : Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Sit in a leg press machine with one foot placed on the platform.","Keep the other leg off the platform, resting to the side.","Release the safeties and lower the platform by bending your knee.","Stop when your knee is near a 90-degree angle.","Drive through the heel to press the platform back up.","Complete reps on one side, then switch."],"met":6.0},{"id":"single-leg-rdl-hold","n":"Soulevé de terre roumain une jambe (statique)","en":"Single Leg RDL Hold","c":"strength","eq":"","pm":["gluteus_maximus","hamstrings"],"sm":["adductors","erector_spinae","gluteus_medius","obliques"],"d":"intermediate","bw":true,"uni":true,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Adducteurs, Lombaires (érecteurs du rachis), Moyen fessier, Obliques. Se fait d'un côté puis de l'autre.","ins":["Stand on one leg with a slight bend in the knee and the arms hanging in front of you.","Hinge at the hip, sending the free leg straight back as the torso tips forward.","Keep the back flat and the hips square to the floor.","Stop when the torso and the free leg are roughly parallel to the floor and hold the position.","Return to standing under control, then switch legs."],"met":5.0},{"id":"single-leg-romanian-deadlift","n":"Soulevé de terre roumain une jambe","en":"Single Leg Romanian Deadlift","c":"strength","eq":"dumbbell","pm":["gluteus_maximus","hamstrings"],"sm":["erector_spinae","gluteus_medius"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — haltères. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis), Moyen fessier. Se fait d'un côté puis de l'autre.","ins":["Stand on one leg holding a dumbbell in each hand in front of your thighs.","Keep a slight bend in the standing knee.","Hinge at the hip while extending the free leg behind you.","Lower the dumbbells along your standing leg until you feel a hamstring stretch.","Drive through the heel to return to upright.","Complete reps on one side, then switch."],"met":6.0},{"id":"sit-ups","n":"Relevés de buste","en":"Sit-Ups","c":"strength","eq":"","pm":["hip_flexors","rectus_abdominis"],"sm":["obliques"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage, au poids du corps. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Obliques.","ins":["Lie on your back with knees bent and feet anchored.","Cross your arms over your chest or place hands behind your head.","Sit all the way up until your torso is upright.","Lower back down with control.","Repeat."],"met":5.0},{"id":"six-inch-hold","n":"Jambes à 15 cm du sol (statique)","en":"Six Inch Hold","c":"strength","eq":"","pm":["hip_flexors","rectus_abdominis"],"sm":["obliques","quadriceps","transverse_abdominis"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Obliques, Quadriceps, Transverse.","ins":["Lie on your back with the legs straight and the arms resting along your sides.","Press the lower back into the floor and brace the abdominals.","Lift the head, shoulders and straight legs about six inches off the floor.","Hold the position while breathing steadily.","Lower slowly to rest."],"met":5.0},{"id":"ski-erg","n":"SkiErg","en":"SkiErg","c":"cardio","eq":"ski_erg","pm":["latissimus_dorsi","rectus_abdominis","triceps_brachii"],"sm":["gluteus_maximus","hamstrings","quadriceps"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice cardio — skiErg. Travaille surtout : Grand dorsal, Grand droit (abdominaux), Triceps. En soutien : Grand fessier, Ischio-jambiers, Quadriceps.","ins":["Stand facing the SkiErg with the handles overhead and the feet about hip-width apart.","Brace the trunk and drive the handles down by pulling with the lats while hinging slightly at the hips.","Finish with the hands beside the thighs and the knees softly bent.","Let the cords retract as you return the arms overhead and stand tall.","Repeat smoothly while keeping the heels planted and the torso controlled."],"met":8.0},{"id":"skull-crusher","n":"Barre au front","en":"Skull Crusher","c":"strength","eq":"barbell","pm":["triceps_brachii"],"sm":[],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — barre. Travaille surtout : Triceps.","ins":["Lie on a flat bench holding a barbell over your chest with a narrow grip.","Lower the bar toward your forehead by bending at the elbows.","Extend your arms back to the start.","Repeat."],"met":5.0},{"id":"sled-row","n":"Rowing au traîneau","en":"Sled Row","c":"strength","eq":"sled","pm":["latissimus_dorsi"],"sm":["biceps_brachii","gluteus_maximus","posterior_deltoid","rhomboids","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — traîneau. Travaille surtout : Grand dorsal. En soutien : Biceps, Grand fessier, Deltoïde postérieur, Rhomboïdes, Trapèzes.","ins":["Load a sled and grip its uprights with both hands, one to each post.","Stand facing the sled with the arms extended and the torso leaned back slightly against the load.","Pull the sled toward you by driving the elbows back, and take a short step backwards as you do.","Extend the arms again, step back once more, and repeat the pull.","Continue for distance or time, keeping a steady pull-and-step rhythm."],"met":6.0},{"id":"smith-machine-bench-press","n":"Développé couché à la Smith machine","en":"Smith Machine Bench Press","c":"strength","eq":"smith_machine","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — smith machine. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Lie on a flat bench set inside a Smith machine.","Grip the bar slightly wider than shoulder-width and unrack it.","Lower the bar under control to your mid-chest.","Pause briefly without bouncing.","Press the bar back up until your arms are fully extended.","Repeat for the desired number of reps."],"met":6.0},{"id":"smith-machine-bent-over-row","n":"Rowing buste penché à la Smith machine","en":"Smith Machine Bent Over Row","c":"strength","eq":"smith_machine","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","erector_spinae","trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — smith machine. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Lombaires (érecteurs du rachis), Trapèzes.","ins":["Stand inside a Smith machine with feet shoulder-width apart.","Grip the bar with an overhand grip slightly wider than shoulders.","Hinge at the hips until your torso is roughly 45 degrees.","Pull the bar toward your lower chest by driving your elbows back.","Squeeze your shoulder blades at the top.","Lower the bar under control and repeat."],"met":6.0},{"id":"smith-machine-bulgarian-split","n":"Squat bulgare à la Smith machine","en":"Smith Machine Bulgarian Split Squat","c":"strength","eq":"smith_machine","pm":["gluteus_maximus","quadriceps"],"sm":["hamstrings"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — smith machine. Travaille surtout : Grand fessier, Quadriceps. En soutien : Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Set up a bench behind the Smith machine. Rest the bar on your traps.","Place the rear foot on the bench and front foot forward.","Lower your back knee toward the floor.","Push through the front heel to return.","Repeat on both sides."],"met":6.0},{"id":"smith-machine-calf-raise","n":"Mollets à la Smith machine","en":"Smith Machine Calf Raise","c":"strength","eq":"smith_machine","pm":["gastrocnemius"],"sm":["soleus"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — smith machine. Travaille surtout : Mollets (gastrocnémiens). En soutien : Soléaire.","ins":["Place the Smith machine bar across your upper back and shoulders.","Stand on a small platform so your heels can drop below your toes.","Unrack the bar and raise up onto the balls of your feet.","Squeeze your calves hard at the top.","Lower your heels below the platform for a full stretch.","Repeat for the desired number of reps."],"met":5.0},{"id":"smith-machine-decline-bench-press","n":"Développé décliné à la Smith machine","en":"Smith Machine Decline Bench Press","c":"strength","eq":"smith_machine","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — smith machine. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Set a decline bench in the machine so the bar lines up with your lower chest when you lie down, and hook your legs under the pads.","Lie back with your head at the low end, take an overhand grip slightly wider than your shoulders and unrack the bar.","Lower the bar under control until it touches your lower chest, keeping your elbows at roughly forty-five degrees from your torso.","Press the bar back up until your arms are extended, without locking the elbows out hard.","Repeat for the desired number of repetitions, then rack the bar before releasing your legs."],"met":6.0},{"id":"smith-machine-front-squat","n":"Squat avant à la Smith machine","en":"Smith Machine Front Squat","c":"strength","eq":"smith_machine","pm":["gluteus_maximus","quadriceps"],"sm":["erector_spinae","gluteus_medius","hamstrings"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — smith machine. Travaille surtout : Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Moyen fessier, Ischio-jambiers.","ins":["Set the bar at upper-chest height and step under it so it rests across the front of your shoulders, against your collarbones.","Cross your arms over the bar or take an open front-rack grip, and drive your elbows up until your upper arms are close to parallel with the floor.","Unrack the bar and stand with your feet about shoulder-width apart and slightly forward of it.","Sit straight down, keeping your elbows high and your torso upright, until your thighs are at least parallel to the floor.","Drive through the middle of your feet to stand back up, and repeat for the desired number of repetitions."],"met":6.0},{"id":"smith-machine-good-morning","n":"Good morning à la Smith machine","en":"Smith Machine Good Morning","c":"strength","eq":"smith_machine","pm":["erector_spinae","hamstrings"],"sm":["gluteus_maximus"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — smith machine. Travaille surtout : Lombaires (érecteurs du rachis), Ischio-jambiers. En soutien : Grand fessier.","ins":["Set the bar at upper-back height, step under it and settle it across your traps, then unrack it with your feet about hip-width apart.","Soften your knees slightly and keep them there -- this is a hinge, not a squat.","Push your hips straight back and let your torso tip forward, keeping your back flat and your head in line with your spine.","Stop when you feel a strong stretch in your hamstrings, with your torso somewhere near parallel to the floor.","Drive your hips forward to stand back up, squeezing the glutes at the top, and repeat for the desired reps."],"met":6.0},{"id":"smith-machine-hip-thrust","n":"Hip thrust à la Smith machine","en":"Smith Machine Hip Thrust","c":"strength","eq":"smith_machine","pm":["gluteus_maximus","gluteus_medius"],"sm":["hamstrings"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — smith machine. Travaille surtout : Grand fessier, Moyen fessier. En soutien : Ischio-jambiers.","ins":["Set a flat bench inside the Smith machine, parallel to the bar and positioned so the bar will sit over your hip crease.","Set the bar low enough that you can get under it while seated on the floor, then sit with your upper back against the bench.","Roll the bar over your hips, pad it if you need to, and unhook it with your feet flat and about hip-width apart.","Drive through your heels and extend your hips until your thighs and torso form a straight line, squeezing the glutes at the top.","Lower your hips under control until they are just off the floor, and repeat for the desired number of repetitions."],"met":6.0},{"id":"smith-machine-incline-bench-press","n":"Développé incliné à la Smith machine","en":"Smith Machine Incline Bench Press","c":"strength","eq":"smith_machine","pm":["anterior_deltoid","pectoralis_major"],"sm":["triceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — smith machine. Travaille surtout : Deltoïde antérieur, Pectoraux. En soutien : Triceps.","ins":["Set an incline bench at 30-45 degrees inside a Smith machine.","Lie back and grip the bar slightly wider than shoulder-width.","Unrack and lower the bar to your upper chest.","Pause briefly at the bottom.","Press the bar back up until your arms are extended.","Repeat for the desired number of reps."],"met":6.0},{"id":"smith-machine-rdl","n":"Soulevé de terre roumain à la Smith machine","en":"Smith Machine Romanian Deadlift","c":"strength","eq":"smith_machine","pm":["hamstrings"],"sm":["erector_spinae","gluteus_maximus","trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — smith machine. Travaille surtout : Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis), Grand fessier, Trapèzes.","ins":["Set the Smith machine bar at mid-thigh height and stand directly underneath with feet hip-width.","Unrack the bar with an overhand grip just outside the hips.","Push the hips back while letting the bar slide down the front of the legs.","Go until you feel a deep hamstring stretch, with a flat back and a soft knee bend.","Drive the hips forward to return to standing, keeping the bar close to the body.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"smith-machine-reverse-grip-bent-over-row","n":"Rowing prise inversée à la Smith machine","en":"Smith Machine Reverse Grip Bent Over Row","c":"strength","eq":"smith_machine","pm":["biceps_brachii","latissimus_dorsi"],"sm":["erector_spinae","rhomboids","trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — smith machine. Travaille surtout : Biceps, Grand dorsal. En soutien : Lombaires (érecteurs du rachis), Rhomboïdes, Trapèzes.","ins":["Stand inside a Smith machine and grip the bar with an underhand grip.","Hinge forward at the hips until your torso is about 45 degrees.","Keep your back flat and core braced.","Pull the bar toward your lower abdomen.","Squeeze your lats and shoulder blades at the top.","Lower the bar under control and repeat."],"met":6.0},{"id":"smith-machine-reverse-lunge","n":"Fente arrière à la Smith machine","en":"Smith Machine Reverse Lunge","c":"strength","eq":"smith_machine","pm":["gluteus_maximus","quadriceps"],"sm":["gluteus_medius","hamstrings"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — smith machine. Travaille surtout : Grand fessier, Quadriceps. En soutien : Moyen fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Set the bar so it sits across your upper traps when you stand, then unrack it with your feet under your hips.","Step one foot straight back and lower the rear knee toward the floor, keeping the front shin vertical and most of your weight on the front foot.","Stop when the rear knee is just short of the floor and the front thigh is roughly parallel to it.","Push through the front heel and bring the rear foot back to standing under the bar.","Complete all the repetitions on one side, or alternate legs, then switch."],"met":6.0},{"id":"smith-machine-shoulder-press","n":"Développé épaules à la Smith machine","en":"Smith Machine Shoulder Press","c":"strength","eq":"smith_machine","pm":["anterior_deltoid","lateral_deltoid"],"sm":["trapezius","triceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — smith machine. Travaille surtout : Deltoïde antérieur, Deltoïde latéral. En soutien : Trapèzes, Triceps.","ins":["Sit on a bench positioned inside a Smith machine.","Grip the bar slightly wider than shoulder-width at shoulder level.","Unrack the bar and press it overhead until your arms are extended.","Lower the bar back to shoulder level under control.","Keep your core tight throughout.","Repeat for the desired number of reps."],"met":6.0},{"id":"smith-machine-shrug","n":"Haussements d'épaules à la Smith machine","en":"Smith Machine Shrug","c":"strength","eq":"smith_machine","pm":["trapezius"],"sm":["forearm_flexors"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — smith machine. Travaille surtout : Trapèzes. En soutien : Fléchisseurs de l'avant-bras.","ins":["Stand upright inside a Smith machine with the bar at thigh height.","Grip the bar slightly wider than shoulder-width with an overhand grip.","Unrack the bar and let it hang in front of your thighs.","Shrug your shoulders straight up toward your ears.","Hold the top for a moment, then lower slowly.","Repeat for the desired number of reps."],"met":5.0},{"id":"smith-machine-split-squat","n":"Fente statique à la Smith machine","en":"Smith Machine Split Squat","c":"strength","eq":"smith_machine","pm":["gluteus_maximus","quadriceps"],"sm":["hamstrings"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — smith machine. Travaille surtout : Grand fessier, Quadriceps. En soutien : Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Set the bar low enough that it will still clear your shoulders at the bottom of the rep, then step under it and rest it across your upper traps.","Unrack the bar and take a long stride forward with one foot, leaving the rear foot planted on the floor with the heel lifted.","Check that your front shin will stay roughly vertical when you descend; adjust the stride length before you start loading it.","Lower straight down by bending both knees until the rear knee is just above the floor and the front thigh is close to parallel.","Drive through the front heel to return to the start, keeping both feet in place, and repeat for the desired reps before switching sides."],"met":6.0},{"id":"smith-machine-squat","n":"Squat à la Smith machine","en":"Smith Machine Squat","c":"strength","eq":"smith_machine","pm":["gluteus_maximus","quadriceps"],"sm":["erector_spinae","gluteus_medius","hamstrings"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — smith machine. Travaille surtout : Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Moyen fessier, Ischio-jambiers.","ins":["Set the Smith machine bar at shoulder height and step under it.","Position the bar across your upper traps and unrack it.","Stand with feet shoulder-width apart, slightly forward of the bar.","Descend until your thighs are parallel to the floor.","Drive through your heels to return to standing.","Repeat for the desired number of reps."],"met":6.0},{"id":"smith-machine-upright-row","n":"Rowing menton à la Smith machine","en":"Smith Machine Upright Row","c":"strength","eq":"smith_machine","pm":["lateral_deltoid","trapezius"],"sm":["anterior_deltoid","biceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — smith machine. Travaille surtout : Deltoïde latéral, Trapèzes. En soutien : Deltoïde antérieur, Biceps.","ins":["Set the bar at hip height, take an overhand grip a little wider than shoulder-width and stand close to it with your arms straight.","Unrack the bar and stand tall with your shoulders back and your core braced.","Pull the bar straight up the front of your body, leading with your elbows and keeping the bar close.","Stop when the bar reaches your lower chest and your elbows are level with your shoulders, then pause briefly.","Lower the bar under control until your arms are straight again, and repeat for the desired reps."],"met":6.0},{"id":"snatch","n":"Arraché (snatch)","en":"Snatch","c":"olympic","eq":"barbell","pm":["gluteus_maximus","quadriceps","trapezius"],"sm":["erector_spinae","hamstrings","lateral_deltoid"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Mouvement d'haltérophilie — barre. Travaille surtout : Grand fessier, Quadriceps, Trapèzes. En soutien : Lombaires (érecteurs du rachis), Ischio-jambiers, Deltoïde latéral.","ins":["Stand with feet hip-width apart and grip the bar wide.","Hinge down, keeping your back flat and chest up.","Explosively extend hips, knees, and ankles to drive the bar up.","Pull yourself under the bar into an overhead squat.","Stand up with the bar locked out overhead.","Return the bar to the floor and repeat."],"met":8.0},{"id":"sphinx-pose","n":"Posture du sphinx","en":"Sphinx Pose","c":"stretching","eq":"","pm":["erector_spinae"],"sm":["hip_flexors","pectoralis_major"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis). En soutien : Fléchisseurs de hanche, Pectoraux.","ins":["Lie face down and place the forearms on the floor with the elbows directly under the shoulders.","Press the forearms and the tops of the feet down and lift the chest.","Draw the shoulders away from the ears and lengthen the back of the neck.","Hold the position for the prescribed time, breathing into the front of the chest.","Lower the chest to the floor and rest."],"met":5.0},{"id":"spider-curl","n":"Curl araignée","en":"Spider Curl","c":"strength","eq":"dumbbell","pm":["biceps_brachii"],"sm":["brachialis"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Biceps. En soutien : Brachial.","ins":["Lie face down on an incline bench with arms hanging straight down.","Hold a dumbbell in each hand with an underhand grip.","Keep your upper arms vertical as you curl the weights up.","Squeeze the biceps hard at the top.","Lower the dumbbells under control to full extension.","Repeat for the desired number of reps."],"met":5.0},{"id":"spiderman-push-up","n":"Pompes Spiderman","en":"Spiderman Push-Up","c":"strength","eq":"","pm":["pectoralis_major","triceps_brachii"],"sm":["anterior_deltoid","hip_flexors","obliques","rectus_abdominis","serratus_anterior"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Pectoraux, Triceps. En soutien : Deltoïde antérieur, Fléchisseurs de hanche, Obliques, Grand droit (abdominaux), Dentelé antérieur.","ins":["Start in a high plank with the hands slightly wider than the shoulders and the body in a straight line.","Begin to lower the chest toward the floor and at the same time lift one foot off the floor.","Draw that knee out and up toward the elbow on the same side, keeping the hips low.","Press back up to the plank while returning the leg to the starting position.","Repeat on the other side and keep alternating."],"met":5.0},{"id":"split-jerk","n":"Jeté fendu","en":"Split Jerk","c":"olympic","eq":"barbell","pm":["anterior_deltoid","quadriceps"],"sm":["gluteus_maximus","trapezius","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Mouvement d'haltérophilie — barre. Travaille surtout : Deltoïde antérieur, Quadriceps. En soutien : Grand fessier, Trapèzes, Triceps.","ins":["Hold the barbell across your front rack with elbows high.","Dip straight down by bending your knees slightly.","Explosively drive the bar overhead with your legs and arms.","Split your feet forward and back as the bar locks out.","Stand up by bringing your feet back together under the bar.","Lower the bar and repeat."],"met":8.0},{"id":"split-squat","n":"Fente statique","en":"Split Squat","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["gluteus_medius","hamstrings"],"d":"intermediate","bw":true,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Moyen fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Stand in a split stance with one foot forward and one back.","Keep your torso upright and core braced.","Lower your hips straight down by bending both knees.","Stop when the back knee is just above the floor.","Drive through the front heel to return to the start.","Complete reps on one side, then switch."],"met":6.0},{"id":"spoto-press","n":"Spoto press","en":"Spoto Press","c":"strength","eq":"barbell","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Lie on a flat bench and grip the barbell slightly wider than shoulders.","Unrack the bar and hold it over your chest with arms extended.","Lower the bar until it is one inch above your chest.","Pause there for a full second without touching the chest.","Press the bar back up until your arms are extended.","Repeat for the desired number of reps."],"met":6.0},{"id":"squat","n":"Squat arrière à la barre","en":"Barbell Back Squat","c":"strength","eq":"barbell","pm":["gluteus_maximus","quadriceps"],"sm":["erector_spinae","hamstrings"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Ischio-jambiers.","ins":["Position the bar on your upper traps.","Unrack and step back, feet shoulder-width apart.","Brace your core and squat down until thighs are parallel.","Drive through your heels to stand back up.","Repeat."],"met":6.0},{"id":"squat-hold","n":"Squat statique","en":"Squat Hold","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["adductors","erector_spinae","gluteus_medius","hamstrings"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Adducteurs, Lombaires (érecteurs du rachis), Moyen fessier, Ischio-jambiers.","ins":["Stand with the feet shoulder-width apart and the toes turned slightly out.","Reach the arms straight forward to counterbalance.","Squat down until the thighs are parallel to the floor, keeping the chest up and the heels down.","Hold the position, keeping the knees in line with the toes.","Stand up to finish."],"met":5.0},{"id":"squat-pulse","n":"Pulsations en squat","en":"Squat Pulse","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["adductors","erector_spinae","hamstrings"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Adducteurs, Lombaires (érecteurs du rachis), Ischio-jambiers.","ins":["Stand with the feet about shoulder-width apart and the toes turned slightly out, arms reaching forward for balance.","Squat down until the thighs are at least parallel to the floor, keeping the chest up and the heels down.","From the bottom, rise only a short way, a few inches, then sink back down.","Keep pulsing in the lower range without locking out or resting at the top.","Stand up fully when the set is finished."],"met":5.0},{"id":"stability-ball-hip-bridge","n":"Pont de hanches sur ballon","en":"Stability Ball Hip Bridge","c":"strength","eq":"stability_ball","pm":["gluteus_maximus"],"sm":["hamstrings","rectus_abdominis"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — ballon de gym. Travaille surtout : Grand fessier. En soutien : Ischio-jambiers, Grand droit (abdominaux).","ins":["Lie face-up on the floor and place both feet on top of a stability ball.","Arms rest at the sides on the floor for balance.","Squeeze the glutes and press the heels into the ball to raise the hips.","Finish with a straight line from shoulders to knees.","Lower the hips under control without the ball rolling away.","Repeat for the recommended number of repetitions."],"met":5.0},{"id":"stability-ball-knee-tuck","n":"Genoux rentrés sur ballon","en":"Stability Ball Knee Tuck","c":"strength","eq":"stability_ball","pm":["rectus_abdominis"],"sm":["anterior_deltoid","hip_flexors","obliques","serratus_anterior"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique — ballon de gym. Travaille surtout : Grand droit (abdominaux). En soutien : Deltoïde antérieur, Fléchisseurs de hanche, Obliques, Dentelé antérieur.","ins":["Start in a high plank with both shins or the tops of the feet on top of a stability ball.","Hands are under the shoulders, body in a straight line.","Brace the core and pull the ball toward the chest by tucking the knees in.","Roll it back out by extending the legs fully back to the plank position.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"stability-ball-push-up","n":"Pompes pieds sur ballon","en":"Stability Ball Push-Up","c":"strength","eq":"stability_ball","pm":["pectoralis_major"],"sm":["anterior_deltoid","rectus_abdominis","serratus_anterior","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — ballon de gym. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Grand droit (abdominaux), Dentelé antérieur, Triceps.","ins":["Kneel in front of a stability ball and place your shins or feet on top of it.","Set the hands on the floor under the shoulders in a high-plank position.","Brace the core hard — the ball will want to roll sideways.","Lower the chest to the floor by bending the elbows.","Press back up to the starting position without letting the ball wobble.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"stability-ball-push-up-hands-on-ball","n":"Pompes mains sur ballon","en":"Stability Ball Push-Up (Hands on Ball)","c":"strength","eq":"stability_ball","pm":["pectoralis_major"],"sm":["anterior_deltoid","rectus_abdominis","serratus_anterior","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — ballon de gym. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Grand droit (abdominaux), Dentelé antérieur, Triceps.","ins":["Place both hands on top of a stability ball and walk your feet back into a straight-arm plank, body in a straight line from head to heels.","Brace your core and keep the ball steady beneath your hands.","Bend your elbows to lower your chest toward the ball under control.","Press back up to full arm extension without letting the ball roll.","Repeat for the desired number of reps."],"met":6.0},{"id":"stability-ball-wall-squat","n":"Squat au mur avec ballon","en":"Stability Ball Wall Squat","c":"strength","eq":"stability_ball","pm":["gluteus_maximus","quadriceps"],"sm":["hamstrings"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — ballon de gym. Travaille surtout : Grand fessier, Quadriceps. En soutien : Ischio-jambiers.","ins":["Place a stability ball between your lower back and a wall.","Step the feet forward about a foot, slightly wider than shoulder-width.","Squat down, letting the ball roll up the back as you descend.","Stop when thighs are parallel to the floor.","Drive through the heels to stand back up."],"met":6.0},{"id":"stair-climber","n":"Simulateur d'escaliers","en":"Stair Climber","c":"cardio","eq":"stair_climber","pm":["gluteus_maximus","quadriceps"],"sm":["gastrocnemius","gluteus_medius","hamstrings","soleus"],"d":"beginner","bw":false,"uni":false,"img":["main"],"desc":"Exercice cardio — simulateur d'escaliers. Travaille surtout : Grand fessier, Quadriceps. En soutien : Mollets (gastrocnémiens), Moyen fessier, Ischio-jambiers, Soléaire.","ins":["Step onto the bottom stair with the machine at its slowest setting and take the rails lightly for balance.","Climb one step at a time, placing the whole foot on each stair rather than just the toes.","Stand upright with your chest open and your hips under your shoulders instead of hunching over the console.","Push the step down through the heel of the front foot, letting the glute of that leg do the work.","Set the pace so you can hold your posture, and keep climbing for the desired time or number of floors."],"met":8.0},{"id":"standing-calf-raise","n":"Mollets debout","en":"Standing Calf Raise","c":"strength","eq":"standing_calf_raise_machine","pm":["gastrocnemius"],"sm":["soleus"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — machine mollets debout. Travaille surtout : Mollets (gastrocnémiens). En soutien : Soléaire.","ins":["Stand on the edge of a platform or calf raise machine.","Lower heels below the platform.","Push up onto your toes.","Lower slowly.","Repeat."],"met":5.0},{"id":"standing-calf-stretch","n":"Étirement des mollets debout","en":"Standing Calf Stretch","c":"stretching","eq":"","pm":["gastrocnemius"],"sm":["soleus"],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Mollets (gastrocnémiens). En soutien : Soléaire. Se fait d'un côté puis de l'autre.","ins":["Step one foot back into a staggered stance.","Keep the back leg straight and the heel pressed down.","Bend the front knee and lean your weight forward.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"standing-forward-fold","n":"Flexion avant debout","en":"Standing Forward Fold","c":"stretching","eq":"","pm":["hamstrings"],"sm":["erector_spinae","gastrocnemius"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis), Mollets (gastrocnémiens).","ins":["Stand tall with your feet hip-width apart and legs straight.","Hinge at your hips and fold your torso down toward the floor.","Let your hands and head hang toward your feet.","Hold for 20 to 30 seconds, breathing steadily."],"met":5.0},{"id":"standing-forward-fold-to-half-lift","n":"Flexion avant vers demi-relevé","en":"Standing Forward Fold to Half Lift","c":"stretching","eq":"","pm":["erector_spinae","hamstrings"],"sm":["gluteus_maximus"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Ischio-jambiers. En soutien : Grand fessier.","ins":["Stand with the feet hip-width apart and fold forward from the hips.","Rest the hands on the shins, the floor or blocks.","Slide the hands up the shins and lift the chest until the back is flat and the spine is long.","Fold back down, letting the head and neck release.","Continue alternating between the two for the desired number of repetitions."],"met":5.0},{"id":"standing-quad-stretch","n":"Étirement des quadriceps debout","en":"Standing Quad Stretch","c":"stretching","eq":"","pm":["quadriceps"],"sm":["hip_flexors"],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Quadriceps. En soutien : Fléchisseurs de hanche. Se fait d'un côté puis de l'autre.","ins":["Stand on one leg, holding a wall for balance if needed.","Bend the other knee and grab that ankle behind you.","Pull the heel toward your glute, keeping knees together.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"standing-side-bend","n":"Flexion latérale debout","en":"Standing Side Bend","c":"stretching","eq":"","pm":["obliques"],"sm":["latissimus_dorsi","quadratus_lumborum"],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Obliques. En soutien : Grand dorsal, Carré des lombes. Se fait d'un côté puis de l'autre.","ins":["Stand with feet hip-width and reach both arms overhead.","Clasp your hands and lengthen up tall.","Bend smoothly to one side in a long curve.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"standing-side-bend-flow","n":"Enchaînement de flexions latérales debout","en":"Standing Side Bend Flow","c":"stretching","eq":"","pm":["obliques"],"sm":["latissimus_dorsi","quadratus_lumborum"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Étirement, au poids du corps. Travaille surtout : Obliques. En soutien : Grand dorsal, Carré des lombes.","ins":["Stand with the feet hip-width apart and reach both arms overhead.","Bend the trunk to one side, keeping both feet planted and the hips level.","Return through the centre with the ribs stacked over the pelvis.","Bend to the other side in the same way.","Keep alternating for the desired number of repetitions."],"met":5.0},{"id":"standing-split","n":"Grand écart debout","en":"Standing Split","c":"stretching","eq":"","pm":["gluteus_maximus","hamstrings"],"sm":["erector_spinae","quadriceps"],"d":"advanced","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis), Quadriceps. Se fait d'un côté puis de l'autre.","ins":["From a forward fold, place both hands on the floor or on blocks beside the standing foot.","Shift the weight onto one leg and lift the other leg behind you.","Keep the standing leg straight and the hips as level as the lift allows.","Hold the position for the prescribed time, drawing the chest towards the standing shin.","Lower the lifted foot down and repeat on the other side."],"met":5.0},{"id":"stationary-bike","n":"Vélo d'appartement","en":"Stationary Bike","c":"cardio","eq":"stationary_bike","pm":["quadriceps"],"sm":["gastrocnemius","gluteus_maximus","hamstrings","soleus"],"d":"beginner","bw":false,"uni":false,"img":["main"],"desc":"Exercice cardio — vélo d'appartement. Travaille surtout : Quadriceps. En soutien : Mollets (gastrocnémiens), Grand fessier, Ischio-jambiers, Soléaire.","ins":["Set the saddle height so your knee stays slightly bent at the bottom of the pedal stroke, then sit down and place the balls of your feet on the pedals.","Take the handlebars with a relaxed grip and sit tall, with your back neutral and your shoulders down.","Push one pedal down and forward while the other rises, keeping the effort in your legs rather than pulling on the bars.","Keep pedalling in a smooth, even circle at a steady cadence, breathing in rhythm with the stroke.","Adjust the resistance to hold your target effort, and continue for the desired time or distance."],"met":8.0},{"id":"step-ups","n":"Step-up","en":"Step Ups","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["gastrocnemius","gluteus_medius","hamstrings"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Mollets (gastrocnémiens), Moyen fessier, Ischio-jambiers.","ins":["Stand facing a sturdy box or bench.","Place one foot fully on the box surface.","Drive through that heel to lift your body onto the box.","Bring your trailing foot up to stand fully on the box.","Step back down leading with the same foot.","Alternate legs or complete all reps on one side before switching."],"met":5.0},{"id":"stiff-leg-deadlift","n":"Soulevé de terre jambes tendues","en":"Stiff Leg Deadlift","c":"strength","eq":"barbell","pm":["gluteus_maximus","hamstrings"],"sm":["erector_spinae","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis), Trapèzes.","ins":["Stand with feet hip-width apart, holding a barbell in front of your thighs.","Keep your legs nearly straight with only a slight knee bend.","Hinge at the hips and lower the bar along your legs.","Go as low as your hamstring flexibility allows with a flat back.","Drive through your heels to return upright.","Repeat for the desired number of reps."],"met":6.0},{"id":"straight-arm-pulldown","n":"Tirage bras tendus à la poulie","en":"Straight-Arm Pulldown","c":"strength","eq":"cable","pm":["latissimus_dorsi"],"sm":["posterior_deltoid","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — poulie. Travaille surtout : Grand dorsal. En soutien : Deltoïde postérieur, Triceps.","ins":["Stand facing a cable machine with a straight bar attached to the high pulley.","With arms nearly straight, push the bar down in an arc toward your thighs.","Squeeze your lats at the bottom.","Slowly return the bar to the starting position.","Repeat."],"met":5.0},{"id":"straight-bar-cable-front-raise","n":"Élévation frontale à la poulie barre droite","en":"Straight-Bar Cable Front Raise","c":"strength","eq":"cable","pm":["anterior_deltoid"],"sm":["lateral_deltoid","pectoralis_major"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — poulie. Travaille surtout : Deltoïde antérieur. En soutien : Deltoïde latéral, Pectoraux.","ins":["Attach a straight bar to a low cable pulley and stand facing away from the machine with the cable running forward past your legs.","Hold the bar with an overhand grip, hands about shoulder-width apart, arms hanging straight down in front of your thighs.","Keep the elbows almost straight and the core braced so the torso does not lean back.","Raise the bar forward in a smooth arc until it reaches shoulder height.","Lower it under control back to the thighs and repeat for the desired number of repetitions."],"met":5.0},{"id":"straight-bar-dips","n":"Dips à la barre droite","en":"Straight Bar Dips","c":"strength","eq":"pull_up_bar","pm":["pectoralis_major"],"sm":["triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre de traction. Travaille surtout : Pectoraux. En soutien : Triceps.","ins":["Grip a straight overhead bar with both hands, hanging with arms extended and feet off the floor.","Keeping your body straight, press down through the bar to raise your shoulders and chest.","Pause briefly at the top of the movement.","Lower back down under control to the hanging position.","Repeat for the desired number of reps."],"met":6.0},{"id":"strict-curl","n":"Curl strict","en":"Strict Curl","c":"strength","eq":"dumbbell","pm":["biceps_brachii"],"sm":["brachialis","forearm_flexors"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Biceps. En soutien : Brachial, Fléchisseurs de l'avant-bras.","ins":["Stand tall with a dumbbell in each hand, arms at your sides and palms facing forward.","Pin your elbows against your sides and brace your core so your torso cannot swing.","Curl both dumbbells up by bending only at the elbows.","Lower them under control until your arms are straight.","Repeat for the desired number of reps."],"met":5.0},{"id":"suitcase-carry","n":"Marche valise (suitcase carry)","en":"Suitcase Carry","c":"strength","eq":"kettlebell","pm":["forearm_flexors","obliques","quadratus_lumborum"],"sm":["erector_spinae","gluteus_medius","quadriceps","trapezius"],"d":"beginner","bw":false,"uni":true,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — kettlebell. Travaille surtout : Fléchisseurs de l'avant-bras, Obliques, Carré des lombes. En soutien : Lombaires (érecteurs du rachis), Moyen fessier, Quadriceps, Trapèzes. Se fait d'un côté puis de l'autre.","ins":["Stand beside a single kettlebell or dumbbell with your feet under your hips.","Hinge at the hips, take the handle in one hand and stand up with the weight hanging at your side.","Pull that shoulder down and back, and brace as if you were about to be pushed sideways.","Walk forward with normal, even strides, keeping your torso upright and square rather than leaning away from the weight.","Keep the free arm relaxed at your side instead of sticking it out as a counterweight.","Carry for the desired distance or time, set the weight down under control, then repeat on the other side."],"met":5.5},{"id":"sumo-deadlift","n":"Soulevé de terre sumo","en":"Sumo Deadlift","c":"strength","eq":"barbell","pm":["gluteus_maximus","quadriceps"],"sm":["erector_spinae","hamstrings"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre. Travaille surtout : Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Ischio-jambiers.","ins":["Stand with feet wider than shoulder-width, toes pointed outward.","Grip the bar between your legs.","Brace your core and drive through your heels to stand.","Lower under control.","Repeat."],"met":6.0},{"id":"sumo-squat","n":"Squat sumo","en":"Sumo Squat","c":"strength","eq":"barbell","pm":["gluteus_maximus","quadriceps"],"sm":["erector_spinae","gluteus_medius","hamstrings"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Grand fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Moyen fessier, Ischio-jambiers.","ins":["Stand with feet wider than shoulder-width and toes turned out.","Hold a barbell across your upper back.","Brace your core and keep your chest up.","Bend at the hips and knees to lower into a deep squat.","Drive through your heels to stand back up.","Repeat for the desired number of reps."],"met":6.0},{"id":"superman","n":"Superman","en":"Superman","c":"strength","eq":"","pm":["erector_spinae","gluteus_maximus"],"sm":["hamstrings"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Grand fessier. En soutien : Ischio-jambiers.","ins":["Lie face down with arms extended overhead.","Simultaneously lift your arms, chest, and legs off the floor.","Hold briefly at the top.","Lower under control.","Repeat."],"met":3.5},{"id":"supine-spinal-twist","n":"Torsion vertébrale allongé","en":"Supine Spinal Twist","c":"stretching","eq":"","pm":["erector_spinae","obliques"],"sm":["gluteus_maximus"],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Obliques. En soutien : Grand fessier. Se fait d'un côté puis de l'autre.","ins":["Lie on your back and bend one knee toward your chest.","Guide that knee across your body toward the floor.","Stretch your arms out wide and turn your head away.","Hold for 20 to 30 seconds, breathing steadily.","Switch sides and repeat."],"met":5.0},{"id":"supine-windshield-wipers","n":"Essuie-glaces allongé","en":"Supine Windshield Wipers","c":"strength","eq":"","pm":["obliques","rectus_abdominis"],"sm":["hip_flexors","transverse_abdominis"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique, au poids du corps. Travaille surtout : Obliques, Grand droit (abdominaux). En soutien : Fléchisseurs de hanche, Transverse.","ins":["Lie on your back with the arms out to the sides and the knees bent over the hips.","Brace the trunk so the lower back does not lift off the floor.","Lower both legs together towards one side as far as the shoulders stay down.","Bring them back through the centre and lower to the other side.","Keep alternating for the desired number of repetitions."],"met":5.0},{"id":"supported-shoulderstand","n":"Chandelle assistée","en":"Supported Shoulderstand","c":"strength","eq":"","pm":["erector_spinae","rectus_abdominis"],"sm":["gluteus_maximus","trapezius"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Grand droit (abdominaux). En soutien : Grand fessier, Trapèzes.","ins":["Lie on your back, ideally with a folded blanket under the shoulders and the head off it.","Lift the legs overhead and support the lower back with both hands, elbows shoulder-width apart.","Walk the hands up the back and stack the hips over the shoulders until the body is vertical.","Hold the position for the prescribed time, keeping the head and neck completely still.","Lower the legs overhead and roll down slowly with the hands supporting the back."],"met":5.0},{"id":"svend-press","n":"Svend press","en":"Svend Press","c":"strength","eq":"plates","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — disques. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Stand upright holding a single weight plate (or two pressed together) between your palms at chest height.","Squeeze the plates hard to generate tension through the pecs.","Press the plates straight out in front of you until the arms are fully extended.","Pause briefly, keeping the squeeze, then return the plates to the chest.","Repeat for the recommended number of repetitions."],"met":5.0},{"id":"t-bar-row","n":"Rowing T-bar","en":"T-Bar Row","c":"strength","eq":"barbell","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","erector_spinae","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Lombaires (érecteurs du rachis), Trapèzes.","ins":["Straddle the loaded T-bar with feet shoulder-width apart.","Hinge at the hips until your torso is around 45 degrees.","Grip the handles and keep your back flat.","Pull the bar up toward your chest by driving your elbows back.","Squeeze your shoulder blades at the top.","Lower the bar under control and repeat."],"met":6.0},{"id":"thoracic-bridge","n":"Pont thoracique","en":"Thoracic Bridge","c":"strength","eq":"","pm":["erector_spinae","gluteus_maximus"],"sm":["posterior_deltoid","triceps_brachii"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Grand fessier. En soutien : Deltoïde postérieur, Triceps.","ins":["Sit on the floor with knees bent and hands behind you, fingers pointing back.","Press through your hands and feet to lift your hips off the floor.","Continue pressing until your chest opens and your arms are extended.","Drop your head back and hold the position.","Breathe steadily while maintaining the bridge.","Lower back down under control."],"met":5.0},{"id":"thread-the-needle","n":"Enfiler l'aiguille","en":"Thread the Needle","c":"stretching","eq":"","pm":["posterior_deltoid","trapezius"],"sm":["erector_spinae","obliques"],"d":"beginner","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Deltoïde postérieur, Trapèzes. En soutien : Lombaires (érecteurs du rachis), Obliques. Se fait d'un côté puis de l'autre.","ins":["Start on all fours with the hands under the shoulders and the knees under the hips.","Slide one arm underneath the body, palm facing up, until the shoulder and the side of the head rest on the mat.","Keep the hips stacked over the knees and walk the top hand forward or wrap it behind the back.","Hold the twist for the prescribed time, breathing into the upper back.","Press the top hand into the floor to come up and repeat on the other side."],"met":5.0},{"id":"thread-the-needle-flow","n":"Enchaînement « enfiler l'aiguille »","en":"Thread the Needle Flow","c":"stretching","eq":"","pm":["obliques","trapezius"],"sm":["erector_spinae","posterior_deltoid"],"d":"beginner","bw":true,"uni":true,"img":["start","peak"],"desc":"Étirement, au poids du corps. Travaille surtout : Obliques, Trapèzes. En soutien : Lombaires (érecteurs du rachis), Deltoïde postérieur. Se fait d'un côté puis de l'autre.","ins":["Start on all fours with the hands under the shoulders and the knees under the hips.","Slide one arm under the body until the shoulder approaches the mat.","Reverse the motion and open that arm up towards the ceiling, following the hand with the eyes.","Return through the centre and repeat for the desired number of repetitions.","Change sides and repeat."],"met":5.0},{"id":"three-legged-dog","n":"Chien tête en bas sur trois appuis","en":"Three-Legged Downward Dog","c":"strength","eq":"","pm":["anterior_deltoid","gluteus_maximus"],"sm":["hamstrings","trapezius"],"d":"intermediate","bw":true,"uni":true,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Deltoïde antérieur, Grand fessier. En soutien : Ischio-jambiers, Trapèzes. Se fait d'un côté puis de l'autre.","ins":["Set up in downward dog with the hands shoulder-width apart and the hips high.","Press both hands evenly into the floor and shift the weight slightly forward.","Lift one leg behind you until it is in line with the spine, keeping both hip points level.","Hold the position for the prescribed time with the standing heel reaching down.","Lower the leg and repeat on the other side."],"met":5.0},{"id":"thruster","n":"Thruster","en":"Thruster","c":"strength","eq":"barbell","pm":["anterior_deltoid","quadriceps"],"sm":["gluteus_maximus","trapezius","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire dynamique — barre. Travaille surtout : Deltoïde antérieur, Quadriceps. En soutien : Grand fessier, Trapèzes, Triceps.","ins":["Hold a barbell in a front rack position with elbows high.","Stand with feet shoulder-width apart.","Squat down to parallel while keeping your torso upright.","Drive up out of the squat and press the bar overhead in one motion.","Lock out your arms at the top with the bar overhead.","Lower the bar back to the front rack and repeat."],"met":6.0},{"id":"toes-to-bar","n":"Pieds à la barre (toes to bar)","en":"Toes to Bar","c":"strength","eq":"pull_up_bar","pm":["hip_flexors","rectus_abdominis"],"sm":["forearm_flexors","latissimus_dorsi","obliques"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre de traction. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Fléchisseurs de l'avant-bras, Grand dorsal, Obliques.","ins":["Hang from a pull-up bar with an overhand grip, arms fully extended and body still.","Engage your lats and core to prevent swinging.","Raise your legs with straight knees, reaching your toes up toward the bar.","Touch the bar with your toes, then lower your legs under control.","Repeat for the desired reps."],"met":6.0},{"id":"torso-twists","n":"Rotations du buste","en":"Torso Twists","c":"stretching","eq":"","pm":["obliques","transverse_abdominis"],"sm":["erector_spinae"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Obliques, Transverse. En soutien : Lombaires (érecteurs du rachis).","ins":["Stand with the feet about shoulder-width apart and the knees softly bent.","Brace lightly and hold the hands together in front of the chest.","Rotate the rib cage to one side without shifting the feet.","Return through centre and rotate to the other side.","Continue alternating smoothly through a comfortable range."],"met":3.5},{"id":"treadmill-running","n":"Course sur tapis","en":"Treadmill Running","c":"cardio","eq":"treadmill","pm":["gastrocnemius","quadriceps"],"sm":["gluteus_maximus","hamstrings","hip_flexors","soleus"],"d":"beginner","bw":false,"uni":false,"img":["main"],"desc":"Exercice cardio — tapis de course. Travaille surtout : Mollets (gastrocnémiens), Quadriceps. En soutien : Grand fessier, Ischio-jambiers, Fléchisseurs de hanche, Soléaire.","ins":["Step onto the treadmill with a foot on each side rail, start the belt at a walking speed and step on once it is moving.","Build up to your running pace, landing under your hips rather than reaching out in front of you.","Run tall with your shoulders relaxed, your elbows bent at about ninety degrees and your arms swinging forward and back, not across your body.","Keep your eyes forward and stay in the middle of the belt instead of drifting back toward the rear roller.","Hold the pace for the desired time or distance, then slow the belt and walk for a few minutes before stepping off."],"met":8.0},{"id":"tree-pose","n":"Posture de l'arbre","en":"Tree Pose","c":"strength","eq":"","pm":["gluteus_medius","quadriceps"],"sm":["erector_spinae","soleus"],"d":"intermediate","bw":true,"uni":true,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Moyen fessier, Quadriceps. En soutien : Lombaires (érecteurs du rachis), Soléaire. Se fait d'un côté puis de l'autre.","ins":["Stand tall and shift the weight onto one foot.","Place the sole of the other foot on the inner calf or the inner thigh, avoiding the knee.","Press the foot and the leg into each other and level the hips.","Bring the hands to the chest or overhead and hold for the prescribed time.","Lower the foot and repeat on the other side."],"met":5.0},{"id":"triangle-pose","n":"Posture du triangle","en":"Triangle Pose","c":"stretching","eq":"","pm":["hamstrings","obliques"],"sm":["adductors","gluteus_medius"],"d":"intermediate","bw":true,"uni":true,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Ischio-jambiers, Obliques. En soutien : Adducteurs, Moyen fessier. Se fait d'un côté puis de l'autre.","ins":["Stand wide with the front foot turned out and the back foot angled slightly in.","Keep both legs straight and reach the front hand forward as the hips shift back.","Tilt sideways and bring the bottom hand to the shin, a block or the floor, top arm reaching up.","Hold the position for the prescribed time, turning the chest towards the ceiling.","Press into the feet to come up and repeat on the other side."],"met":5.0},{"id":"tricep-kickback","n":"Kickback triceps à l'haltère","en":"Dumbbell Tricep Kickback","c":"strength","eq":"dumbbell","pm":["triceps_brachii"],"sm":[],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — haltères. Travaille surtout : Triceps. Se fait d'un côté puis de l'autre.","ins":["Hinge forward at the hips, holding a dumbbell with elbow bent at 90 degrees.","Extend your arm straight back, squeezing the tricep.","Hold briefly at full extension.","Lower with control.","Repeat on both sides."],"met":5.0},{"id":"tricep-pushdown","n":"Extension triceps à la poulie (pushdown)","en":"Cable Tricep Pushdown","c":"strength","eq":"cable","pm":["triceps_brachii"],"sm":[],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — poulie. Travaille surtout : Triceps.","ins":["Stand facing a cable machine with a straight bar attachment.","Grip the bar and pin your elbows to your sides.","Push the bar down until your arms are fully extended.","Slowly return to the starting position.","Repeat."],"met":5.0},{"id":"trx-bicep-curl","n":"Curl biceps au TRX","en":"TRX Bicep Curl","c":"strength","eq":"suspension_trainer","pm":["biceps_brachii"],"sm":["brachialis","brachioradialis"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — tRX / sangles. Travaille surtout : Biceps. En soutien : Brachial, Brachio-radial.","ins":["Adjust the suspension trainer straps to a medium length.","Stand facing the anchor point, grasp the handles with an underhand grip, and lean back until your arms are fully extended.","Keep your body straight and core engaged, pull your chest towards your hands by bending your elbows.","Squeeze your biceps at the top of the movement.","Slowly extend your arms back to the starting position, controlling the descent.","Maintain tension throughout the set."],"met":5.0},{"id":"trx-chest-press","n":"Développé pectoraux au TRX","en":"TRX Chest Press","c":"strength","eq":"suspension_trainer","pm":["pectoralis_major"],"sm":["anterior_deltoid","rectus_abdominis","triceps_brachii"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — tRX / sangles. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Grand droit (abdominaux), Triceps.","ins":["Adjust the suspension trainer handles to mid-calf height.","Stand facing away from the anchor point, holding a handle in each hand, arms extended.","Lean forward into a plank position, keeping your body straight from head to heels.","Lower your chest towards your hands by bending your elbows, maintaining tension in the straps.","Press back up to the starting position, fully extending your arms and squeezing your chest."],"met":6.0},{"id":"trx-face-pull","n":"Face pull au TRX","en":"TRX Face Pull","c":"strength","eq":"suspension_trainer","pm":["posterior_deltoid","rhomboids"],"sm":["trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — tRX / sangles. Travaille surtout : Deltoïde postérieur, Rhomboïdes. En soutien : Trapèzes.","ins":["Grasp the TRX handles with an overhand grip, palms facing down.","Lean back until your arms are fully extended and your body forms a straight line.","Pull the handles towards your face, driving your elbows high and wide.","Squeeze your shoulder blades together at the peak contraction.","Slowly extend your arms back to the starting position with control."],"met":6.0},{"id":"trx-hamstring-curl","n":"Leg curl au TRX","en":"TRX Hamstring Curl","c":"strength","eq":"suspension_trainer","pm":["hamstrings"],"sm":["gastrocnemius","gluteus_maximus"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — tRX / sangles. Travaille surtout : Ischio-jambiers. En soutien : Mollets (gastrocnémiens), Grand fessier.","ins":["Lie on your back with heels in the suspension trainer cradles, knees bent at 90 degrees.","Lift your hips off the floor, creating a straight line from knees to shoulders.","Extend your legs forward, maintaining hip elevation and core tension.","Pull your heels back towards your glutes, contracting your hamstrings forcefully.","Control the movement, avoiding any drop in hip height throughout the set."],"met":5.0},{"id":"trx-lunge","n":"Fente au TRX","en":"TRX Lunge","c":"strength","eq":"suspension_trainer","pm":["gluteus_maximus","quadriceps"],"sm":["gluteus_medius","hamstrings"],"d":"beginner","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — tRX / sangles. Travaille surtout : Grand fessier, Quadriceps. En soutien : Moyen fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Stand facing away from the anchor point, holding the suspension trainer handles in front of you.","Place one foot into both foot cradles, extending the leg behind you.","Brace your core and lower your body by bending the front knee, keeping your torso upright.","Descend until your front thigh is parallel to the floor or just below, maintaining tension on the suspension trainer.","Drive through your front heel to return to the starting position, extending the front leg.","Complete all reps on one side, then switch legs and repeat per side."],"met":6.0},{"id":"trx-pistol-squat","n":"Pistol squat au TRX","en":"TRX Pistol Squat","c":"strength","eq":"suspension_trainer","pm":["gluteus_maximus","quadriceps"],"sm":["gluteus_medius","hamstrings"],"d":"intermediate","bw":false,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — tRX / sangles. Travaille surtout : Grand fessier, Quadriceps. En soutien : Moyen fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Anchor the suspension trainer and hold the handles with both hands, arms extended.","Stand tall, lift one leg straight out in front of you, keeping it off the ground.","Initiate the squat by pushing your hips back and bending the standing knee, lowering your body as deep as possible.","Keep your chest up, back straight, and use the TRX for balance and support as needed.","Drive through your heel to return to the starting position, extending the standing leg fully.","Complete all reps on one side before switching to the other."],"met":6.0},{"id":"trx-plank","n":"Gainage au TRX","en":"TRX Plank","c":"strength","eq":"suspension_trainer","pm":["rectus_abdominis","transverse_abdominis"],"sm":["anterior_deltoid","obliques"],"d":"intermediate","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — tRX / sangles. Travaille surtout : Grand droit (abdominaux), Transverse. En soutien : Deltoïde antérieur, Obliques.","ins":["Place both feet in the TRX foot cradles.","Assume a forearm or high plank position on the floor.","Keep your body in a straight line from head to heels.","Brace your core and squeeze your glutes.","Hold the position for the desired time.","Lower your knees to exit safely."],"met":6.0},{"id":"trx-row","n":"Rowing au TRX","en":"TRX Row","c":"strength","eq":"suspension_trainer","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","posterior_deltoid","trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — tRX / sangles. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Deltoïde postérieur, Trapèzes.","ins":["Grasp the handles of a suspension trainer with an overhand grip, palms facing each other.","Lean back, extending your arms fully, keeping your body straight from head to heels.","Engage your core and pull your chest towards your hands, squeezing your shoulder blades together.","Pause briefly at the top, then slowly lower yourself back to the starting position with control.","Maintain a rigid body throughout the movement, avoiding any sagging in the hips."],"met":6.0},{"id":"trx-side-plank","n":"Gainage latéral au TRX","en":"TRX Side Plank","c":"strength","eq":"suspension_trainer","pm":["obliques","transverse_abdominis"],"sm":["gluteus_medius","lateral_deltoid"],"d":"intermediate","bw":false,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique — tRX / sangles. Travaille surtout : Obliques, Transverse. En soutien : Moyen fessier, Deltoïde latéral.","ins":["Place both feet in the TRX foot cradles and lie on your side.","Prop up on your bottom forearm with your elbow under your shoulder.","Lift your hips so your body forms a straight line.","Stack your top foot over the bottom foot.","Hold the position while breathing steadily.","Lower and switch sides after the set."],"met":6.0},{"id":"trx-squat","n":"Squat au TRX","en":"TRX Squat","c":"strength","eq":"suspension_trainer","pm":["gluteus_maximus","quadriceps"],"sm":["hamstrings"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — tRX / sangles. Travaille surtout : Grand fessier, Quadriceps. En soutien : Ischio-jambiers.","ins":["Stand facing the anchor point, holding the handles with palms facing each other, arms extended.","Lean back slightly, keeping your body straight and core engaged, with feet shoulder-width apart.","Initiate the squat by pushing your hips back and bending your knees, lowering your body as if sitting in a chair.","Descend until your thighs are parallel to the floor or as deep as comfortable, maintaining tension on the straps.","Drive through your heels to return to the starting position, extending your hips and knees fully."],"met":6.0},{"id":"trx-tricep-extension","n":"Extension triceps au TRX","en":"TRX Triceps Extension","c":"strength","eq":"suspension_trainer","pm":["triceps_brachii"],"sm":[],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — tRX / sangles. Travaille surtout : Triceps.","ins":["Stand facing the anchor point, holding the TRX handles with an overhand grip, palms facing down.","Lean forward, extending your arms straight out in front of you at shoulder height, creating tension in the straps.","Keeping your elbows high and fixed, bend them to lower your body by letting your hands move towards your temples.","Extend your elbows forcefully to push your body back to the starting position, squeezing your triceps.","Maintain a rigid plank position throughout the movement, engaging your core and glutes."],"met":5.0},{"id":"trx-y-fly","n":"Écartés en Y au TRX","en":"TRX Y-Fly","c":"strength","eq":"suspension_trainer","pm":["posterior_deltoid","trapezius"],"sm":["lateral_deltoid","rhomboids"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — tRX / sangles. Travaille surtout : Deltoïde postérieur, Trapèzes. En soutien : Deltoïde latéral, Rhomboïdes.","ins":["Stand facing the anchor point, holding the handles with an overhand grip, palms facing each other.","Lean back, extending your arms straight in front of you, maintaining a plank position with your body.","Initiate the movement by pulling your shoulder blades together and down, forming a 'Y' shape with your body.","Keep your arms straight and elbows slightly bent, squeezing your shoulder blades at the top.","Slowly control the descent back to the starting position, resisting the pull of the straps."],"met":5.0},{"id":"upright-row","n":"Rowing menton à la barre","en":"Barbell Upright Row","c":"strength","eq":"barbell","pm":["lateral_deltoid","trapezius"],"sm":["anterior_deltoid","biceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre. Travaille surtout : Deltoïde latéral, Trapèzes. En soutien : Deltoïde antérieur, Biceps.","ins":["Stand holding a barbell with a shoulder-width overhand grip.","Pull the bar straight up along your body toward your chin.","Lead with your elbows, keeping them above your hands.","Lower the bar with control.","Repeat."],"met":6.0},{"id":"upward-dog","n":"Chien tête en haut","en":"Upward-Facing Dog","c":"stretching","eq":"","pm":["erector_spinae","triceps_brachii"],"sm":["gluteus_maximus","pectoralis_major"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Lombaires (érecteurs du rachis), Triceps. En soutien : Grand fessier, Pectoraux.","ins":["Lie face down with the hands beside the lower ribs and the tops of the feet on the floor.","Press the hands down and straighten the arms, lifting the chest and then the thighs off the mat.","Draw the shoulders back and down and keep the neck long.","Hold the position for the prescribed time with only the hands and the tops of the feet on the floor.","Bend the arms and lower down under control."],"met":5.0},{"id":"v-bar-lat-pulldown","n":"Tirage vertical poignée en V","en":"V-Bar Lat Pulldown","c":"strength","eq":"lat_pulldown_machine","pm":["latissimus_dorsi"],"sm":["biceps_brachii","rhomboids","trapezius"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — machine tirage vertical. Travaille surtout : Grand dorsal. En soutien : Biceps, Rhomboïdes, Trapèzes.","ins":["Attach a V-bar (double-D handle) to a lat pulldown cable.","Sit with the thighs secured under the pad and grip the handle, palms facing each other.","Begin with the arms fully extended overhead.","Pull the handle down to the sternum by driving the elbows down and slightly back.","Squeeze the lats at the bottom, then return slowly under control.","Repeat for the recommended number of repetitions."],"met":6.0},{"id":"v-bar-tricep-pushdown","n":"Extension triceps poignée en V à la poulie","en":"V-Bar Tricep Pushdown","c":"strength","eq":"cable","pm":["triceps_brachii"],"sm":[],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de poussée — poulie. Travaille surtout : Triceps.","ins":["Attach a V-bar handle to a high cable pulley.","Stand facing the stack and grip the V-bar with both hands, palms down.","Start with the elbows tucked to the sides, forearms parallel to the floor.","Press the handle down until the arms are fully extended.","Squeeze the triceps, then return under control to the starting position.","Repeat for the recommended number of repetitions."],"met":5.0},{"id":"v-sit","n":"V-sit","en":"V-Sit","c":"strength","eq":"","pm":["hip_flexors","rectus_abdominis"],"sm":["obliques","quadriceps"],"d":"intermediate","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Obliques, Quadriceps.","ins":["Sit on the floor with your legs extended in front of you.","Lean back slightly and lift your legs off the floor.","Reach your arms forward so your body forms a V shape.","Balance on your sit bones with core tight.","Hold the position while breathing steadily.","Lower your legs and torso to exit."],"met":5.0},{"id":"v-ups","n":"V-ups","en":"V Ups","c":"strength","eq":"","pm":["hip_flexors","rectus_abdominis"],"sm":["obliques","transverse_abdominis"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Fléchisseurs de hanche, Grand droit (abdominaux). En soutien : Obliques, Transverse.","ins":["Lie flat on your back with arms extended overhead and legs straight.","Simultaneously raise your legs and upper body toward each other.","Reach your hands toward your feet at the top, forming a V shape.","Keep your legs straight throughout the movement.","Lower both ends under control back to the floor.","Repeat for the desired number of reps."],"met":5.0},{"id":"walking","n":"Marche","en":"Walking","c":"cardio","eq":"","pm":["gastrocnemius","quadriceps"],"sm":["gluteus_maximus","hamstrings","hip_flexors","soleus"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Exercice cardio, au poids du corps. Travaille surtout : Mollets (gastrocnémiens), Quadriceps. En soutien : Grand fessier, Ischio-jambiers, Fléchisseurs de hanche, Soléaire.","ins":["Stand tall with your weight over the middle of your feet and your shoulders relaxed, not pulled back.","Step forward and land on your heel, then roll through the foot and push off the ball and toes.","Keep at least one foot on the ground at all times — as soon as both leave the floor you are running, not walking.","Let your arms swing naturally from the shoulder, opposite arm to opposite leg, with the elbows softly bent.","Look ahead rather than down at your feet, and breathe through a steady, repeatable rhythm.","Continue for the desired time or distance, picking a pace at which you could still hold a conversation."],"met":3.5},{"id":"walking-lunge","n":"Fentes marchées","en":"Walking Lunge","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["gluteus_medius","hamstrings"],"d":"intermediate","bw":true,"uni":true,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Moyen fessier, Ischio-jambiers. Se fait d'un côté puis de l'autre.","ins":["Stand tall with feet hip-width apart and hands on hips.","Step one foot forward into a long lunge.","Lower until both knees are around 90 degrees.","Drive through the front heel and step the back foot forward.","Continue alternating legs as you walk forward.","Repeat for the desired number of reps."],"met":5.0},{"id":"wall-push-ups","n":"Pompes contre le mur","en":"Wall Push Ups","c":"strength","eq":"","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"beginner","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Stand facing a wall and place your palms on it at shoulder height.","Step your feet back until your arms are fully extended.","Bend your elbows to bring your chest toward the wall.","Keep your body in a straight line throughout.","Press back to the starting position.","Repeat for the desired number of reps."],"met":5.0},{"id":"wall-sit","n":"Chaise contre le mur","en":"Wall Sit","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["hamstrings"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Ischio-jambiers.","ins":["Stand with back against a wall.","Slide down until thighs are parallel to the floor.","Hold the position.","Stand back up when done."],"met":5.0},{"id":"warrior-one","n":"Guerrier I","en":"Warrior I","c":"strength","eq":"","pm":["gluteus_maximus","quadriceps"],"sm":["anterior_deltoid","erector_spinae"],"d":"intermediate","bw":true,"uni":true,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Grand fessier, Quadriceps. En soutien : Deltoïde antérieur, Lombaires (érecteurs du rachis). Se fait d'un côté puis de l'autre.","ins":["Step one foot back and turn it out about forty-five degrees, planting the whole sole.","Bend the front knee until it stacks over the ankle and keep the back leg straight.","Draw both hip points towards the front of the mat and lift the arms overhead.","Hold the position for the prescribed time with the ribs down and the chest lifted.","Step the feet together and repeat on the other side."],"met":5.0},{"id":"warrior-three","n":"Guerrier III","en":"Warrior III","c":"strength","eq":"","pm":["gluteus_maximus","hamstrings"],"sm":["erector_spinae","gluteus_medius"],"d":"intermediate","bw":true,"uni":true,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Grand fessier, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis), Moyen fessier. Se fait d'un côté puis de l'autre.","ins":["Stand on one leg with the knee soft and the hips level.","Hinge forward from the hips as the other leg lifts behind you.","Continue until the torso and the lifted leg are roughly parallel to the floor.","Reach the arms forward, back along the body or out to the sides, and hold for the prescribed time.","Lower the leg and repeat on the other side."],"met":5.0},{"id":"warrior-two","n":"Guerrier II","en":"Warrior II","c":"strength","eq":"","pm":["gluteus_medius","quadriceps"],"sm":["adductors","lateral_deltoid"],"d":"intermediate","bw":true,"uni":true,"img":["main"],"desc":"Exercice de musculation polyarticulaire statique, au poids du corps. Travaille surtout : Moyen fessier, Quadriceps. En soutien : Adducteurs, Deltoïde latéral. Se fait d'un côté puis de l'autre.","ins":["Stand wide with the front foot turned out ninety degrees and the back foot slightly in.","Bend the front knee until it stacks over the ankle and tracks towards the middle toes.","Open the hips and chest to the side and extend the arms parallel to the floor.","Hold the position for the prescribed time, gazing over the front hand.","Straighten the front leg and repeat on the other side."],"met":5.0},{"id":"weighted-dips","n":"Dips lestés","en":"Weighted Dips","c":"strength","eq":"dip_station","pm":["pectoralis_major","triceps_brachii"],"sm":["anterior_deltoid"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — station de dips. Travaille surtout : Pectoraux, Triceps. En soutien : Deltoïde antérieur.","ins":["Attach a plate to a dip belt around your waist so the weight hangs between your legs.","Grip the parallel dip bars and press yourself up to the top position with your arms locked out and your feet off the floor.","Lean your torso slightly forward and lower your body by bending your elbows until your shoulders are below them.","Press back up through your palms until your arms are locked out again, keeping the hanging plate from swinging.","Repeat for the desired number of reps."],"met":6.0},{"id":"weighted-pull-up","n":"Tractions lestées","en":"Weighted Pull-Up","c":"strength","eq":"pull_up_bar","pm":["latissimus_dorsi"],"sm":["biceps_brachii","posterior_deltoid","rhomboids","trapezius"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre de traction. Travaille surtout : Grand dorsal. En soutien : Biceps, Deltoïde postérieur, Rhomboïdes, Trapèzes.","ins":["Attach a plate to a dip belt around your waist so the weight hangs between your legs, or hold the load between your feet.","Grip the pull-up bar with an overhand grip slightly wider than shoulder-width and hang at full arm extension with your legs together.","Pull your elbows down and back to drive your chest toward the bar until your chin clears it.","Lower yourself under control back to the full dead hang, keeping tension on your lats and letting the weight settle before the next rep.","Repeat for the desired number of reps."],"met":6.0},{"id":"weighted-wall-crunch","n":"Crunch lesté contre le mur","en":"Weighted Wall Crunch","c":"strength","eq":"plates","pm":["rectus_abdominis"],"sm":["obliques"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — disques. Travaille surtout : Grand droit (abdominaux). En soutien : Obliques.","ins":["Lie on your back and park your legs so your hips cannot help: brace your feet against a wall or a box, or hold your legs up with the knees bent.","Hold a weight against your chest with both hands -- a plate, a dumbbell, or a kettlebell all work.","Crunch up, lifting your shoulder blades off the floor.","Lower with control.","Repeat."],"met":5.0},{"id":"wide-grip-bench-press","n":"Développé couché prise large","en":"Wide-Grip Bench Press","c":"strength","eq":"barbell","pm":["pectoralis_major"],"sm":["anterior_deltoid","triceps_brachii"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Triceps.","ins":["Lie on a flat bench. Grip the barbell wider than shoulder-width.","Lower the bar to mid-chest.","Press back up to full extension.","Repeat."],"met":6.0},{"id":"wide-grip-pull-ups","n":"Tractions prise large","en":"Wide Grip Pull Ups","c":"strength","eq":"pull_up_bar","pm":["latissimus_dorsi"],"sm":["biceps_brachii","posterior_deltoid","rhomboids","trapezius"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — barre de traction. Travaille surtout : Grand dorsal. En soutien : Biceps, Deltoïde postérieur, Rhomboïdes, Trapèzes.","ins":["Grip the pull-up bar with an overhand grip wider than shoulder-width.","Hang with arms fully extended and core braced.","Pull your chest toward the bar by driving your elbows down.","Keep your shoulders pulled back as you rise.","Lower yourself under control to full extension.","Repeat for the desired number of reps."],"met":6.0},{"id":"wide-grip-push-ups","n":"Pompes prise large","en":"Wide Grip Push Ups","c":"strength","eq":"","pm":["pectoralis_major"],"sm":["anterior_deltoid","serratus_anterior","triceps_brachii"],"d":"intermediate","bw":true,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée, au poids du corps. Travaille surtout : Pectoraux. En soutien : Deltoïde antérieur, Dentelé antérieur, Triceps.","ins":["Start in a high plank with hands wider than shoulder-width.","Keep your body in a straight line from head to heels.","Lower your chest toward the floor by bending your elbows.","Keep your core braced and glutes engaged.","Press back up until your arms are extended.","Repeat for the desired number of reps."],"met":5.0},{"id":"wide-grip-seated-cable-row","n":"Rowing assis prise large à la poulie","en":"Wide Grip Seated Cable Row","c":"strength","eq":"cable","pm":["latissimus_dorsi","rhomboids"],"sm":["biceps_brachii","posterior_deltoid"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de tirage — poulie. Travaille surtout : Grand dorsal, Rhomboïdes. En soutien : Biceps, Deltoïde postérieur.","ins":["Sit at a cable row station with feet on the platform.","Grip a wide bar with an overhand grip.","Pull the bar toward your upper abdomen, squeezing your shoulder blades.","Extend your arms back to the starting position with control.","Repeat."],"met":6.0},{"id":"wide-legged-forward-fold","n":"Flexion avant jambes écartées","en":"Wide-Legged Forward Fold","c":"stretching","eq":"","pm":["adductors","hamstrings"],"sm":["erector_spinae","gastrocnemius"],"d":"beginner","bw":true,"uni":false,"img":["main"],"desc":"Étirement, au poids du corps. Travaille surtout : Adducteurs, Ischio-jambiers. En soutien : Lombaires (érecteurs du rachis), Mollets (gastrocnémiens).","ins":["Stand with the feet wide apart and the outer edges parallel.","Place the hands on the hips, lift the chest and hinge forward from the hip joints.","Bring the hands to the floor under the shoulders and let the head hang.","Hold the fold for the prescribed time, shifting the weight slightly into the balls of the feet.","Bring the hands back to the hips and come up with a flat back."],"met":5.0},{"id":"wide-stance-leg-press","n":"Presse à cuisses pieds écartés","en":"Wide-Stance Leg Press","c":"strength","eq":"leg_press","pm":["adductors"],"sm":["gluteus_maximus","hamstrings","quadriceps"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — presse à cuisses. Travaille surtout : Adducteurs. En soutien : Grand fessier, Ischio-jambiers, Quadriceps.","ins":["Set the back pad and seat so your lower back remains supported at the bottom of the repetition.","Place your feet wide on the platform with the toes turned out only as far as the knees can follow comfortably.","Lower the sled by bending the hips and knees while keeping the knees aligned with the toes and the feet flat.","Press through the whole foot and extend the hips and knees without forcing the knees into lockout.","Lower the sled under control and repeat for the desired number of repetitions."],"met":6.0},{"id":"wrist-curl","n":"Curl poignets aux deux haltères","en":"Bilateral Dumbbell Wrist Curl","c":"strength","eq":"dumbbell","pm":["forearm_flexors"],"sm":["brachioradialis"],"d":"beginner","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Fléchisseurs de l'avant-bras. En soutien : Brachio-radial.","ins":["Sit on a bench holding a dumbbell in each hand, forearms resting on your thighs, palms up.","Let both dumbbells roll down to your fingertips.","Curl both dumbbells up by flexing your wrists.","Squeeze at the top, then lower under control.","Repeat for the desired number of reps."],"met":5.0},{"id":"wrist-roller","n":"Rouleau à poignets","en":"Wrist Roller","c":"strength","eq":"wrist_roller","pm":["forearm_extensors","forearm_flexors"],"sm":["anterior_deltoid"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — rouleau à poignets. Travaille surtout : Extenseurs de l'avant-bras, Fléchisseurs de l'avant-bras. En soutien : Deltoïde antérieur.","ins":["Grip the wrist roller handle with arms extended in front at shoulder height.","Let the weight hang from the cord.","Roll the handle forward with alternating wrist movements to wind the weight up.","Keep your arms straight throughout.","Once fully wound, reverse the rotation to lower the weight.","Repeat for the desired number of reps."],"met":6.0},{"id":"zercher-squat","n":"Squat Zercher","en":"Zercher Squat","c":"strength","eq":"barbell","pm":["gluteus_maximus","quadriceps"],"sm":["biceps_brachii","erector_spinae","hamstrings"],"d":"advanced","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation polyarticulaire de poussée — barre. Travaille surtout : Grand fessier, Quadriceps. En soutien : Biceps, Lombaires (érecteurs du rachis), Ischio-jambiers.","ins":["Set a barbell in a rack at about waist height, step in and hook it into the crooks of the elbows, with the forearms crossed or the hands clasped in front of the chest.","Lift the bar out of the rack, step back and stand with the feet about shoulder-width apart.","Brace the core and keep the chest up and the elbows pressed together.","Squat down by bending the hips and knees until the thighs are at least parallel to the floor.","Drive through the middle of the feet to stand back up.","Repeat for the desired number of repetitions, then re-rack the bar."],"met":6.0},{"id":"zottman-curl","n":"Curl Zottman","en":"Zottman Curl","c":"strength","eq":"dumbbell","pm":["biceps_brachii"],"sm":["brachialis","brachioradialis","forearm_extensors"],"d":"intermediate","bw":false,"uni":false,"img":["start","peak"],"desc":"Exercice de musculation d'isolation de tirage — haltères. Travaille surtout : Biceps. En soutien : Brachial, Brachio-radial, Extenseurs de l'avant-bras.","ins":["Stand with your feet about hip-width apart, arms extended at your sides, and a dumbbell in each hand with the palms facing forward.","Keep your upper arms beside your ribs and curl both dumbbells toward your shoulders without swinging the torso.","At the top, keep the elbows bent and rotate the forearms until the palms face down.","Lower the dumbbells slowly with the pronated grip until the arms are straight.","Turn the palms forward again at the bottom and repeat for the desired number of repetitions."],"met":5.0}];
